def fetch_agave_task(task_id, auth=None):
    kwargs = {"timeout": 30}
    resolved_auth = auth
    if resolved_auth is None:
        try:
            resolved_auth = _current_user_jita_auth() or globals().get("JITA_SVC_AUTH")
        except RuntimeError:
            resolved_auth = globals().get("JITA_SVC_AUTH")
    if resolved_auth:
        kwargs["auth"] = resolved_auth
    resp = session.get(f"{JITA_BASE}/agave_tasks/{task_id}", **kwargs)
    resp.raise_for_status()
    payload = resp.json() if resp is not None else {}
    if isinstance(payload, dict) and isinstance(payload.get("data"), dict):
        return payload.get("data") or {}
    return payload if isinstance(payload, dict) else {}


def nutest_branch_from_agave_task(task):
    """Return JITA nutest-py3-tests_branch (or nested framework branch)."""
    if not isinstance(task, dict):
        return ""
    for key in ("nutest-py3-tests_branch", "nutest_py3_tests_branch", "nutest_branch"):
        val = str(task.get(key) or "").strip()
        if val:
            return val
    framework = str(task.get("test_framework") or "nutest-py3-tests").strip() or "nutest-py3-tests"
    keyed = str(task.get("%s_branch" % framework) or "").strip()
    if keyed:
        return keyed
    tfm = task.get("test_framework_metadata")
    if isinstance(tfm, dict):
        for nested_key in ("framework", "test"):
            nested = tfm.get(nested_key)
            if isinstance(nested, dict):
                val = str(nested.get("branch") or "").strip()
                if val:
                    return val
    return ""

# ======================================================
# Flask Endpoint
# ======================================================
def fetch_test_results_batch_with_pagination(task_ids, limit=2000, timeout=120, merge=True):
    """
    Fetch test results for multiple tasks in batch.

    Args:
        task_ids: List of task IDs to fetch results for
        limit: Number of results to fetch (default: 2000)
        timeout: Request timeout in seconds (default: 120)
        merge: If True (default), JITA merges duplicate testcases across tasks.
               Handover / JITA analysis needs merge=False to count per-run passes.

    Returns:
        List of test results

    Raises:
        requests.exceptions.Timeout: If request times out
        requests.exceptions.RequestException: For other request errors
    """
    if not task_ids:
        return []
    
    # Increase timeout for large task sets (more than 50 tasks)
    if len(task_ids) > 50:
        timeout = max(timeout, 180)  # At least 3 minutes for large sets
    
    logger.info(
        f"Fetching test results for {len(task_ids)} tasks "
        f"(timeout: {timeout}s, limit: {limit}, merge={bool(merge)})"
    )
    
    # Correct payload structure: raw_query + merge at top level
    payload = {
        "raw_query": {
            "agave_task_id": {
                "$in": [{"$oid": tid} for tid in task_ids]
            }
        },
        "only": (
            "_id,test,status,agave_task_id,jira_tickets,triaged_by,exception_summary,"
            "test_log_url,comments"
        ),
        "start": 0,
        "limit": limit,
        "sort": "agave_task_id,status",
        "merge": bool(merge),
    }
    
    # Log payload for verification
    #logger.info(f"[agave_test_results API] Payload: {json.dumps(payload, indent=2)}")
    #logger.info(f"[agave_test_results API] merge parameter: {payload.get('merge')}")
    logger.info(f"[agave_test_results API] Number of task_ids in query: {len(task_ids)}")
    
    try:
        resp = session.post(
            f"{JITA_BASE}/reports/agave_test_results",
            json=payload,
            timeout=timeout
        )
        
        resp.raise_for_status()
        response_data = resp.json()
        results = response_data.get("data", [])
        total = response_data.get("total", 0)
        
        # Log response info
        logger.info(f"[agave_test_results API] Response - Total: {total}, Returned: {len(results)}, Merge enabled: {payload.get('merge')}")
        if results:
            # Log sample test names to verify merge (first 3 unique test names)
            sample_tests = []
            seen_sample = set()
            for r in results:
                test_name = r.get("test", {}).get("name", "")
                if test_name and test_name not in seen_sample and len(sample_tests) < 3:
                    sample_tests.append(test_name)
                    seen_sample.add(test_name)
            logger.info(f"[agave_test_results API] Sample test names (first 3 unique): {sample_tests}")
        
        logger.info(f"Fetched {len(results)} merged test results from {len(task_ids)} tasks")
        return results
        
    except requests.exceptions.Timeout as e:
        logger.error(f"Timeout fetching test results: {e}")
        raise requests.exceptions.Timeout(
            f"Request timed out after {timeout}s while fetching test results. "
            f"This may be due to a large number of tasks ({len(task_ids)}). "
            f"Try reducing the number of tasks or increasing the timeout."
        ) from e
    except requests.exceptions.RequestException as e:
        logger.error(f"Error fetching test results: {e}")
        raise

