def _build_eng_ticket_summary(ticket_ctx):
    explicit = (ticket_ctx.get("summary") or "").strip()
    if explicit:
        return explicit[:255]
    testcase = (ticket_ctx.get("testcase_name") or "").strip()
    root = re.sub(r"\s+", " ", (ticket_ctx.get("root_cause") or "").strip())
    short_root = root[:140] if root else "Failed testcase triage"
    short_tc = testcase.split(".")[-1] if testcase else "testcase"
    return f"{short_tc} — {short_root}"[:255]


def _oid_str(value):
    if isinstance(value, dict) and value.get("$oid"):
        return str(value["$oid"]).strip()
    if value is None:
        return ""
    return str(value).strip()


def _parse_jita_log_url_parts(test_log_url):
    """
    Parse task/result ids + lab/infra from a JITA test_log_url.
    Supports both API proxy URLs and raw /logs/<task>/<result>/ paths.
    """
    url = (test_log_url or "").strip()
    out = {"task_id": "", "result_dir": "", "lab": "phx1", "infra": "nutest", "raw_path": ""}
    if not url:
        return out
    m = re.search(r"[?&]lab=([^&]+)", url, flags=re.I)
    if m:
        out["lab"] = m.group(1)
    m = re.search(r"[?&]infra=([^&]+)", url, flags=re.I)
    if m:
        out["infra"] = m.group(1)
    m = re.search(r"(?:[?&]url=)?(/logs/([a-f0-9]{24})/([a-f0-9]{24}))", url, flags=re.I)
    if not m:
        m = re.search(r"/logs/([a-f0-9]{24})/([a-f0-9]{24})", url, flags=re.I)
        if m:
            out["task_id"] = m.group(1)
            out["result_dir"] = m.group(2)
            out["raw_path"] = f"/logs/{m.group(1)}/{m.group(2)}"
            return out
        return out
    out["raw_path"] = m.group(1)
    out["task_id"] = m.group(2)
    out["result_dir"] = m.group(3)
    return out


def _jita_api_log_url(path_under_logs, lab="phx1", infra="nutest"):
    path = (path_under_logs or "").strip()
    if not path.startswith("/"):
        path = "/" + path
    return (
        f"https://jita.eng.nutanix.com/api/v2/log?log_type=test_log"
        f"&url={path}&lab={lab}&infra={infra}"
    )


def _build_eng_ticket_links(ticket_ctx):
    """Build Triage-Genie-style Jita / Log / Triage Genie / Triage Genie JSON links."""
    testcase = (ticket_ctx.get("testcase_name") or "").strip()
    test_log_url = (ticket_ctx.get("test_log_url") or "").strip()
    task_id = (
        _oid_str(ticket_ctx.get("agave_task_id"))
        or _oid_str(ticket_ctx.get("task_id"))
        or ""
    )
    result_id = (
        _oid_str(ticket_ctx.get("testcase_id"))
        or _oid_str(ticket_ctx.get("test_result_id"))
        or ""
    )
    parts = _parse_jita_log_url_parts(test_log_url)
    if not task_id:
        task_id = parts.get("task_id") or ""
    lab = parts.get("lab") or "phx1"
    infra = parts.get("infra") or "nutest"
    raw_path = parts.get("raw_path") or ""
    if not raw_path and task_id and parts.get("result_dir"):
        raw_path = f"/logs/{task_id}/{parts['result_dir']}"
    if not raw_path and task_id and result_id:
        # Fallback: some runs use result id as log dir.
        raw_path = f"/logs/{task_id}/{result_id}"

    log_link = ""
    if test_log_url and "log_type=test_log" in test_log_url:
        log_link = test_log_url
    elif raw_path:
        log_link = _jita_api_log_url(raw_path, lab=lab, infra=infra)
    elif test_log_url:
        log_link = test_log_url

    jita_link = ""
    if task_id:
        jita_link = (
            f"https://jita.eng.nutanix.com/results?task_ids={task_id}"
            f"&active_tab=2&merge_tests=false"
        )

    tg_link = ""
    if result_id:
        tg_link = f"http://triage-genie.eng.nutanix.com/review/{result_id}"
    elif task_id:
        tg_link = f"http://triage-genie.eng.nutanix.com/view_tasks?jita_task_ids={task_id}"

    tg_json_link = ""
    tc_path = convert_testcase_name_to_path(testcase)
    if raw_path and tc_path:
        tg_json_link = _jita_api_log_url(
            f"{raw_path.rstrip('/')}/{tc_path}/normalized_logs/triage_genie.json",
            lab=lab,
            infra=infra,
        )

    return {
        "jita": jita_link,
        "log": log_link,
        "triage_genie": tg_link,
        "triage_genie_json": tg_json_link,
        "task_id": task_id,
        "result_id": result_id,
        "raw_path": raw_path,
        "lab": lab,
        "infra": infra,
    }


def _extract_steps_from_steps_log(steps_log, limit=40):
    """Pull unique STEP descriptions from steps.log as a Test Steps fallback."""
    if not steps_log:
        return ""
    steps = []
    seen = set()
    for line in str(steps_log).splitlines():
        m = re.search(r"\bSTEP\b.*?\(T[SB]\)\s+(.*)$", line)
        if not m:
            continue
        text = m.group(1).strip().strip("-").strip()
        if not text or set(text) <= {"-", "="} or text in seen:
            continue
        seen.add(text)
        steps.append(text)
        if len(steps) >= limit:
            break
    return "\n".join(steps)


def _fetch_last_pass_info(testcase_name, branch="", timeout=12):
    """Best-effort last successful run for Regression line (may be unavailable)."""
    testcase_name = (testcase_name or "").strip()
    if not testcase_name:
        return {}
    branch = (branch or "").strip()
    raw_query = {"test": testcase_name, "status": "Succeeded"}
    if branch:
        raw_query["branch"] = branch
    try:
        resp = session.post(
            f"{JITA_BASE}/reports/agave_test_results",
            json={
                "raw_query": raw_query,
                "only": "_id,test,status,start_time,end_time,branch",
                "start": 0,
                "limit": 1,
                "sort": "-start_time",
                "merge": True,
            },
            timeout=timeout,
        )
        if resp.status_code != 200:
            return {}
        rows = (resp.json() or {}).get("data") or []
        if not rows:
            return {}
        row = rows[0]
        ts = row.get("start_time") or row.get("end_time")
        when = ""
        if isinstance(ts, dict) and "$date" in ts:
            when = datetime.utcfromtimestamp(ts["$date"] / 1000).strftime("%Y-%m-%dT%H:%M:%S")
        elif isinstance(ts, (int, float)):
            # seconds or ms
            val = float(ts)
            if val > 1e12:
                val = val / 1000.0
            when = datetime.utcfromtimestamp(val).strftime("%Y-%m-%dT%H:%M:%S")
        elif isinstance(ts, str):
            when = ts
        return {
            "branch": (row.get("branch") or branch or "").strip(),
            "at": when,
        }
    except Exception as e:
        logger.debug("last-pass lookup failed for %s: %s", testcase_name, e)
        return {}


def _enrich_eng_ticket_context(ticket_ctx):
    """
    Fill NOS/PC commits, exception/traceback, log URL, and links from JITA so the
    ENG description matches Triage Genie style for this specific test run.
    """
    ctx = dict(ticket_ctx or {})
    testcase = (ctx.get("testcase_name") or "").strip()
    result_id = _oid_str(ctx.get("testcase_id") or ctx.get("test_result_id"))
    task_id = _oid_str(ctx.get("agave_task_id") or ctx.get("task_id"))

    detailed = {}
    if result_id:
        detailed = fetch_detailed_test_result(result_id) or {}
        if detailed:
            if not testcase:
                test_obj = detailed.get("test") or {}
                testcase = (test_obj.get("name") if isinstance(test_obj, dict) else "") or ""
                ctx["testcase_name"] = testcase
            if not task_id:
                task_id = _oid_str(detailed.get("agave_task_id"))
                if task_id:
                    ctx["agave_task_id"] = task_id
            if not (ctx.get("test_log_url") or "").strip() and detailed.get("test_log_url"):
                ctx["test_log_url"] = detailed.get("test_log_url")
            if not (ctx.get("exception") or "").strip() and detailed.get("exception"):
                ctx["exception"] = detailed.get("exception")
            if not (ctx.get("exception_summary") or "").strip() and detailed.get("exception_summary"):
                ctx["exception_summary"] = detailed.get("exception_summary")
            if not (ctx.get("nos_branch") or "").strip() and detailed.get("branch"):
                ctx["nos_branch"] = detailed.get("branch")
            if not (ctx.get("nos_commit") or "").strip() and detailed.get("commit_id"):
                ctx["nos_commit"] = detailed.get("commit_id")
            if not (ctx.get("nos_gbn") or ctx.get("gbn")) and detailed.get("gbn") is not None:
                ctx["nos_gbn"] = detailed.get("gbn")

    if task_id and (
        not ctx.get("nos_commit")
        or not ctx.get("pc_commit")
        or not ctx.get("nos_branch")
        or not ctx.get("pc_branch")
        or not ctx.get("nutest_branch")
        or not ctx.get("nutest-py3-tests_branch")
    ):
        try:
            task = fetch_agave_task(task_id) or {}
        except Exception as e:
            logger.debug("fetch_agave_task(%s) failed: %s", task_id, e)
            task = {}
        if task:
            ctx.setdefault("nos_branch", task.get("branch") or "")
            ctx.setdefault("nos_commit", task.get("commit_id") or "")
            if task.get("gbn") is not None:
                ctx.setdefault("nos_gbn", task.get("gbn"))
            ctx.setdefault("pc_branch", task.get("image_branch") or task.get("branch") or "")
            ctx.setdefault("pc_commit", task.get("image_commit") or task.get("commit_id") or "")
            if task.get("image_gbn") is not None:
                ctx.setdefault("pc_gbn", task.get("image_gbn"))
            elif task.get("gbn") is not None:
                ctx.setdefault("pc_gbn", task.get("gbn"))
            # Test-repo branch is the one Gerrit CRs for nutest fixes should target.
            if task.get("nutest-py3-tests_branch"):
                ctx.setdefault("nutest_branch", task.get("nutest-py3-tests_branch"))
                ctx.setdefault("nutest-py3-tests_branch", task.get("nutest-py3-tests_branch"))
            if task.get("service"):
                ctx.setdefault("service", task.get("service"))
            if task.get("label"):
                ctx.setdefault("label", task.get("label"))
            if task.get("package_type"):
                ctx.setdefault("package_type", task.get("package_type"))

    # Default PC from NOS when PC fields still blank.
    if not (ctx.get("pc_branch") or "").strip():
        ctx["pc_branch"] = ctx.get("nos_branch") or ctx.get("current_branch") or "master"
    if not (ctx.get("pc_commit") or "").strip():
        ctx["pc_commit"] = ctx.get("nos_commit") or ""
    if ctx.get("pc_gbn") is None and ctx.get("nos_gbn") is not None:
        ctx["pc_gbn"] = ctx.get("nos_gbn")
    if not (ctx.get("nos_branch") or "").strip():
        ctx["nos_branch"] = ctx.get("current_branch") or ctx.get("branch") or "master"

    # Failed-with one-liner
    if not (ctx.get("failed_with") or "").strip():
        ctx["failed_with"] = (
            (ctx.get("root_cause") or "").strip()
            or (ctx.get("exception_summary") or "").strip()
            or (ctx.get("ai_summary") or "").strip()
        )

    # Test steps: explicit > steps.log STEP lines
    if not (ctx.get("test_steps") or "").strip():
        links = _build_eng_ticket_links(ctx)
        tc_path = convert_testcase_name_to_path(testcase)
        steps_text = ""
        if links.get("raw_path") and tc_path:
            steps_url = _jita_api_log_url(
                f"{links['raw_path'].rstrip('/')}/{tc_path}/steps.log",
                lab=links.get("lab") or "phx1",
                infra=links.get("infra") or "nutest",
            )
            steps_text = _extract_steps_from_steps_log(
                fetch_log_from_url(steps_url, timeout=20)
            )
        if steps_text:
            ctx["test_steps"] = steps_text

    # Last pass (best-effort; skip quietly on timeout)
    if not ctx.get("last_pass_at"):
        lp = _fetch_last_pass_info(
            testcase,
            branch=(ctx.get("nos_branch") or ctx.get("current_branch") or ""),
        )
        if lp.get("at"):
            ctx["last_pass_at"] = lp["at"]
            ctx["last_pass_branch"] = lp.get("branch") or ctx.get("nos_branch") or "master"

    ctx["_eng_links"] = _build_eng_ticket_links(ctx)
    branch_info = _infer_gerrit_target_branch(ctx)
    ctx["gerrit_branch"] = branch_info.get("gerrit_branch")
    ctx["handoff_branch"] = branch_info.get("handoff_branch")
    ctx["cr_branch"] = branch_info.get("gerrit_branch")
    ctx["_branch_info"] = branch_info
    return ctx


def _build_eng_ticket_description(ticket_ctx):
    """
    Build ENG description in Triage Genie style:

      Test case *name*
      Failed with:
      ...
      NOS:*branch* commit (gbn)
      PC :*branch* commit (gbn)
      Regression: *Yes-build-to-build*, Last pass on branch *master*, at *ts*
      Links: [Jita|...] | [Log|...] | [Triage Genie|...] | [Triage Genie JSON|...]
      Test Steps: {noformat}...{noformat}
      Traceback: {code}...{code}
    """
    ctx = ticket_ctx or {}
    testcase = (ctx.get("testcase_name") or "").strip()
    failed_with = re.sub(r"\s+", " ", (ctx.get("failed_with") or ctx.get("root_cause") or "").strip())
    if len(failed_with) > 600:
        failed_with = failed_with[:597].rstrip() + "..."

    nos_branch = (ctx.get("nos_branch") or ctx.get("current_branch") or ctx.get("branch") or "master").strip()
    nos_commit = (ctx.get("nos_commit") or "").strip()
    nos_gbn = ctx.get("nos_gbn") if ctx.get("nos_gbn") is not None else ctx.get("gbn")
    pc_branch = (ctx.get("pc_branch") or nos_branch).strip()
    pc_commit = (ctx.get("pc_commit") or nos_commit).strip()
    pc_gbn = ctx.get("pc_gbn") if ctx.get("pc_gbn") is not None else nos_gbn

    regression = (ctx.get("regression") or _ENG_REGRESSION_YES).strip() or _ENG_REGRESSION_YES
    last_pass_branch = (ctx.get("last_pass_branch") or nos_branch).strip()
    last_pass_at = (ctx.get("last_pass_at") or "").strip()

    links = ctx.get("_eng_links") or _build_eng_ticket_links(ctx)
    link_bits = []
    if links.get("jita"):
        link_bits.append(f"[Jita|{links['jita']}]")
    if links.get("log"):
        link_bits.append(f"[Log|{links['log']}]")
    if links.get("triage_genie"):
        link_bits.append(f"[Triage Genie|{links['triage_genie']}]")
    if links.get("triage_genie_json"):
        link_bits.append(f"[Triage Genie JSON|{links['triage_genie_json']}]")

    lines = []
    if testcase:
        lines.append(f"Test case *{testcase}*")
    else:
        lines.append("Test case *unknown*")
    lines.append("Failed with:")
    lines.append(failed_with or "See traceback / deep analysis below.")
    lines.append("")
    nos_line = f"NOS:*{nos_branch}*"
    if nos_commit:
        nos_line += f" {nos_commit}"
    if nos_gbn not in (None, ""):
        nos_line += f" ({nos_gbn})"
    pc_line = f"PC :*{pc_branch}*"
    if pc_commit:
        pc_line += f" {pc_commit}"
    if pc_gbn not in (None, ""):
        pc_line += f" ({pc_gbn})"
    lines.append(nos_line)
    lines.append(pc_line)

    reg_line = f"Regression: *{regression}*"
    if last_pass_at:
        reg_line += f", Last pass on branch *{last_pass_branch}*, at *{last_pass_at}*"
    lines.append(reg_line)

    if link_bits:
        lines.append("Links: " + " | ".join(link_bits))
    lines.append("")

    test_steps = (ctx.get("test_steps") or "").strip()
    if test_steps:
        lines.append("Test Steps:")
        lines.append("{noformat}")
        lines.append(test_steps[:6000])
        lines.append("{noformat}")
        lines.append("")

    expected = (ctx.get("expected_results") or "").strip()
    if expected:
        lines.append(f"Expected results - {expected}")
        lines.append("")

    traceback = (ctx.get("exception") or ctx.get("traceback") or "").strip()
    if traceback:
        lines.append("Traceback:")
        lines.append("{code}")
        lines.append(traceback[:12000])
        lines.append("{code}")
        lines.append("")

    # Keep deep-analysis extras after the TG-style block (does not replace it).
    extras = []
    report = (ctx.get("triage_report") or "").strip()
    if report and "Failed with:" not in report[:80]:
        extras.append("h3. RegX-AI Deep Analysis\n" + report[:8000])
    fix = (ctx.get("suggested_fix") or "").strip()
    if fix:
        extras.append("h3. Suggested Fix\n" + fix[:3000])
    user_notes = (
        (ctx.get("additional_details") or ctx.get("user_notes") or ctx.get("notes") or "")
        .strip()
    )
    if user_notes:
        extras.append("h3. Additional Details (from triage chat)\n" + user_notes[:4000])
    related = []
    for c in ctx.get("related_components") or []:
        name = (c if isinstance(c, str) else str(c)).strip()
        if name and name not in related:
            related.append(name)
    # related components are appended later by create_eng_jira_ticket too; skip here

    body = "\n".join(lines).rstrip()
    if extras:
        body = body + "\n\n----\n" + "\n\n".join(extras)
    body = body + "\n\n----\n_Created via RegX-AI Cursor Deep Analysis_"
    return body


def _infer_primary_component(ticket_ctx):
    """Infer ENG Primary Component parent from analysis / testcase path."""
    explicit = (ticket_ctx.get("primary_component") or "").strip()
    if explicit:
        return explicit
    haystacks = []
    for c in ticket_ctx.get("related_components") or []:
        haystacks.append(str(c))
    for c in ticket_ctx.get("components") or []:
        haystacks.append(str(c))
    haystacks.append(ticket_ctx.get("testcase_name") or "")
    haystacks.append(ticket_ctx.get("root_cause") or "")
    haystacks.append(ticket_ctx.get("triage_report") or "")
    blob = " ".join(haystacks)
    for pattern, name in _ENG_PRIMARY_COMPONENT_ALIASES:
        if pattern.search(blob):
            return name
    # Path heuristic: cdp.<service>....
    tc = (ticket_ctx.get("testcase_name") or "").strip().lower()
    parts = tc.split(".")
    if len(parts) >= 2 and parts[0] == "cdp":
        svc = parts[1].replace("_", " ").title()
        # Prefer known alias casing
        for _, name in _ENG_PRIMARY_COMPONENT_ALIASES:
            if name.lower() == svc.lower() or name.lower().replace(" ", "_") == parts[1]:
                return name
        return svc
    return ""


def resolve_sourcegraph_token(explicit_token=None):
    """Resolve Sourcegraph token from request/user settings/env."""
    tok = (explicit_token or "").strip()
    if tok and "****" not in tok:
        return tok
    username = _current_username()
    if username:
        saved = (get_user_key(username, "sourcegraph_token") or "").strip()
        if saved:
            return saved
    return (os.getenv("SOURCEGRAPH_TOKEN") or "").strip()


def _infer_affects_version(ticket_ctx):
    """Infer Affects Version as a valid ENG Jira version name (not git branch)."""
    for key in ("affects_version", "version", "nos_version", "current_branch", "branch"):
        raw = (ticket_ctx.get(key) or "").strip()
        if not raw:
            continue
        low = raw.lower()
        if "master" in low:
            return "master"
        # Branch ganges-7.6-stable → Jira version "7.6" (not the branch name)
        m = re.search(r"\b(\d+\.\d+(?:\.\d+)?)\b", raw)
        if m:
            return m.group(1)
        if "ganges" in low:
            return "7.6"
    blob = " ".join([
        str(ticket_ctx.get("triage_report") or ""),
        str(ticket_ctx.get("root_cause") or ""),
    ])
    if re.search(r"\bmaster\b", blob, flags=re.I):
        return "master"
    m = re.search(r"\b(\d+\.\d+(?:\.\d+)?)\b", blob)
    if m:
        return m.group(1)
    return "master"


def _infer_test_type(ticket_ctx):
    """Map to a valid ENG Test Type option (never NuTest — not a Jira option)."""
    explicit = (ticket_ctx.get("test_type") or "").strip()
    if explicit:
        mapped = _ENG_TEST_TYPE_ALIASES.get(explicit.lower())
        if mapped:
            return mapped
        if explicit in _ENG_TEST_TYPE_CANDIDATES:
            return explicit
        # Unknown string — fall through to classification-based default
    cls = (ticket_ctx.get("classification") or "").strip().lower()
    if "product" in cls:
        return "Product Bug"
    return "Test Bug"


def _infer_regression_flag(ticket_ctx):
    """ENG Regression? options are e.g. No / Yes-build-to-build (not plain Yes)."""
    explicit = ticket_ctx.get("regression")
    if isinstance(explicit, bool):
        return _ENG_REGRESSION_YES if explicit else _ENG_REGRESSION_NO
    if isinstance(explicit, str) and explicit.strip():
        val = explicit.strip()
        low = val.lower()
        if low in {"no", "n", "false", "0"}:
            return _ENG_REGRESSION_NO
        if low in {"yes", "y", "true", "1"} or low.startswith("yes"):
            # Preserve already-valid option strings
            if val in (_ENG_REGRESSION_YES, "Yes-release-to-release", "Yes-build-to-build"):
                return val if val != "Yes" else _ENG_REGRESSION_YES
            if "release" in low:
                return "Yes-release-to-release"
            return _ENG_REGRESSION_YES
        return val
    # Deep analysis in RegX is almost always a regression failure.
    return _ENG_REGRESSION_YES


def _fetch_eng_createmeta_fields(issue_type="Test", token=None):
    """
    Fetch/cached ENG createmeta fields (allowedValues for versions + custom fields).

    Nutanix Jira returns 404 for the legacy
    /issue/createmeta?projectKeys=...&expand=projects.issuetypes.fields API.
    Use the per-issuetype endpoint instead:
      GET /issue/createmeta/ENG/issuetypes
      GET /issue/createmeta/ENG/issuetypes/{id}
    """
    issue_type = (issue_type or "Test").strip() or "Test"
    with _eng_createmeta_lock:
        cached = _eng_createmeta_cache.get(issue_type)
        if cached:
            return cached

    jira_token = resolve_jira_token(token)
    if not jira_token:
        return {}

    headers = get_jira_headers(jira_token)
    try:
        types_resp = session.get(
            f"{JIRA_BASE}/issue/createmeta/ENG/issuetypes",
            headers=headers,
            timeout=45,
            verify=False,
        )
        if types_resp.status_code != 200:
            logger.warning(
                "ENG createmeta issuetypes failed (%s): %s",
                types_resp.status_code,
                (types_resp.text or "")[:300],
            )
            return {}
        type_id = None
        for itype in (types_resp.json() or {}).get("values") or []:
            if (itype.get("name") or "").strip().lower() == issue_type.lower():
                type_id = itype.get("id")
                break
        if not type_id:
            logger.warning("ENG createmeta: issuetype %r not found", issue_type)
            return {}

        fields_resp = session.get(
            f"{JIRA_BASE}/issue/createmeta/ENG/issuetypes/{type_id}",
            headers=headers,
            timeout=60,
            verify=False,
        )
        if fields_resp.status_code != 200:
            logger.warning(
                "ENG createmeta fields failed (%s): %s",
                fields_resp.status_code,
                (fields_resp.text or "")[:300],
            )
            return {}

        # New API returns a list of field descriptors under "values".
        fields = {}
        for field in (fields_resp.json() or {}).get("values") or []:
            fid = field.get("fieldId") or field.get("key")
            if fid:
                fields[fid] = field

        with _eng_createmeta_lock:
            _eng_createmeta_cache[issue_type] = fields
        return fields
    except Exception as e:
        logger.warning("ENG createmeta error: %s", e)
        return {}


def _allowed_option_values(field_meta):
    """Return list of {id, value/name, children?} from createmeta field."""
    out = []
    for opt in (field_meta or {}).get("allowedValues") or []:
        entry = {
            "id": opt.get("id"),
            "value": opt.get("value") or opt.get("name") or "",
            "name": opt.get("name") or opt.get("value") or "",
            "children": [
                {
                    "id": c.get("id"),
                    "value": c.get("value") or c.get("name") or "",
                    "name": c.get("name") or c.get("value") or "",
                }
                for c in (opt.get("children") or [])
            ],
        }
        if entry["value"] or entry["name"]:
            out.append(entry)
    return out


def _pick_allowed_option(preferred, options, fallbacks=None):
    """Pick best matching allowed option value string (case-insensitive)."""
    candidates = []
    if preferred:
        candidates.append(str(preferred).strip())
    for fb in fallbacks or []:
        if fb and str(fb).strip() not in candidates:
            candidates.append(str(fb).strip())
    if not options:
        return candidates[0] if candidates else ""

    by_lower = {}
    for opt in options:
        key = (opt.get("value") or opt.get("name") or "").strip()
        if key:
            by_lower[key.lower()] = key

    for cand in candidates:
        hit = by_lower.get(cand.lower())
        if hit:
            return hit
    # Substring / startswith soft match
    for cand in candidates:
        cl = cand.lower()
        for low, orig in by_lower.items():
            if cl in low or low in cl or low.startswith(cl) or cl.startswith(low):
                return orig
    # Last resort: first allowed option
    first = (options[0].get("value") or options[0].get("name") or "").strip()
    return first


def _pick_cascading_primary_component(preferred, options, context_blob=""):
    """
    Build ENG Primary Component payload: {"value": Parent, "child": {"value": Child}}.
    Cascading select rejects parent-only on some Jira configs; real ENG tickets always set child.
    """
    parent = _pick_allowed_option(
        preferred,
        options,
        fallbacks=["Stargate", "Curator", "Cassandra"],
    )
    if not parent:
        return None

    parent_opt = None
    for opt in options or []:
        key = (opt.get("value") or opt.get("name") or "").strip()
        if key.lower() == parent.lower():
            parent_opt = opt
            break
    children = (parent_opt or {}).get("children") or []
    if not children:
        return {"value": parent}

    child_names = [
        (c.get("value") or c.get("name") or "").strip()
        for c in children
        if (c.get("value") or c.get("name"))
    ]
    blob = (context_blob or "").lower()
    picked_child = ""
    # Prefer a child whose token appears in testcase/root-cause text.
    for name in child_names:
        token = name.lower().replace(parent.lower(), "").strip("-_ ")
        if token and len(token) >= 3 and token.replace(" ", "") in blob.replace(" ", "").replace("_", ""):
            picked_child = name
            break
    if not picked_child:
        other = next((n for n in child_names if n.lower().endswith("-other") or n.lower() == "other"), "")
        picked_child = other or child_names[0]
    return {"value": parent, "child": {"value": picked_child}}


def _pick_allowed_version(preferred, version_options):
    """Pick a valid ENG version name from createmeta versions list."""
    names = []
    for opt in version_options or []:
        n = (opt.get("name") or opt.get("value") or "").strip()
        if n:
            names.append(n)
    if not names:
        # Safe defaults used by existing ENG tickets
        return preferred if preferred in {"master", "Triage", "7.6", "7.5.1"} else "master"

    by_lower = {n.lower(): n for n in names}
    prefs = []
    if preferred:
        prefs.append(preferred)
        # Map branch-like → release number
        m = re.search(r"\b(\d+\.\d+(?:\.\d+)?)\b", preferred)
        if m:
            prefs.append(m.group(1))
        if "master" in preferred.lower():
            prefs.append("master")
        if "7.6" in preferred or "ganges" in preferred.lower():
            prefs.extend(["7.6", "master"])
    prefs.extend(["master", "7.6", "7.5.1"])

    for p in prefs:
        hit = by_lower.get(p.lower())
        if hit:
            return hit
    for p in prefs:
        pl = p.lower()
        for low, orig in by_lower.items():
            if pl in low or low.startswith(pl):
                return orig
    return by_lower.get("master") or names[0]


def is_confirm_eng_ticket_intent(text):
    """User confirming a pending ENG ticket draft (yes / create with overrides)."""
    t = re.sub(r"[*`_]", "", (text or "").strip().lower())
    t = re.sub(r"\s+", " ", t)
    if not t:
        return False
    if re.match(r"^(yes|y|ok|okay|confirm|proceed|go ahead|create it|looks good|lgtm)\b", t):
        return True
    # Field override reply while a draft is pending
    return bool(
        re.search(
            r"\b(primary component|affects version|fix version|test case|test type|regression)\s*[:=]",
            t,
            flags=re.I,
        )
    )


def parse_eng_ticket_field_overrides(text):
    """Parse 'Primary Component: Stargate' style overrides from user reply."""
    overrides = {}
    if not text:
        return overrides
    patterns = {
        "primary_component": r"primary\s*component\s*[:=]\s*([^\n,;]+)",
        "affects_version": r"affects\s*version(?:/s)?\s*[:=]\s*([^\n,;]+)",
        "fix_version": r"fix\s*version(?:/s)?\s*[:=]\s*([^\n,;]+)",
        "testcase_name": r"test\s*case(?:\s*name)?\s*[:=]\s*([^\n,;]+)",
        "test_type": r"test\s*type\s*[:=]\s*([^\n,;]+)",
        "regression": r"regression\??\s*[:=]\s*([^\n,;]+)",
        "issue_type": r"issue\s*type\s*[:=]\s*([^\n,;]+)",
        "summary": r"summary\s*[:=]\s*([^\n]+)",
    }
    for key, pat in patterns.items():
        m = re.search(pat, text, flags=re.I)
        if m:
            overrides[key] = m.group(1).strip().strip("\"'")
    return overrides


def build_eng_ticket_draft(ticket_ctx):
    """
    Infer ENG-required fields from deep-analysis context.

    Returns draft dict with proposed values + missing list for user confirmation.
    """
    ctx = dict(ticket_ctx or {})
    testcase = (ctx.get("testcase_name") or "").strip()
    primary = _infer_primary_component(ctx)
    affects = _infer_affects_version(ctx)
    fix_version = (ctx.get("fix_version") or "Triage").strip() or "Triage"
    test_type = _infer_test_type(ctx)
    regression = _infer_regression_flag(ctx)
    issue_type = (ctx.get("issue_type") or "").strip() or _issue_type_from_classification(
        ctx.get("classification")
    )
    summary = _build_eng_ticket_summary(ctx)

    draft = {
        "summary": summary,
        "issue_type": issue_type,
        "testcase_name": testcase,
        "primary_component": primary,
        "affects_version": affects,
        "fix_version": fix_version,
        "test_type": test_type,
        "regression": regression,
        "inferred_from_analysis": True,
    }

    missing = []
    if not testcase:
        missing.append("testcase_name")
    if not primary:
        missing.append("primary_component")
    if not affects:
        missing.append("affects_version")
    if not test_type:
        missing.append("test_type")

    draft["missing"] = missing
    # Confirmation only when inference could not fill required ENG fields.
    draft["needs_confirmation"] = bool(missing)
    return draft


def format_eng_ticket_draft_prompt(draft):
    """Ask the user to confirm inferred ENG fields before create."""
    lines = [
        "ENG requires a few fields before I can create the ticket. "
        "I inferred these from the analysis — reply **yes** to create, or override any field:",
        "",
        f"- **Summary:** {draft.get('summary')}",
        f"- **Issue Type:** {draft.get('issue_type')}",
        f"- **Primary Component:** {draft.get('primary_component') or '❓ needed (e.g. Stargate)'}",
        f"- **Test Case Name:** {draft.get('testcase_name') or '❓ needed'}",
        f"- **Affects Version/s:** {draft.get('affects_version') or '❓ needed (e.g. master)'}",
        f"- **Fix Version/s:** {draft.get('fix_version') or 'Triage'}",
        f"- **Test Type:** {draft.get('test_type') or '❓ needed (e.g. Test Bug)'}",
        f"- **Regression?:** {draft.get('regression') or 'Yes-build-to-build'}",
        "",
        "Example override:",
        "`yes; Primary Component: Stargate; Affects Version: master; Test Type: Test Bug`",
    ]
    if draft.get("missing"):
        lines.insert(
            1,
            "**Still missing (please provide):** " + ", ".join(draft["missing"]),
        )
        lines.insert(2, "")
    return "\n".join(lines)


def create_eng_jira_ticket(ticket_ctx, token=None, require_confirm=False):
    """
    Create an ENG Jira issue from deep-analysis context.

    Infers required ENG fields from the chat/analysis and creates immediately
    on simple asks like "create eng ticket". Only prompts the user when a
    required field cannot be inferred (or require_confirm=True).

    Returns dict:
      - ok + key/url on success
      - needs_user_input + draft + follow_up_answer when user input needed
      - ok False + error on hard failure
    """
    ctx = dict(ticket_ctx or {})
    draft = build_eng_ticket_draft(ctx)

    # Auto-create when analysis has enough data. Ask only if something is missing
    # (or caller explicitly wants confirmation).
    if draft.get("missing") or (require_confirm and not ctx.get("confirm")):
        return {
            "ok": False,
            "needs_user_input": True,
            "draft": draft,
            "follow_up_answer": format_eng_ticket_draft_prompt(draft),
            "error": (
                "Missing required ENG fields: " + ", ".join(draft["missing"])
                if draft.get("missing")
                else "ENG required fields need confirmation before create"
            ),
        }

    jira_token = resolve_jira_token(token)
    if not jira_token:
        return {
            "ok": False,
            "error": (
                "Jira token not available. Open User Settings → API Keys and add "
                "your Atlassian Jira Personal Token."
            ),
        }

    summary = draft["summary"]
    issue_type = draft["issue_type"]
    testcase = draft["testcase_name"]
    primary = draft["primary_component"]
    affects = draft["affects_version"]
    fix_version = draft["fix_version"]
    test_type = draft["test_type"]
    regression = draft["regression"]

    # Enrich with JITA run metadata (NOS/PC/commits/links/steps/traceback) so the
    # description matches Triage Genie for this specific testcase run.
    ctx["regression"] = regression
    try:
        ctx = _enrich_eng_ticket_context(ctx)
    except Exception as enrich_err:
        logger.warning("ENG ticket context enrich failed: %s", enrich_err)
    description = _build_eng_ticket_description(ctx)
    if ctx.get("testcase_name") and not testcase:
        testcase = ctx["testcase_name"]
        draft["testcase_name"] = testcase


    # Resolve against live ENG createmeta so values are valid option/version names.
    meta = _fetch_eng_createmeta_fields(issue_type, token=jira_token)
    primary_payload = {"value": primary}
    if meta:
        pc_opts = _allowed_option_values(meta.get("customfield_15160"))
        context_blob = " ".join([
            str(testcase or ""),
            str(ctx.get("root_cause") or ""),
            str(ctx.get("triage_report") or ""),
            " ".join(str(c) for c in (ctx.get("related_components") or [])),
        ])
        cascaded = _pick_cascading_primary_component(primary, pc_opts, context_blob)
        if cascaded:
            primary_payload = cascaded
            primary = cascaded.get("value") or primary
        else:
            primary = _pick_allowed_option(
                primary, pc_opts, fallbacks=["Stargate", "Curator", "Cassandra"]
            ) or primary
            primary_payload = {"value": primary}
        regression = _pick_allowed_option(
            regression,
            _allowed_option_values(meta.get("customfield_13260")),
            fallbacks=[_ENG_REGRESSION_YES, _ENG_REGRESSION_NO, "Yes-build-to-build", "No"],
        ) or regression
        # Normalize aliases like NuTest → Test Bug before matching allowed values.
        test_type = _infer_test_type({**ctx, "test_type": test_type})
        test_type = _pick_allowed_option(
            test_type,
            _allowed_option_values(meta.get("customfield_18062")),
            fallbacks=list(_ENG_TEST_TYPE_CANDIDATES),
        ) or test_type
        affects = _pick_allowed_version(
            affects, _allowed_option_values(meta.get("versions"))
        ) or affects
        fix_version = _pick_allowed_version(
            fix_version, _allowed_option_values(meta.get("fixVersions"))
        ) or fix_version
        draft.update({
            "primary_component": primary,
            "regression": regression,
            "test_type": test_type,
            "affects_version": affects,
            "fix_version": fix_version,
        })
    else:
        # Createmeta unavailable — still never send invalid NuTest.
        test_type = _infer_test_type({**ctx, "test_type": test_type})
        draft["test_type"] = test_type
        primary_payload = {"value": primary}

    related = []
    for c in ctx.get("related_components") or []:
        name = (c if isinstance(c, str) else str(c)).strip()
        if name and name not in related:
            related.append(name)
    if related:
        description = (
            description.rstrip()
            + "\n\nh3. Related Components (from analysis)\n"
            + ", ".join(related)
        )

    labels = ["ai-qa-triage", "regx-ai"]
    for lab in ctx.get("labels") or []:
        lab = str(lab).strip()
        if lab and lab not in labels:
            labels.append(lab)

    environment = (ctx.get("test_log_url") or ctx.get("environment") or "").strip()

    fields = {
        "project": {"key": "ENG"},
        "summary": summary,
        "issuetype": {"name": issue_type},
        "description": description,
        "labels": labels,
        "versions": [{"name": affects}],
        "fixVersions": [{"name": fix_version}],
        "customfield_15160": primary_payload,  # Primary Component (cascading)
        "customfield_13260": {"value": regression},  # Regression?
        "customfield_18060": [testcase[:255]],  # Test Case Name
        "customfield_18062": {"value": test_type},  # Test Type
    }
    if environment:
        fields["environment"] = environment

    headers = get_jira_headers(jira_token)

    def _post_create(payload_fields):
        return session.post(
            f"{JIRA_BASE}/issue",
            headers=headers,
            json={"fields": payload_fields},
            timeout=60,
            verify=False,
        )

    try:
        resp = _post_create(fields)

        # Auto-heal invalid required option/version values (no user yes-loop).
        if resp.status_code >= 400:
            err_json = {}
            try:
                err_json = resp.json() or {}
            except Exception:
                err_json = {}
            errors = err_json.get("errors") or {}
            retry_fields = dict(fields)
            changed = False

            if "customfield_18062" in errors:
                for candidate in _ENG_TEST_TYPE_CANDIDATES:
                    if candidate == retry_fields.get("customfield_18062", {}).get("value"):
                        continue
                    trial = dict(retry_fields)
                    trial["customfield_18062"] = {"value": candidate}
                    trial_resp = _post_create(trial)
                    if trial_resp.status_code in (200, 201):
                        resp = trial_resp
                        test_type = candidate
                        retry_fields = trial
                        changed = False
                        break
                    resp = trial_resp
                    err_json = {}
                    try:
                        err_json = trial_resp.json() or {}
                    except Exception:
                        pass
                    errors = err_json.get("errors") or {}
                    if "customfield_18062" not in errors:
                        retry_fields = trial
                        changed = True
                        break

            if resp.status_code >= 400 and "customfield_13260" in errors:
                for candidate in (_ENG_REGRESSION_YES, _ENG_REGRESSION_NO, "Yes-release-to-release"):
                    trial = dict(retry_fields)
                    trial["customfield_13260"] = {"value": candidate}
                    trial_resp = _post_create(trial)
                    if trial_resp.status_code in (200, 201):
                        resp = trial_resp
                        regression = candidate
                        retry_fields = trial
                        break
                    resp = trial_resp

            if resp.status_code >= 400 and "versions" in (errors or {}):
                for candidate in ("master", "7.6", "7.5.1", "Triage"):
                    trial = dict(retry_fields)
                    trial["versions"] = [{"name": candidate}]
                    trial_resp = _post_create(trial)
                    if trial_resp.status_code in (200, 201):
                        resp = trial_resp
                        affects = candidate
                        retry_fields = trial
                        break
                    resp = trial_resp

            if resp.status_code >= 400 and "fixVersions" in (errors or {}):
                for candidate in ("Triage", "master", "7.6"):
                    trial = dict(retry_fields)
                    trial["fixVersions"] = [{"name": candidate}]
                    trial_resp = _post_create(trial)
                    if trial_resp.status_code in (200, 201):
                        resp = trial_resp
                        fix_version = candidate
                        retry_fields = trial
                        break
                    resp = trial_resp

            fields = retry_fields
            if changed and resp.status_code >= 400:
                resp = _post_create(fields)

        # Strip only non-required invalid fields (e.g. bad optional labels).
        if resp.status_code >= 400:
            err_json = {}
            try:
                err_json = resp.json() or {}
            except Exception:
                err_json = {}
            errors = err_json.get("errors") or {}
            optional_bad = [k for k in errors if k in {"components", "environment", "labels", "customfield_10011"}]
            if optional_bad:
                logger.warning(
                    "ENG ticket create optional field rejected %s — retrying without them",
                    optional_bad,
                )
                retry_fields = dict(fields)
                for k in optional_bad:
                    retry_fields.pop(k, None)
                resp = _post_create(retry_fields)

        if resp.status_code not in (200, 201):
            err_body = ""
            try:
                err_body = json.dumps(resp.json())[:800]
            except Exception:
                err_body = (resp.text or "")[:800]
            return {
                "ok": False,
                "error": f"Jira create failed ({resp.status_code}): {err_body}",
            }

        draft.update({
            "primary_component": primary,
            "regression": regression,
            "test_type": test_type,
            "affects_version": affects,
            "fix_version": fix_version,
        })

        data = resp.json() or {}
        key = data.get("key") or ""
        if not key:
            return {"ok": False, "error": "Jira create returned no issue key"}

        url = f"https://jira.nutanix.com/browse/{key}"
        duplicates_linked = []
        for dup in ctx.get("jira_duplicates") or []:
            dup_key = str(dup).strip().upper()
            if not dup_key or not re.match(r"^[A-Z][A-Z0-9]+-\d+$", dup_key):
                continue
            try:
                link_resp = session.post(
                    f"{JIRA_BASE}/issueLink",
                    headers=headers,
                    json={
                        "type": {"name": "Duplicate"},
                        "inwardIssue": {"key": key},
                        "outwardIssue": {"key": dup_key},
                    },
                    timeout=30,
                    verify=False,
                )
                if link_resp.status_code in (200, 201):
                    duplicates_linked.append(dup_key)
            except Exception as link_err:
                logger.warning("Failed linking %s as duplicate of %s: %s", key, dup_key, link_err)

        return {
            "ok": True,
            "key": key,
            "url": url,
            "summary": summary,
            "issue_type": issue_type,
            "draft": {**draft, "test_type": test_type},
            "duplicates_linked": duplicates_linked,
        }
    except Exception as e:
        logger.error("Error creating ENG Jira ticket: %s", e, exc_info=True)
        return {"ok": False, "error": str(e)}


def search_glean(query_text):
    """Search Glean for similar issues"""
    try:
        if not os.getenv("GLEAN_TOKEN"):
            logger.warning("GLEAN_TOKEN not set, skipping Glean API call")
            return None
        
        headers = get_glean_headers()
        payload = {
            "query": query_text,
            "max_results": 5
        }
        resp = session.post(
            f"{GLEAN_BASE}/search",
            headers=headers,
            json=payload,
            timeout=30
        )
        if resp.status_code == 200:
            return resp.json()
        else:
            logger.warning(f"Failed to search Glean: {resp.status_code}")
            return None
    except Exception as e:
        logger.warning(f"Error searching Glean: {e}")
        return None


def search_glean_jira(query_text, max_results=10):
    """Search Glean specifically for JIRA tickets matching the query.

    Filters results to the ``jira`` datasource so that only ENG/JIRA issues
    are returned.  Falls back to the generic search if the JIRA-scoped call
    fails.
    """
    if not os.getenv("GLEAN_TOKEN"):
        logger.warning("GLEAN_TOKEN not set, skipping Glean JIRA search")
        return None
    headers = get_glean_headers()
    payload = {
        "query": query_text,
        "pageSize": max_results,
        "requestOptions": {
            "datasourcesFilter": {
                "datasources": ["jira"],
            },
        },
    }
    try:
        resp = session.post(
            f"{GLEAN_BASE}/search",
            headers=headers,
            json=payload,
            timeout=30,
        )
        if resp.status_code == 200:
            return resp.json()
        logger.warning(f"Glean JIRA search returned {resp.status_code}, falling back to generic search")
    except Exception as e:
        logger.warning(f"Glean JIRA search failed: {e}, falling back")
    return search_glean(query_text)


def _extract_jira_tickets_from_glean(glean_data):
    """Walk Glean search results and extract JIRA ticket IDs + metadata.

    Returns a list of dicts:
        [{"ticket": "ENG-12345", "title": "...", "url": "...", "snippet": "..."}, ...]
    """
    import re as _re
    jira_pat = _re.compile(r'[A-Z][A-Z0-9]+-\d+')

    if not glean_data or not isinstance(glean_data, dict):
        return []

    raw_results = glean_data.get("results", [])
    if isinstance(raw_results, dict):
        raw_results = raw_results.get("results", [])
    if not isinstance(raw_results, list):
        return []

    seen_tickets = {}
    for r in raw_results:
        if not isinstance(r, dict):
            continue
        doc = r.get("document", r)
        title = doc.get("title", "")
        url = doc.get("url", "")
        # Collect snippet text from all available snippet objects
        snippet_text = ""
        snippets = r.get("snippets", [])
        if isinstance(snippets, list):
            parts = []
            for s in snippets:
                if isinstance(s, dict):
                    inner = s.get("snippet", s)
                    if isinstance(inner, dict):
                        parts.append(inner.get("text", ""))
                    elif isinstance(inner, str):
                        parts.append(inner)
                elif isinstance(s, str):
                    parts.append(s)
            snippet_text = " ".join(parts)[:500]

        combined_text = f"{title} {url} {snippet_text}"
        found_ids = jira_pat.findall(combined_text)

        # If the URL is a direct JIRA link, the ticket from the URL is the primary one
        if url and "jira" in url.lower():
            url_ids = jira_pat.findall(url)
            found_ids = url_ids + [t for t in found_ids if t not in url_ids]

        for tid in found_ids:
            if tid not in seen_tickets:
                seen_tickets[tid] = {
                    "ticket": tid,
                    "title": title[:200],
                    "url": url if tid in (jira_pat.findall(url) if url else []) else f"https://jira.nutanix.com/browse/{tid}",
                    "snippet": snippet_text[:300],
                }
    return list(seen_tickets.values())

def determine_failure_stage(test_result):
    """Determine failure stage from test result"""
    # Try to extract from exception_summary or exception
    exception_summary = test_result.get("exception_summary", "").lower()
    exception = test_result.get("exception", "").lower()
    combined = f"{exception_summary} {exception}"
    
    if any(keyword in combined for keyword in ["setup", "set up", "before", "precondition"]):
        return "Test Setup"
    elif any(keyword in combined for keyword in ["teardown", "tear down", "after", "cleanup"]):
        return "Teardown"
    elif any(keyword in combined for keyword in ["infra", "infrastructure", "connection", "timeout", "network"]):
        return "Infra"
    else:
        return "Test Body"

# Intermittent (mark for rerun) patterns: loaded from JSON; if exception_summary
# matches any pattern, mark for rerun as Yes.
INTERMITTENT_PATTERNS_JSON = os.path.join(os.path.dirname(__file__), "intermittent_patterns.json")

def _load_intermittent_patterns():
    """Load intermittent regex patterns from JSON file."""
    default_patterns = [
        r"Timedout executing command source.*cluster start in .* secs with error:",
        r"Timedout executing command source.*cluster.*create in .* secs with error",
        r"Couldn't get handle to SVM VM object for ip",
    ]
    try:
        if os.path.exists(INTERMITTENT_PATTERNS_JSON):
            with open(INTERMITTENT_PATTERNS_JSON, "r") as f:
                data = json.load(f)
            raw = data.get("intermittent_patterns", data) if isinstance(data, dict) else data
            if isinstance(raw, list) and raw:
                # Supports both the legacy format (list of regex strings) and the
                # structured format (list of {"regex"/"pattern": ..., ...} objects).
                compiled = []
                for p in raw:
                    if isinstance(p, dict):
                        p = p.get("regex") or p.get("pattern")
                    if isinstance(p, str) and p:
                        compiled.append(re.compile(p, re.IGNORECASE))
                if compiled:
                    return compiled
    except Exception as e:
        logger.warning(f"Could not load intermittent_patterns.json: {e}, using defaults")
    return [re.compile(p, re.IGNORECASE) for p in default_patterns]

SETUP_EXC_LIST = _load_intermittent_patterns()

def is_intermittent_rerun(exception_summary):
    """If exception_summary matches setup_exc_list patterns, mark for rerun as Yes."""
    if not exception_summary:
        return "No"
    text = (exception_summary or "").strip()
    for pattern in SETUP_EXC_LIST:
        if pattern.search(text):
            return "Yes"
    return "No"

def _jira_field_text(value):
    """Flatten a Jira field that may be a string or Atlassian document format."""
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        texts = []

        def _walk(node):
            if isinstance(node, dict):
                text = node.get("text")
                if text:
                    texts.append(str(text))
                for child in node.get("content") or []:
                    _walk(child)
            elif isinstance(node, list):
                for child in node:
                    _walk(child)

        _walk(value)
        return " ".join(texts)
    return str(value)


def classify_failure(exception_summary, exception, jira_data, glean_data):
    """Classify failure as Test Issue or Product Issue"""
    exception_lower = (exception_summary or "").lower() + " " + (exception or "").lower()
    
    # Test Issue indicators
    test_issue_keywords = [
        "assertion", "assert", "expected", "actual", "python", "import error",
        "syntax error", "indentation", "nameerror", "attributeerror", "typeerror",
        "test framework", "pytest", "unittest", "dependency", "library", "module not found"
    ]
    
    # Product Issue indicators
    product_issue_keywords = [
        "api", "backend", "server", "500", "503", "timeout", "connection refused",
        "feature", "regression", "bug", "defect", "broken", "not working"
    ]
    
    test_issue_score = sum(1 for keyword in test_issue_keywords if keyword in exception_lower)
    product_issue_score = sum(1 for keyword in product_issue_keywords if keyword in exception_lower)
    
    # Check Jira ticket if available
    if jira_data:
        fields = jira_data.get("fields") or {}
        jira_summary = _jira_field_text(fields.get("summary")).lower()
        jira_description = _jira_field_text(fields.get("description")).lower()
        jira_combined = f"{jira_summary} {jira_description}"
        
        if "test" in jira_combined and "fix" in jira_combined:
            test_issue_score += 2
        if "product" in jira_combined or "regression" in jira_combined:
            product_issue_score += 2
    
    if test_issue_score > product_issue_score and test_issue_score > 0:
        return "Test Issue"
    elif product_issue_score > test_issue_score and product_issue_score > 0:
        return "Product Issue"
    else:
        return "Unknown / Needs Manual Review"

def validate_triage_genie_ticket(jira_ticket_id, exception_summary, exception):
    """Validate Triage Genie / Jira ticket relevance"""
    if not jira_ticket_id:
        return "Invalid"
    
    jira_data = fetch_jira_ticket(jira_ticket_id)
    if not jira_data:
        return "Invalid"
    
    fields = jira_data.get("fields", {})
    ticket_status = fields.get("status", {}).get("name", "")
    resolution = fields.get("resolution", {}).get("name", "") if fields.get("resolution") else None
    summary = _jira_field_text(fields.get("summary")).lower()
    description = _jira_field_text(fields.get("description")).lower()
    
    # Check if ticket is resolved/closed
    if resolution or ticket_status in ["Closed", "Resolved", "Done"]:
        return "Invalid"
    
    # Compare exception with ticket description
    exception_lower = (exception_summary or "").lower() + " " + (exception or "").lower()
    ticket_text = f"{summary} {description}"
    
    # Check for keyword overlap
    exception_words = set(exception_lower.split())
    ticket_words = set(ticket_text.split())
    common_words = exception_words.intersection(ticket_words)
    
    if len(common_words) >= 3:
        return "Valid"
    elif len(common_words) >= 1:
        return "Partial"
    else:
        return "Invalid"

def generate_ai_suggestion(issue_type, exception_summary, exception, jira_tickets, jira_data, glean_data):
    """Generate AI suggestion based on analysis"""
    suggestions = []
    
    if issue_type == "Test Issue":
        exception_lower = (exception_summary or "").lower() + " " + (exception or "").lower()
        
        if "python" in exception_lower or "import" in exception_lower:
            suggestions.append("Failure caused by Python dependency or import issue. Update test dependencies and verify Python environment.")
        elif "assertion" in exception_lower or "assert" in exception_lower:
            suggestions.append("Assertion failure detected. Review expected vs actual values. Update test assertions if product behavior has changed.")
        elif "syntax" in exception_lower or "indentation" in exception_lower:
            suggestions.append("Syntax error in test code. Review and fix test script syntax.")
        else:
            suggestions.append("Test logic issue identified. Review test implementation and update test code. Consider creating a Nugerrit CR for test fixes.")
        
        if jira_tickets:
            suggestions.append(f"Review Jira ticket(s): {', '.join(jira_tickets)}")
    
    elif issue_type == "Product Issue":
        if jira_tickets and jira_data:
            ticket_id = jira_tickets[0]
            suggestions.append(f"Failure aligns with known product issue in {ticket_id}. Test behavior is valid. Monitor Jira ticket for fix.")
        elif jira_tickets:
            suggestions.append(f"Product regression detected. Track via Jira ticket(s): {', '.join(jira_tickets)}. Test should remain as-is until product fix.")
        else:
            suggestions.append("Product-level failure identified. Test behavior is valid. Consider creating a Jira ticket to track this product issue.")
        
        if glean_data:
            suggestions.append("Similar issues found in Glean search. Review related documentation or known issues.")
    
    else:
        suggestions.append("Unable to definitively classify failure. Manual review recommended. Check test logs and Jira tickets for context.")
        if jira_tickets:
            suggestions.append(f"Review existing Jira ticket(s): {', '.join(jira_tickets)}")
    
    return " ".join(suggestions)

def fetch_detailed_test_result(testcase_id):
    """Fetch detailed test result including exception and failure stage"""
    try:
        resp = session.get(
            f"{PHX_BASE}/agave_test_results/{testcase_id}",
            timeout=30
        )
        resp.raise_for_status()
        return resp.json().get("data", {})
    except Exception as e:
        logger.warning(f"Error fetching detailed test result {testcase_id}: {e}")
        return {}

def convert_testcase_name_to_path(testcase_name):
    """
    Convert testcase name to directory path.
    Example: cdp.curator.goldsuite_iointegrity.test_goldsuite.CuratorGoldSuiteTest.test_gold___cluster_upgrade_with_disk_balancing
    -> cdp/curator/goldsuite_iointegrity/test_goldsuite/CuratorGoldSuiteTest/test_gold___cluster_upgrade_with_disk_balancing
    """
    if not testcase_name:
        return ""
    # Replace dots with slashes
    path = testcase_name.replace(".", "/")
    return path

def fetch_log_from_url(log_url, timeout=30):
    """
    Fetch log content from a URL.
    Returns the log content as string, or empty string if fetch fails.
    """
    try:
        resp = session.get(log_url, timeout=timeout, verify=False)
        if resp.status_code == 200:
            return resp.text
        else:
            logger.warning(f"Failed to fetch log from {log_url}: HTTP {resp.status_code}")
            return ""
    except Exception as e:
        logger.warning(f"Error fetching log from {log_url}: {e}")
        return ""

def fetch_testcase_logs(testcase_name, tester_log_url):
    """
    Fetch steps.log and nutest_test.log for a testcase.
    
    Args:
        testcase_name: Full testcase name (e.g., cdp.curator.goldsuite_iointegrity.test_goldsuite.CuratorGoldSuiteTest.test_gold___cluster_upgrade_with_disk_balancing)
        tester_log_url: Base URL for logs directory (e.g., http://10.40.234.216/logs/...)
    
    Returns:
        dict with 'steps_log' and 'nutest_test_log' keys, containing log content or empty strings
    """
    logs = {
        "steps_log": "",
        "nutest_test_log": ""
    }
    
    if not testcase_name or not tester_log_url:
        return logs
    
    # Convert testcase name to path
    testcase_path = convert_testcase_name_to_path(testcase_name)
    if not testcase_path:
        return logs
    
    # Construct log URLs
    # Ensure tester_log_url ends with /
    base_url = tester_log_url.rstrip("/") + "/"
    
    # Construct full paths
    steps_log_url = f"{base_url}{testcase_path}/steps.log"
    nutest_test_log_url = f"{base_url}{testcase_path}/nutest_test.log"
    
    logger.info(f"Fetching logs for {testcase_name}")
    logger.debug(f"Steps log URL: {steps_log_url}")
    logger.debug(f"Nutest test log URL: {nutest_test_log_url}")
    
    # Fetch logs
    logs["steps_log"] = fetch_log_from_url(steps_log_url)
    logs["nutest_test_log"] = fetch_log_from_url(nutest_test_log_url)
    
    return logs

def generate_ai_failure_summary(exception, exception_summary, tester_log_url, testcase_name, steps_log="", nutest_test_log=""):
    """
    Generate AI-based failure summary using the Nutanix AI endpoint.
    
    Args:
        exception: Full exception text
        exception_summary: Exception summary
        tester_log_url: Base URL for logs
        testcase_name: Testcase name
        steps_log: Content of steps.log
        nutest_test_log: Content of nutest_test.log
    
    Returns:
        tuple (success: bool, summary: str or error message)
    """
    try:
        # Build the prompt content
        log_content = ""
        if steps_log:
            log_content += f"=== steps.log ===\n{steps_log[:5000]}\n\n"  # Limit to 5000 chars per log
        if nutest_test_log:
            log_content += f"=== nutest_test.log ===\n{nutest_test_log[:5000]}\n\n"
        
        # Build user content
        user_content = (
            f"Testcase: {testcase_name}\n\n"
            f"Exception Summary: {exception_summary or 'N/A'}\n\n"
            f"Exception:\n```\n{exception or 'N/A'}\n```\n\n"
        )
        
        if log_content:
            user_content += f"Test Logs:\n{log_content}\n"
        
        user_content += (
            "Provide a concise failure summary:\n"
            "(1) Root cause in one sentence\n"
            "(2) Failing component or line if clear\n"
            "(3) Suggested fix or next step"
        )
        
        # System prompt
        system_prompt = (
            "You are a test failure analyst. Given a Python test failure with exception details and logs, "
            "provide a concise failure summary: (1) Root cause in one sentence, (2) failing component or line if clear, "
            "(3) suggested fix or next step. Be specific and actionable."
        )
        
        # Prepare payload
        payload = {
            "model": "hack-reason",
            "messages": [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_content}
            ],
            "max_tokens": 1024,
            "stream": False
        }
        
        # Make request to AI endpoint
        url = f"{AI_BASE}/chat/completions"
        headers = {
            "Authorization": f"Bearer {AI_API_KEY}",
            "Accept": "application/json",
            "Content-Type": "application/json"
        }
        
        data = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(url, data=data, headers=headers, method="POST")
        
        with urllib.request.urlopen(req, context=SSL_CTX, timeout=60) as resp:
            if resp.getcode() != 200:
                return False, f"AI API returned HTTP {resp.getcode()}"
            
            response_data = json.loads(resp.read().decode())
            choices = response_data.get("choices", [])
            if not choices:
                return False, "AI returned no choices"
            
            content = (choices[0].get("message") or {}).get("content", "")
            return True, content.strip()
            
    except urllib.error.HTTPError as e:
        body = e.read().decode() if e.fp else ""
        try:
            err_json = json.loads(body)
        except Exception:
            err_json = {"raw": body}
        return False, f"AI API error HTTP {e.code}: {json.dumps(err_json)[:300]}"
    except Exception as e:
        logger.error(f"Error generating AI failure summary: {e}", exc_info=True)
        return False, f"Error generating AI summary: {str(e)}"

def create_triage_genie_session():
    """
    Create a requests.Session authenticated via login for Triage Genie API calls.

    Uses TRIAGE_GENIE_USERNAME / TRIAGE_GENIE_PASSWORD env vars if set,
    otherwise falls back to the service account (JITA_SVC_USERNAME / JITA_SVC_PASSWORD).
    """
    tg_user = TRIAGE_GENIE_USERNAME or JITA_SVC_USERNAME
    tg_pass = TRIAGE_GENIE_PASSWORD or JITA_SVC_PASSWORD

    if not tg_user or not tg_pass:
        logger.warning("Triage Genie credentials not configured (set TRIAGE_GENIE_USERNAME / TRIAGE_GENIE_PASSWORD)")
        return None

    session_triage = requests.Session()
    session_triage.verify = False
    try:
        login_response = session_triage.post(
            LOGIN_URL,
            data={"username": tg_user, "password": tg_pass},
            verify=False,
            timeout=15,
            allow_redirects=False,
        )
        # Successful login: 302 redirect to dashboard (not back to /login).
        # Failed login: 200 with login page re-rendered.
        if login_response.status_code == 302:
            location = login_response.headers.get("Location", "")
            if "/login" not in location:
                logger.info("Triage Genie session authenticated successfully")
                return session_triage

        logger.warning(
            "Triage Genie login failed (credentials rejected). "
            "Set TRIAGE_GENIE_USERNAME and TRIAGE_GENIE_PASSWORD env vars "
            "with valid Triage Genie / LDAP credentials."
        )
        return None
    except Exception as e:
        logger.warning(f"Triage Genie login error: {e}")
        return None


def build_triage_genie_ticket_map(test_result_ids):
    """
    Batch pre-fetch Triage Genie dup_ticket_id for each test result.

    Uses GET /api/tasks/{testcase_id} (the direct Triage Genie task endpoint).
    Authentication: session-based login via create_triage_genie_session().

    Args:
        test_result_ids: List of JITA test result _id values (testcase IDs)

    Returns:
        dict: Mapping of testcase_id -> dup_ticket_id
    """
    ticket_map = {}
    if not test_result_ids:
        return ticket_map

    unique_ids = list(set(tid for tid in test_result_ids if tid))
    logger.info(f"build_triage_genie_ticket_map: looking up {len(unique_ids)} testcase(s) via /api/tasks/{{id}}")

    tg_session = create_triage_genie_session()
    if not tg_session:
        logger.warning("build_triage_genie_ticket_map: no TG session — cannot fetch tickets")
        return ticket_map

    def _lookup_single(tc_id):
        """GET /api/tasks/{tc_id} and return (tc_id, dup_ticket_id) or (tc_id, None)."""
        try:
            resp = tg_session.get(
                f"{TRIAGE_GENIE_BASE}/tasks/{tc_id}",
                verify=False,
                timeout=15,
            )
            if resp.status_code == 200:
                ct = resp.headers.get("Content-Type", "")
                if "json" in ct or "application/json" in ct:
                    data = resp.json()
                    dup = data.get("dup_ticket_id")
                    if dup:
                        return (tc_id, str(dup).strip())
                else:
                    logger.debug(f"TG /tasks/{tc_id} returned HTML (auth may have expired)")
            elif resp.status_code == 404:
                logger.debug(f"TG /tasks/{tc_id}: not found (test may not be triaged yet)")
            else:
                logger.debug(f"TG /tasks/{tc_id} returned {resp.status_code}")
        except Exception as exc:
            logger.debug(f"TG /tasks/{tc_id} error: {exc}")
        return (tc_id, None)

    with ThreadPoolExecutor(max_workers=MAX_WORKERS) as executor:
        futures = {executor.submit(_lookup_single, tid): tid for tid in unique_ids}
        for future in as_completed(futures):
            tc_id, dup_ticket = future.result()
            if dup_ticket:
                ticket_map[tc_id] = dup_ticket

    logger.info(f"build_triage_genie_ticket_map: found {len(ticket_map)} ticket(s) out of {len(unique_ids)} lookups")
    return ticket_map


def fetch_triage_genie_ticket_id(testcase_id, triage_session=None):
    """
    Fetch Triage Genie dup_ticket_id for a single test result.

    Calls GET /api/tasks/{testcase_id} using a session-authenticated connection.
    If triage_session is not provided, creates one via create_triage_genie_session().

    Returns:
        str: Jira ticket ID (e.g., "ENG-904593") or None if not found
    """
    if not testcase_id:
        return None

    session = triage_session or create_triage_genie_session()
    if not session:
        return None

    try:
        resp = session.get(
            f"{TRIAGE_GENIE_BASE}/tasks/{testcase_id}",
            verify=False,
            timeout=15,
        )
        if resp.status_code == 200:
            ct = resp.headers.get("Content-Type", "")
            if "json" in ct:
                data = resp.json()
                dup = data.get("dup_ticket_id")
                if dup:
                    logger.info(f"Found Triage Genie ticket {dup} for testcase {testcase_id}")
                    return str(dup).strip()
            else:
                logger.debug(f"TG /tasks/{testcase_id} returned HTML (auth expired or invalid)")
        elif resp.status_code == 404:
            logger.debug(f"TG /tasks/{testcase_id}: not found")
        else:
            logger.debug(f"TG /tasks/{testcase_id} returned {resp.status_code}")
    except Exception as e:
        logger.debug(f"TG /tasks/{testcase_id} error: {e}")

    return None

@app.route("/mcp/regression/failed-analysis/analyze", methods=["GET"])
@jwt_required
def analyze_failed_testcases():
    """Analyze failed testcases with AI agent"""
    start = time.time()
    
    tag = request.args.get("tag")
    task_ids_param = request.args.get("task_ids")
    include_param = request.args.get("include", "")
    include_set = {x.strip().lower() for x in include_param.split(",") if x.strip()} if include_param else set()
    # Default: basic + exception_summary + intermittent when no include given
    if not include_set:
        include_set = {"basic", "exception_summary", "intermittent"}
    
    # Parse task_ids if provided
    task_ids = None
    if task_ids_param:
        task_ids = [tid.strip() for tid in task_ids_param.split(",") if tid.strip()]
    
    if not tag and not task_ids:
        return jsonify({"error": "Either tag or task_ids is required"}), 400
    
    try:
        # Fetch regression tasks
        tasks = fetch_regression_tasks(tag=tag, task_ids=task_ids)
        if not tasks:
            return jsonify({
                "success": True,
                "results": [],
                "message": "No tasks found for the given criteria"
            })
        
        # Collect all task IDs
        collected_task_ids = [task["_id"]["$oid"] for task in tasks]
        
        # Fetch test results - only failed ones
        logger.info(f"Fetching failed test results for {len(collected_task_ids)} tasks")
        all_test_results = []
        
        if collected_task_ids:
            try:
                # Fetch all test results first
                all_results = fetch_test_results_batch_with_pagination(collected_task_ids)
                # Filter for failed tests
                failed_results = [
                    tr for tr in all_results 
                    if tr.get("status", "").lower() in ("failed", "failure")
                ]
                logger.info(f"Found {len(failed_results)} failed testcases")
                
                # Batch pre-fetch Triage Genie tickets via direct /api/tasks/{id} lookups
                tg_ticket_map = {}
                if "triage_genie_ticket" in include_set:
                    _failed_ids = []
                    for _fr in failed_results:
                        _rid = _fr.get("_id")
                        if isinstance(_rid, dict) and "$oid" in _rid:
                            _failed_ids.append(_rid["$oid"])
                        elif _rid:
                            _failed_ids.append(str(_rid))
                    tg_ticket_map = build_triage_genie_ticket_map(_failed_ids)
                
                # Current branch for history API (from first task)
                current_branch = (tasks[0].get("branch") or "") if tasks else ""
                
                # Analyze each failed testcase
                analysis_results = []
                
                for test_result in failed_results:
                    testcase_id = None
                    if isinstance(test_result.get("_id"), dict) and "$oid" in test_result.get("_id", {}):
                        testcase_id = test_result["_id"]["$oid"]
                    else:
                        testcase_id = str(test_result.get("_id", ""))
                    
                    # Fetch detailed test result for exception and failure stage
                    detailed_result = {}
                    if testcase_id:
                        detailed_result = fetch_detailed_test_result(testcase_id)
                    
                    # Extract data
                    test_field = test_result.get("test", {})
                    if isinstance(test_field, dict):
                        testcase_name = test_field.get("name", "")
                    elif isinstance(test_field, str):
                        testcase_name = test_field
                    else:
                        # Try from detailed result
                        detailed_test = detailed_result.get("test", {})
                        if isinstance(detailed_test, dict):
                            testcase_name = detailed_test.get("name", "")
                        elif isinstance(detailed_test, str):
                            testcase_name = detailed_test
                        else:
                            testcase_name = ""
                    
                    status = test_result.get("status", "FAILED")
                    exception_summary = test_result.get("exception_summary") or detailed_result.get("exception_summary", "")
                    exception = detailed_result.get("exception", "")
                    jira_tickets = test_result.get("jira_tickets", [])
                    test_log_url = test_result.get("test_log_url") or detailed_result.get("test_log_url", "")
                    comments = test_result.get("comments") or detailed_result.get("comments") or ""
                    
                    # Determine failure stage
                    failure_stage = determine_failure_stage({**test_result, **detailed_result})
                    
                    # Intermittent (mark for rerun) from exception_summary
                    intermittent_rerun = is_intermittent_rerun(exception_summary) if "intermittent" in include_set else None
                    
                    # Optional heavy fields: Jira/Glean, issue type, suggestion, Triage Genie ticket, AI Summary
                    jira_data = None
                    glean_data = None
                    issue_type = None
                    suggestion = None
                    triage_genie_ticket_id = None
                    ai_summary = None
                    if "issue_type" in include_set or "suggestion" in include_set:
                        if jira_tickets:
                            jira_data = fetch_jira_ticket(jira_tickets[0])
                        if exception_summary:
                            glean_data = search_glean(exception_summary)
                    if "issue_type" in include_set:
                        issue_type = classify_failure(exception_summary, exception, jira_data, glean_data)
                    if "suggestion" in include_set:
                        suggestion = generate_ai_suggestion(
                            issue_type or classify_failure(exception_summary, exception, jira_data, glean_data),
                            exception_summary, exception, jira_tickets, jira_data, glean_data
                        )
                    if "triage_genie_ticket" in include_set:
                        triage_genie_ticket_id = (
                            tg_ticket_map.get(testcase_id)
                            or tg_ticket_map.get(testcase_name)
                        )
                    
                    # Generate AI Summary if requested
                    if "ai_summary" in include_set:
                        try:
                            # Fetch logs
                            logs = fetch_testcase_logs(testcase_name, test_log_url)
                            
                            # Generate AI summary
                            success, summary = generate_ai_failure_summary(
                                exception=exception,
                                exception_summary=exception_summary,
                                tester_log_url=test_log_url,
                                testcase_name=testcase_name,
                                steps_log=logs.get("steps_log", ""),
                                nutest_test_log=logs.get("nutest_test_log", "")
                            )
                            
                            if success:
                                ai_summary = summary
                            else:
                                ai_summary = f"Error generating summary: {summary}"
                                logger.warning(f"Failed to generate AI summary for {testcase_name}: {summary}")
                        except Exception as e:
                            logger.error(f"Error generating AI summary for {testcase_name}: {e}", exc_info=True)
                            ai_summary = f"Error: {str(e)}"
                    
                    # Resolve regression owner
                    regression_owner = resolve_regression_owner(testcase_name) if testcase_name else "Unknown"
                    
                    # Resolve agave_task_id for retrigger support
                    raw_atid = test_result.get("agave_task_id")
                    if isinstance(raw_atid, dict) and "$oid" in raw_atid:
                        agave_task_id = raw_atid["$oid"]
                    elif raw_atid:
                        agave_task_id = str(raw_atid)
                    else:
                        agave_task_id = None

                    deployment_id = (
                        _rdm_oid(test_result.get("deployment_id"))
                        or _rdm_oid(detailed_result.get("deployment_id"))
                        or None
                    )

                    row = {
                        "testcase_id": testcase_id,
                        "testcase_name": testcase_name,
                        "agave_task_id": agave_task_id,
                        "status": status,
                        "failure_stage": failure_stage,
                        "jira_tickets": jira_tickets,
                        "regression_owner": regression_owner,
                        "test_log_url": test_log_url,
                        "exception_summary": exception_summary,
                        "comments": comments,
                        "exception": exception[:200] if exception else ""
                    }
                    if intermittent_rerun is not None:
                        row["intermittent_rerun"] = intermittent_rerun
                    if issue_type is not None:
                        row["issue_type"] = issue_type
                    if suggestion is not None:
                        row["suggestion_by_ai_agent"] = suggestion
                    if triage_genie_ticket_id is not None:
                        row["triage_genie_ticket_id"] = triage_genie_ticket_id
                    if ai_summary is not None:
                        row["ai_summary"] = ai_summary
                    if deployment_id:
                        row["deployment_id"] = deployment_id

                    analysis_results.append(row)
                
                logger.info(f"[END] Failed Analysis | results={len(analysis_results)} | time={time.time() - start:.2f}s")
                
                return jsonify({
                    "success": True,
                    "results": analysis_results,
                    "total_analyzed": len(analysis_results),
                    "current_branch": current_branch,
                    "tag": tag or None
                })
                
            except requests.exceptions.ConnectionError as e:
                logger.error(f"Connection error: {e}", exc_info=True)
                return jsonify({
                    "error": "Failed to connect to JITA API. Please check your network connection and ensure 'jita.eng.nutanix.com' is accessible.",
                    "details": str(e)
                }), 503
            except requests.exceptions.Timeout as e:
                logger.error(f"Timeout error: {e}", exc_info=True)
                return jsonify({
                    "error": "Request to JITA API timed out. Please try again.",
                    "details": str(e)
                }), 504
            except Exception as e:
                logger.error(f"Error fetching test results: {e}", exc_info=True)
                return jsonify({"error": f"Failed to fetch test results: {str(e)}"}), 500
        else:
            return jsonify({
                "success": True,
                "results": [],
                "message": "No task IDs found"
            })
            
    except ConnectionError as e:
        logger.error(f"Connection error: {e}", exc_info=True)
        return jsonify({
            "error": str(e),
            "type": "connection_error"
        }), 503
    except TimeoutError as e:
        logger.error(f"Timeout error: {e}", exc_info=True)
        return jsonify({
            "error": str(e),
            "type": "timeout_error"
        }), 504
    except Exception as e:
        logger.error(f"Error analyzing failed testcases: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


def _normalize_test_status(status):
    """Lowercased JITA test status string. Dicts (rare) use name/status."""
    if isinstance(status, dict):
        status = status.get("name") or status.get("status") or ""
    try:
        return str(status or "").strip().lower()
    except Exception:
        return ""


def _count_test_statuses(results):
    counts = {}
    for tr in results or []:
        key = _normalize_test_status(tr.get("status")) or "(empty)"
        counts[key] = counts.get(key, 0) + 1
    return counts


def _analyze_failed_testcases_stream(tag, task_ids, include_set, status_set=None):
    """Generator that yields SSE events: progress, start, then one 'row' per result, then 'done' or 'error'."""
    if status_set is None:
        status_set = {"failed", "failure"}
    try:
        yield json.dumps({"type": "progress", "phase": "preparing"})

        tasks = fetch_regression_tasks(tag=tag, task_ids=task_ids)
        if not tasks:
            yield json.dumps({
                "type": "start",
                "total": 0,
                "current_branch": "",
                "tag": tag,
                "status_counts": {},
                "fetched_total": 0,
                "task_count": 0,
            })
            yield json.dumps({"type": "done"})
            return
        collected_task_ids = [task["_id"]["$oid"] for task in tasks]

        yield json.dumps({"type": "progress", "phase": "fetching_results"})

        all_results = fetch_test_results_batch_with_pagination(collected_task_ids)
        status_counts = _count_test_statuses(all_results)
        failed_results = [
            tr for tr in all_results
            if _normalize_test_status(tr.get("status")) in status_set
        ]
        logger.info(
            "Failed analysis: tasks=%s fetched=%s matched=%s status_counts=%s filter=%s",
            len(collected_task_ids),
            len(all_results),
            len(failed_results),
            status_counts,
            sorted(status_set),
        )
        current_branch = (tasks[0].get("branch") or "") if tasks else ""

        # Batch pre-fetch Triage Genie tickets via direct /api/tasks/{id} lookups
        tg_ticket_map = {}
        if "triage_genie_ticket" in include_set:
            yield json.dumps({"type": "progress", "phase": "fetching_triage_genie"})
            _failed_ids = []
            for _fr in failed_results:
                _rid = _fr.get("_id")
                if isinstance(_rid, dict) and "$oid" in _rid:
                    _failed_ids.append(_rid["$oid"])
                elif _rid:
                    _failed_ids.append(str(_rid))
            tg_ticket_map = build_triage_genie_ticket_map(_failed_ids)

        yield json.dumps({
            "type": "start",
            "total": len(failed_results),
            "current_branch": current_branch,
            "tag": tag or None,
            "status_counts": status_counts,
            "fetched_total": len(all_results),
            "task_count": len(collected_task_ids),
        })

        for test_result in failed_results:
            testcase_id = None
            if isinstance(test_result.get("_id"), dict) and "$oid" in test_result.get("_id", {}):
                testcase_id = test_result["_id"]["$oid"]
            else:
                testcase_id = str(test_result.get("_id", ""))
            detailed_result = {}
            if testcase_id:
                detailed_result = fetch_detailed_test_result(testcase_id)
            test_field = test_result.get("test", {})
            if isinstance(test_field, dict):
                testcase_name = test_field.get("name", "")
            elif isinstance(test_field, str):
                testcase_name = test_field
            else:
                detailed_test = detailed_result.get("test", {})
                if isinstance(detailed_test, dict):
                    testcase_name = detailed_test.get("name", "")
                elif isinstance(detailed_test, str):
                    testcase_name = detailed_test
                else:
                    testcase_name = ""
            status = test_result.get("status", "FAILED")
            exception_summary = test_result.get("exception_summary") or detailed_result.get("exception_summary", "")
            exception = detailed_result.get("exception", "")
            jira_tickets = test_result.get("jira_tickets", [])
            test_log_url = test_result.get("test_log_url") or detailed_result.get("test_log_url", "")
            comments = test_result.get("comments") or detailed_result.get("comments") or ""
            failure_stage = determine_failure_stage({**test_result, **detailed_result})
            intermittent_rerun = is_intermittent_rerun(exception_summary) if "intermittent" in include_set else None
            jira_data = None
            glean_data = None
            issue_type = None
            suggestion = None
            triage_genie_ticket_id = None
            ai_summary = None
            if "issue_type" in include_set or "suggestion" in include_set:
                if jira_tickets:
                    jira_data = fetch_jira_ticket(jira_tickets[0])
                if exception_summary:
                    glean_data = search_glean(exception_summary)
            if "issue_type" in include_set:
                issue_type = classify_failure(exception_summary, exception, jira_data, glean_data)
            if "suggestion" in include_set:
                suggestion = generate_ai_suggestion(
                    issue_type or classify_failure(exception_summary, exception, jira_data, glean_data),
                    exception_summary, exception, jira_tickets, jira_data, glean_data
                )
            if "triage_genie_ticket" in include_set:
                triage_genie_ticket_id = (
                    tg_ticket_map.get(testcase_id)
                    or tg_ticket_map.get(testcase_name)
                )
            
            # Generate AI Summary if requested
            if "ai_summary" in include_set:
                try:
                    # Fetch logs
                    logs = fetch_testcase_logs(testcase_name, test_log_url)
                    
                    # Generate AI summary
                    success, summary = generate_ai_failure_summary(
                        exception=exception,
                        exception_summary=exception_summary,
                        tester_log_url=test_log_url,
                        testcase_name=testcase_name,
                        steps_log=logs.get("steps_log", ""),
                        nutest_test_log=logs.get("nutest_test_log", "")
                    )
                    
                    if success:
                        ai_summary = summary
                    else:
                        ai_summary = f"Error generating summary: {summary}"
                        logger.warning(f"Failed to generate AI summary for {testcase_name}: {summary}")
                except Exception as e:
                    logger.error(f"Error generating AI summary for {testcase_name}: {e}", exc_info=True)
                    ai_summary = f"Error: {str(e)}"
            
            regression_owner = resolve_regression_owner(testcase_name) if testcase_name else "Unknown"

            raw_atid = test_result.get("agave_task_id")
            if isinstance(raw_atid, dict) and "$oid" in raw_atid:
                agave_task_id = raw_atid["$oid"]
            elif raw_atid:
                agave_task_id = str(raw_atid)
            else:
                agave_task_id = None

            deployment_id = (
                _rdm_oid(test_result.get("deployment_id"))
                or _rdm_oid(detailed_result.get("deployment_id"))
                or None
            )

            row = {
                "testcase_id": testcase_id,
                "testcase_name": testcase_name,
                "agave_task_id": agave_task_id,
                "status": status,
                "failure_stage": failure_stage,
                "jira_tickets": jira_tickets,
                "regression_owner": regression_owner,
                "test_log_url": test_log_url,
                "exception_summary": exception_summary,
                "comments": comments,
                "exception": exception[:200] if exception else ""
            }
            if intermittent_rerun is not None:
                row["intermittent_rerun"] = intermittent_rerun
            if issue_type is not None:
                row["issue_type"] = issue_type
            if suggestion is not None:
                row["suggestion_by_ai_agent"] = suggestion
            if triage_genie_ticket_id is not None:
                row["triage_genie_ticket_id"] = triage_genie_ticket_id
            if ai_summary is not None:
                row["ai_summary"] = ai_summary
            if deployment_id:
                row["deployment_id"] = deployment_id

            yield json.dumps({"type": "row", "result": row})
        yield json.dumps({"type": "done"})
    except Exception as e:
        logger.error(f"Error in analyze stream: {e}", exc_info=True)
        yield json.dumps({"type": "error", "message": str(e)})


@app.route("/mcp/regression/failed-analysis/analyze-stream", methods=["GET"])
@jwt_required
def analyze_failed_testcases_stream():
    """Stream analysis results as Server-Sent Events so the UI can display rows as they load."""
    tag = request.args.get("tag")
    task_ids_param = request.args.get("task_ids")
    include_param = request.args.get("include", "")
    include_set = {x.strip().lower() for x in include_param.split(",") if x.strip()} if include_param else set()
    if not include_set:
        include_set = {"basic", "exception_summary", "intermittent"}
    task_ids = normalize_task_id_list(task_ids_param) if task_ids_param else None
    if not tag and not task_ids:
        if task_ids_param:
            return jsonify({"error": "No valid 24-char JITA task IDs provided"}), 400
        return jsonify({"error": "Either tag or task_ids is required"}), 400

    statuses_param = request.args.get("statuses", "")
    STATUS_ALIASES = {
        "failed": ("failed", "failure"),
        "skipped": ("skipped", "skip"),
        "warning": ("warning", "warn"),
        "killed": ("killed", "terminated", "cancelled"),
        "pending": ("pending", "waiting", "running", "started"),
    }
    if statuses_param:
        requested = {s.strip().lower() for s in statuses_param.split(",") if s.strip()}
        status_set = set()
        for key in requested:
            if key in STATUS_ALIASES:
                status_set.update(STATUS_ALIASES[key])
            else:
                status_set.add(key)
    else:
        status_set = {"failed", "failure"}

    def gen():
        for chunk in _analyze_failed_testcases_stream(tag, task_ids, include_set, status_set):
            yield f"data: {chunk}\n\n"

    return Response(
        stream_with_context(gen()),
        mimetype="text/event-stream",
        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"}
    )


def _put_jita_triage_tickets(test_id, comment, jira_tickets, username):
    """Attach comment/jira_tickets on an agave_test_result. Returns (ok, error)."""
    if not test_id:
        return False, "test_id is required"
    user_auth = _get_user_credentials(username)
    if not user_auth:
        return False, "credentials"
    tickets = jira_tickets
    if isinstance(tickets, str):
        tickets = [tickets] if tickets else []
    update_fields = {
        "comments": comment or "",
        "triaged_by": username or "",
    }
    if tickets is not None:
        update_fields["jira_tickets"] = tickets
    payload = {
        "query": {"_id": {"$in": [{"$oid": test_id}]}},
        "data": {"$set": update_fields},
        "multi": True,
    }
    try:
        resp = requests.put(
            f"{JITA_BASE}/agave_test_results",
            headers={"Content-Type": "application/json"},
            json=payload,
            auth=user_auth,
            verify=False,
            timeout=30,
        )
    except Exception as exc:
        logger.warning("[cursor-ai-chat] JITA triage put failed: %s", exc)
        return False, str(exc)
    if resp.status_code == 200:
        return True, None
    return False, (resp.text or f"HTTP {resp.status_code}")


@app.route("/mcp/regression/failed-analysis/update-triage", methods=["PUT"])
@jwt_required
def update_triage_comments():
    """Update comment and/or jira_tickets for an agave_test_result via JITA PUT API."""
    try:
        data = request.get_json() or {}
        test_id = data.get("test_id")
        comment = data.get("comment", "")
        jira_tickets = data.get("jira_tickets")
        if not test_id:
            return jsonify({"error": "test_id is required"}), 400

        current_username = g.current_user.get("sub", "")
        ok, err = _put_jita_triage_tickets(
            test_id,
            comment,
            jira_tickets,
            current_username,
        )
        if err == "credentials":
            return jsonify({
                "error": "Session credentials expired. Please re-login to update triage.",
                "code": "CREDENTIALS_EXPIRED"
            }), 401
        if ok:
            return jsonify({"success": True, "message": "Updated", "triaged_by": current_username})
        return jsonify({"error": err or "Update failed"}), 500
    except Exception as e:
        logger.error(f"Error updating triage: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


# ======================================================
# RDM Failure Analysis for Skipped Testcases
# ======================================================

_RDM_PATTERNS_DATA_ROOT = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "data")

# Categories that auto-disable the failing node in Jarvis on approve / auto-workflow.
RDM_NODE_DISABLE_CATEGORIES = {"INFRA_NODE"}
RDM_RERUN_ACTIONS = {"disable_node_and_rerun", "rerun"}


def _rdm_patterns_file(for_write=False):
    """Team-scoped RDM pattern file; fall back to CDP_FT then legacy data/ path."""
    team = ""
    try:
        if has_request_context():
            team = (getattr(g, "team", None) or "").strip()
    except Exception:
        pass
    candidates = []
    if team:
        candidates.append(os.path.join(_RDM_PATTERNS_DATA_ROOT, team, "rdm_failure_patterns.json"))
    candidates.append(os.path.join(_RDM_PATTERNS_DATA_ROOT, "CDP_FT", "rdm_failure_patterns.json"))
    candidates.append(os.path.join(_RDM_PATTERNS_DATA_ROOT, "rdm_failure_patterns.json"))
    for path in candidates:
        if os.path.exists(path):
            return path
    if for_write:
        dest_dir = os.path.join(_RDM_PATTERNS_DATA_ROOT, team or "CDP_FT")
        os.makedirs(dest_dir, exist_ok=True)
        return os.path.join(dest_dir, "rdm_failure_patterns.json")
    return candidates[0]


# Back-compat alias used by older helpers / tests.
RDM_PATTERNS_FILE = os.path.join(_RDM_PATTERNS_DATA_ROOT, "CDP_FT", "rdm_failure_patterns.json")


def _pattern_next_action(pattern):
    """Resolve next_action from explicit field or category."""
    explicit = (pattern.get("next_action") or "").strip()
    if explicit:
        return explicit
    cat = (pattern.get("category") or "").upper()
    if cat in RDM_NODE_DISABLE_CATEGORIES:
        return "disable_node_and_rerun"
    if cat == "INFRA_INTERMITTENT":
        return "rerun"
    return "comment_only"


def _strip_json_line_comments(text):
    """Drop `//` comment lines so accidental JS-style comments do not break JSON."""
    kept = []
    for line in (text or "").splitlines():
        if line.lstrip().startswith("//"):
            continue
        kept.append(line)
    return "\n".join(kept)


def _read_rdm_patterns_json(path):
    """Read the patterns file; tolerate // comment lines in otherwise valid JSON."""
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        data = json.loads(_strip_json_line_comments(text))
    if not isinstance(data, dict):
        return {"patterns": []}
    if not isinstance(data.get("patterns"), list):
        data["patterns"] = []
    return data


def _load_rdm_patterns():
    """Load RDM failure patterns from JSON file and compile regexes."""
    try:
        path = _rdm_patterns_file()
        if os.path.exists(path):
            data = _read_rdm_patterns_json(path)
            patterns = data.get("patterns", [])
            compiled = []
            for p in patterns:
                try:
                    compiled.append({
                        "id": p["id"],
                        "regex": re.compile(p["regex"], re.IGNORECASE | re.DOTALL),
                        "comment_template": p["comment_template"],
                        "category": p.get("category", ""),
                        "description": p.get("description", ""),
                        "jira": p.get("jira", ""),
                        "next_action": _pattern_next_action(p),
                        "action": p.get("action", ""),
                    })
                except re.error as e:
                    logger.warning(f"Invalid regex in RDM pattern '{p.get('id')}': {e}")
            return compiled
    except Exception as e:
        logger.warning(f"Could not load rdm_failure_patterns.json: {e}")
    return []


RDM_PATTERNS = _load_rdm_patterns()


# Hostnames in installer-error lines: "pitpf06-4: The target node..." or
# "Nodes: kylun01-1: Received \"fatal\"...". Require a digit so "Error:" / "Reason:"
# are not treated as nodes.
_INSTALLER_NODE_LINE_RE = re.compile(
    r"(?:^|\n)\s*(?:Nodes?:\s*)?([A-Za-z][\w.-]*\d[\w.-]*):\s+\S"
)


def _extract_installer_error_nodes(message):
    """Return every node listed under an RDM 'Installer errors:' block."""
    if not message:
        return []
    installer = re.search(r"Installer errors\s*:", message, re.IGNORECASE)
    if not installer:
        return []
    seen = dict()
    for name in _INSTALLER_NODE_LINE_RE.findall(message[installer.end():]):
        if name.lower() in ("nodes", "node"):
            continue
        seen.setdefault(name, None)
    return list(seen)


def _extract_node_names(message):
    """Extract node names from RDM failure messages.

    Prefer every hostname in an Installer errors block (multi-node failures
    list one node per line after a single 'Nodes:' prefix). Otherwise combine
    other extraction strategies. Returns a deduplicated list in first-seen order.
    """
    if not message:
        return []
    installer_nodes = _extract_installer_error_nodes(message)
    if installer_nodes:
        return installer_nodes
    seen = dict()
    for n in re.findall(r'([\w.-]+):\s*Received\s+"fatal"\s+in\s+waiting\s+for\s+event', message):
        seen.setdefault(n, None)
    for n in re.findall(r"(?:Nodes?:\s*)([a-zA-Z][\w\-]*\d+[\-\d]*)", message):
        seen.setdefault(n, None)
    if seen:
        return list(seen)
    all_nodes = re.findall(r"\b([a-zA-Z]+\d{2,}-\d+)\b", message)
    return list(dict.fromkeys(all_nodes))


_RDM_SKILL_TICKET_RE = re.compile(r"\b([A-Z][A-Z0-9]+-\d+)\b")
_RDM_JIRA_CREATE_URL = "https://jira.nutanix.com/secure/CreateIssue!default.jspa"


def _ticket_keys_from_rdm_skill(analysis):
    """Collect ENG/DIAL (and other) Jira keys from skill JSON."""
    analysis = analysis or {}
    keys = []
    for item in analysis.get("existing_tickets") or []:
        if isinstance(item, dict):
            key = item.get("ticket") or item.get("key") or ""
        else:
            key = str(item or "")
        if key:
            keys.append(key.strip())
    for key in analysis.get("jira_duplicates") or []:
        if key:
            keys.append(str(key).strip())
    for field in (
        analysis.get("suggested_comment"),
        analysis.get("root_cause"),
        analysis.get("triage_report"),
    ):
        if field:
            keys.extend(_RDM_SKILL_TICKET_RE.findall(str(field)))
    seen = []
    for key in keys:
        if key and key not in seen:
            seen.append(key)
    return seen


def _rdm_skill_jira_project(issue_category, tickets, suggested_project=""):
    project = (suggested_project or "").strip().upper()
    if project in ("DIAL", "ENG"):
        return project
    if tickets:
        prefix = tickets[0].split("-", 1)[0].upper()
        if prefix in ("DIAL", "ENG"):
            return prefix
    cat = (issue_category or "").upper()
    if any(token in cat for token in ("FOUNDATION", "INFRA", "INTERMITTENT", "PLUGIN")):
        return "DIAL"
    if any(token in cat for token in ("PRODUCT", "CONFIG")):
        return "ENG"
    return "DIAL"


def _normalize_rdm_skill_analysis(analysis, rdm_message=""):
    """Map triage-rdm-deployment-failure JSON to RDM-cell actions."""
    analysis = analysis or {}
    issue_category = (
        analysis.get("issue_category") or analysis.get("classification") or ""
    ).strip()
    recommended_action = (analysis.get("recommended_action") or "").strip().lower().replace("-", "_")
    tickets = _ticket_keys_from_rdm_skill(analysis)
    nodes = _extract_node_names(rdm_message or "")
    cat_upper = issue_category.upper()

    if recommended_action not in (
        "link_existing",
        "create_jira",
        "rerun",
        "disable_node_and_rerun",
    ):
        if tickets:
            recommended_action = "link_existing"
        elif nodes:
            recommended_action = "disable_node_and_rerun"
        elif any(token in cat_upper for token in ("INTERMITTENT", "FLAKY", "ONE-OFF", "ONE_OFF")):
            recommended_action = "rerun"
        else:
            recommended_action = "create_jira"

    suggested_comment = (analysis.get("suggested_comment") or "").strip()
    if not suggested_comment:
        if recommended_action == "link_existing" and tickets:
            suggested_comment = "regx_rerun (%s)" % tickets[0]
        elif recommended_action == "disable_node_and_rerun" and nodes:
            suggested_comment = ", ".join(
                "regx_rerun_disable-%s Rerun cause due to node issue" % n for n in nodes
            )
        else:
            suggested_comment = "regx_rerun"

    next_action = (
        "disable_node_and_rerun"
        if recommended_action == "disable_node_and_rerun" or (
            nodes and recommended_action == "rerun"
        )
        else "rerun"
    )
    jira_project = _rdm_skill_jira_project(
        issue_category, tickets, analysis.get("suggested_jira_project") or ""
    )
    summary = (analysis.get("suggested_fix") or analysis.get("root_cause") or "RDM deployment failure")[:180]
    return {
        "issue_category": issue_category,
        "recommended_action": recommended_action,
        "suggested_comment": suggested_comment,
        "jira_refs": tickets,
        "jira_ticket": tickets[0] if tickets else "",
        "failed_nodes": nodes,
        "suggested_next_action": next_action,
        "suggested_jira_project": jira_project,
        "jira_create": {
            "needed": recommended_action == "create_jira",
            "project": jira_project,
            "url": _RDM_JIRA_CREATE_URL,
            "summary": "RDM: %s" % summary,
            "description": analysis.get("triage_report") or analysis.get("root_cause") or "",
        },
    }


_RDM_MCP_GLEAN_URL = "https://panacea-dev.eng.nutanix.com/mcp/glean"
_RDM_MCP_SOURCEGRAPH_URL = "https://panacea-dev.eng.nutanix.com/mcp/sourcegraph"


def _probe_mcp_endpoint(url):
    """Best-effort liveness check. 4xx still means the gateway is up."""
    try:
        resp = requests.get(url, timeout=4)
        ok = resp.status_code < 500
        return {
            "ok": ok,
            "status": "ok" if ok else "unavailable",
            "status_code": resp.status_code,
        }
    except Exception as exc:
        return {"ok": False, "status": "unavailable", "error": str(exc)[:200]}


def _probe_rdm_mcp_health():
    return {
        "glean": _probe_mcp_endpoint(_RDM_MCP_GLEAN_URL),
        "sourcegraph": _probe_mcp_endpoint(_RDM_MCP_SOURCEGRAPH_URL),
    }


def _agent_mcp_entry_unavailable(entry):
    if entry is None:
        return False
    if isinstance(entry, bool):
        return entry is False
    if isinstance(entry, dict):
        if entry.get("ok") is False:
            return True
        status = str(entry.get("status") or entry.get("state") or "").strip().lower()
        return status in ("unavailable", "down", "error", "failed")
    status = str(entry).strip().lower()
    return status in ("unavailable", "down", "error", "failed", "false")


def _merge_rdm_mcp_health(probe, agent_status):
    """Treat MCP as down if the probe failed or the agent reported a tool error."""
    probe = probe or {}
    agent_status = agent_status if isinstance(agent_status, dict) else {}
    merged = {}
    for key in ("glean", "sourcegraph"):
        p = probe.get(key) or {}
        a = agent_status.get(key)
        probe_ok = bool(p.get("ok", True)) if p else True
        ok = probe_ok and not _agent_mcp_entry_unavailable(a)
        merged[key] = {
            "ok": ok,
            "status": "ok" if ok else "unavailable",
            "probe": p,
            "agent": a,
        }
    notes = str(agent_status.get("notes") or "").strip()
    merged["notes"] = notes
    return merged


def fetch_jita_deployments(task_id):
    """Fetch JITA deployments for a given agave_task_id (paginated)."""
    deployments = []
    start = 0
    limit = 100
    try:
        while True:
            payload = {
                "raw_query": {"task_id": {"$oid": task_id}},
                "start": start,
                "limit": limit,
            }
            resp = session.post(
                f"{JITA_BASE}/reports/deployments",
                json=payload,
                auth=globals().get("JITA_SVC_AUTH"),
                timeout=30,
            )
            if resp.status_code != 200:
                logger.warning(
                    f"JITA deployments fetch failed for task {task_id}: HTTP {resp.status_code}"
                )
                break
            batch = resp.json().get("data", []) or []
            deployments.extend(batch)
            if len(batch) < limit:
                break
            start += limit
        return deployments
    except Exception as e:
        logger.warning(f"JITA deployments fetch error for task {task_id}: {e}")
        return deployments


def _rdm_oid(val):
    """Normalize Mongo/JSON id fields to a string."""
    if not val:
        return ""
    if isinstance(val, dict):
        return str(val.get("$oid") or val.get("$id") or "")
    return str(val)


def _rdm_info_from_deployments(deployments, deployment_id=None):
    """
    Build RDM failure info from JITA deployments.

    When ``deployment_id`` (JITA deployment ``_id``) is set, use that
    deployment's ``provision_request_id`` — a task can have many RDMs,
    one per test. Do not fall back to another test's failed RDM.
    """
    if not deployments:
        return None

    failed_deployments = [
        d for d in deployments if (d.get("status") or "").lower() == "failed"
    ]
    chosen = None
    if deployment_id:
        want = str(deployment_id)
        for dep in deployments:
            if _rdm_oid(dep.get("_id")) == want:
                chosen = dep
                break
        if chosen is None:
            logger.warning(
                f"JITA deployment_id {want} not found among {len(deployments)} deployments"
            )
            return None
    else:
        chosen = failed_deployments[0] if failed_deployments else None
        if chosen is None:
            return None

    prov_id = _rdm_oid(chosen.get("provision_request_id"))
    combined_message = ""
    for transition in chosen.get("status_transitions") or []:
        if (transition.get("status") or "").lower() == "failed":
            reason = transition.get("reason") or ""
            if reason:
                combined_message = reason
                break

    rdm_category = ""
    rdm_resolution = ""
    rdm_source = ""
    if prov_id:
        try:
            rdm_resp = session.get(
                f"https://rdm.eng.nutanix.com/api/v1/scheduled_deployments/{prov_id}?expand=created_by",
                timeout=15,
            )
            if rdm_resp.status_code == 200:
                rdm_data = rdm_resp.json().get("data", {}) or {}
                rdm_msg = rdm_data.get("message", "")
                if rdm_msg:
                    combined_message = rdm_msg
                fa = rdm_data.get("failure_analysis") or {}
                rdm_category = fa.get("category", "")
                rdm_resolution = fa.get("resolution", "")
                em = (fa.get("error_metadata") or {}).get("RDM") or {}
                rdm_source = em.get("source", "")
        except Exception as e:
            logger.warning(f"RDM API fetch failed for {prov_id}: {e}")

    if not combined_message and not prov_id:
        return None

    return {
        "rdm_message": combined_message,
        "rdm_link": (
            f"https://rdm.eng.nutanix.com/scheduled_deployments/{prov_id}" if prov_id else ""
        ),
        "provision_request_id": prov_id,
        "jita_deployment_id": _rdm_oid(chosen.get("_id")),
        "rdm_category": rdm_category,
        "rdm_resolution": rdm_resolution,
        "rdm_source": rdm_source,
        "failed_deployment_count": len(failed_deployments),
        "total_deployment_count": len(deployments),
    }


def get_rdm_failure_info(task_id, deployment_id=None, testcase_id=None, deployments=None):
    """
    Get RDM failure information for a task / specific test.

    Prefer the test result's ``deployment_id`` so each skipped test maps to
    its own RDM scheduled-deployment, not the first failed RDM on the task.
    """
    if deployments is None:
        deployments = fetch_jita_deployments(task_id)
    if not deployments:
        return None

    if not deployment_id and testcase_id:
        deployment_id = _jita_test_result_deployment_id(testcase_id) or None
        if not deployment_id:
            logger.warning(
                "Could not resolve deployment_id for testcase %s; "
                "not falling back to first failed RDM on the task",
                testcase_id,
            )
            return None

    return _rdm_info_from_deployments(deployments, deployment_id=deployment_id)


def _jita_test_result_deployment_id(testcase_id):
    """Resolve a test result's JITA deployment_id (PHX, then JITA)."""
    if not testcase_id:
        return ""
    tr = fetch_detailed_test_result(testcase_id) or {}
    did = _rdm_oid(tr.get("deployment_id"))
    if did:
        return did
    try:
        resp = session.get(
            f"{JITA_BASE}/agave_test_results/{testcase_id}",
            auth=globals().get("JITA_SVC_AUTH"),
            timeout=30,
        )
        if resp.status_code == 200:
            return _rdm_oid((resp.json().get("data") or {}).get("deployment_id"))
    except Exception as e:
        logger.warning(f"JITA test result fetch failed for {testcase_id}: {e}")
    return ""


def match_rdm_pattern(rdm_message):
    """
    Match an RDM failure message against known patterns.
    Returns dict with matched pattern info and generated comment, or None.
    Hot-reloads patterns from disk so file edits take effect without restart.
    """
    global RDM_PATTERNS
    if not rdm_message:
        return None

    RDM_PATTERNS = _load_rdm_patterns()
    for pattern in RDM_PATTERNS:
        match = pattern["regex"].search(rdm_message)
        if match:
            template = pattern["comment_template"]
            comment = template

            nodes = _extract_node_names(rdm_message)
            if "{node_name}" in template:
                if nodes:
                    comment = ", ".join(
                        template.replace("{node_name}", n) for n in nodes
                    )
                else:
                    comment = "regx_rerun"

            return {
                "pattern_id": pattern["id"],
                "category": pattern["category"],
                "description": pattern["description"],
                "generated_comment": comment,
                "failed_nodes": nodes or [],
                "jira": pattern.get("jira", ""),
                "next_action": _pattern_next_action(pattern),
                "matched": True,
            }

    return None


def _suggest_rdm_pattern_from_message(rdm_message, rdm_link="", nodes=None):
    """Draft a reusable pattern from an unmatched RDM failure for user approval."""
    nodes = nodes if nodes is not None else _extract_node_names(rdm_message or "")
    snippet = (rdm_message or "").strip()
    # Use the first ~6 non-empty lines as the signature, then escape.
    lines = [ln.strip() for ln in snippet.splitlines() if ln.strip()][:6]
    signature = " ".join(lines)[:400]
    escaped = re.escape(signature)
    for n in nodes:
        escaped = escaped.replace(re.escape(n), r"([\w\-]+)")
    regex = re.sub(r"(\\ )+", r"\\s+", escaped)
    regex = regex.replace(r"\:", ":")
    slug_src = (nodes[0] if nodes else "rdm") + "_" + (signature[:40] or "pattern")
    slug = re.sub(r"[^a-zA-Z0-9]+", "_", slug_src).strip("_").lower()[:60]
    next_action = "disable_node_and_rerun" if nodes else "rerun"
    category = "INFRA_NODE" if nodes else "INFRA_INTERMITTENT"
    comment = (
        "regx_rerun_disable-{node_name} Rerun cause due to node issue"
        if nodes else "regx_rerun"
    )
    return {
        "id": f"learned_{slug}" if slug else f"learned_{int(time.time())}",
        "regex": regex or r"Installer errors[:\s]+Nodes?:\s*([\w\-]+)",
        "confidence": 0.9,
        "comment_template": comment,
        "category": category,
        "next_action": next_action,
        "description": "Learned from RDM AI analysis approval",
        "action": (
            "Disable failed node(s) in Jarvis and rerun"
            if nodes else "Rerun the skipped test"
        ),
        "example_failure": snippet[:800],
        "reference_task": rdm_link or "",
    }


_JARVIS_SERVICE_MOD = None


def _jarvis_mod():
    """Load Jarvis helpers without importing agents.base (requires PyYAML)."""
    global _JARVIS_SERVICE_MOD
    if _JARVIS_SERVICE_MOD is not None:
        return _JARVIS_SERVICE_MOD
    try:
        from agents.services import jarvis_service as mod
        _JARVIS_SERVICE_MOD = mod
        return mod
    except ModuleNotFoundError as e:
        if getattr(e, "name", "") != "yaml" and "yaml" not in str(e):
            raise
    import importlib.util
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "agents", "services", "jarvis_service.py")
    spec = importlib.util.spec_from_file_location("regx_jarvis_service", path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    _JARVIS_SERVICE_MOD = mod
    return mod


def _jarvis_service():
    return _jarvis_mod().JarvisNodeService(auth=JITA_SVC_AUTH)


def _apply_jita_triage_update(test_id, comment, jira_tickets=None):
    """Update JITA agave_test_result comments. Returns (ok, payload_or_error)."""
    current_username = _current_username()
    user_auth = _get_user_credentials(current_username)
    if not user_auth:
        return False, {
            "error": "Session credentials expired. Please re-login to update triage.",
            "code": "CREDENTIALS_EXPIRED",
        }
    update_fields = {
        "comments": comment,
        "triaged_by": current_username,
    }
    if jira_tickets is not None:
        if isinstance(jira_tickets, str):
            jira_tickets = [jira_tickets] if jira_tickets else []
        update_fields["jira_tickets"] = jira_tickets
    payload = {
        "query": {"_id": {"$in": [{"$oid": test_id}]}},
        "data": {"$set": update_fields},
        "multi": True,
    }
    try:
        resp = requests.put(
            f"{JITA_BASE}/agave_test_results",
            headers={"Content-Type": "application/json"},
            json=payload,
            auth=user_auth,
            verify=False,
            timeout=30,
        )
        if resp.status_code == 200:
            return True, {"success": True, "triaged_by": current_username, "comment": comment}
        return False, {"error": resp.text or f"HTTP {resp.status_code}"}
    except Exception as e:
        logger.error(f"Error updating triage: {e}", exc_info=True)
        return False, {"error": str(e)}


def _disable_rdm_nodes(failed_nodes, rdm_link, disabled_by):
    """Disable each hostname in Jarvis. Returns list of per-node results."""
    results = []
    if not failed_nodes:
        return results
    svc = _jarvis_service()
    seen = set()
    for node_name in failed_nodes:
        name = (node_name or "").strip()
        if not name or name.lower() in seen:
            continue
        seen.add(name.lower())
        result = svc.disable_node_sync(
            node_name=name,
            rdm_link=rdm_link,
            disabled_by=disabled_by,
            reason="Rerun cause due to node issue",
        )
        results.append(result)
    return results


def _rdm_should_disable(category, next_action, failed_nodes):
    action = (next_action or "").strip() or _pattern_next_action({"category": category, "next_action": next_action})
    if action == "disable_node_and_rerun":
        return True
    if (category or "").upper() in RDM_NODE_DISABLE_CATEGORIES and failed_nodes:
        return True
    return False


def _rdm_should_rerun(next_action, category):
    action = (next_action or "").strip() or _pattern_next_action({"category": category, "next_action": next_action})
    return action in RDM_RERUN_ACTIONS


@app.route("/mcp/regression/failed-analysis/rdm-analyze", methods=["POST"])
@jwt_required
def rdm_analyze_skipped():
    """
    Analyze RDM failure for skipped testcases.

    Accepts either:
      { tests: [{ agave_task_id, testcase_id, testcase_name, deployment_id }] }
      { task_ids: [agave_task_id, ...] }  (legacy; one RDM per task)

    Prefer ``tests`` so each testcase maps to its own JITA deployment / RDM.
    """
    try:
        data = request.get_json() or {}
        tests = data.get("tests") or []
        task_ids = data.get("task_ids", [])
        if isinstance(task_ids, str):
            task_ids = [tid.strip() for tid in task_ids.split(",") if tid.strip()]
        if tests:
            rows = tests
        elif task_ids:
            rows = [{"agave_task_id": tid} for tid in task_ids]
        else:
            return jsonify({"error": "tests or task_ids is required"}), 400

        dep_cache = {}
        results = []
        for row in rows:
            task_id = row.get("agave_task_id") or ""
            if task_id and task_id not in dep_cache:
                dep_cache[task_id] = fetch_jita_deployments(task_id)
            results.append(_analyze_one_rdm_task(
                task_id,
                testcase_id=row.get("testcase_id"),
                deployment_id=row.get("deployment_id"),
                deployments=dep_cache.get(task_id),
            ))

        return jsonify({"success": True, "results": results})
    except Exception as e:
        logger.error(f"RDM analyze error: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/mcp/regression/failed-analysis/rdm-analyze-ai", methods=["POST"])
@jwt_required
def rdm_analyze_ai():
    """
    AI-powered analysis for RDM failures that don't match known patterns.
    Uses Glean search + AI summary to identify existing bugs and provide analysis.
    """
    try:
        data = request.get_json() or {}
        task_id = data.get("task_id", "")
        testcase_id = data.get("testcase_id", "")
        deployment_id = data.get("deployment_id", "")
        rdm_message = data.get("rdm_message", "")
        testcase_name = data.get("testcase_name", "")

        if not rdm_message and not task_id:
            return jsonify({"error": "task_id or rdm_message is required"}), 400

        rdm_info = None
        if task_id:
            rdm_info = get_rdm_failure_info(
                task_id,
                deployment_id=deployment_id or None,
                testcase_id=testcase_id or None,
            )
            if not rdm_message and rdm_info:
                rdm_message = rdm_info.get("rdm_message", "")

        if not rdm_message:
            return jsonify({"error": "No RDM failure message found"}), 404

        # Search Glean for similar failures
        glean_results = None
        search_query = rdm_message[:200]
        if testcase_name:
            short_name = testcase_name.split(".")[-1] if "." in testcase_name else testcase_name
            search_query = f"{short_name} {search_query}"
        try:
            glean_results = search_glean(search_query)
        except Exception as e:
            logger.warning(f"Glean search failed for RDM analysis: {e}")

        # Build AI analysis
        jira_refs = []
        glean_summary = ""
        if glean_results and isinstance(glean_results, list):
            for gr in glean_results[:5]:
                if isinstance(gr, dict):
                    title = gr.get("title", "")
                    url = gr.get("url", "")
                    if title:
                        glean_summary += f"- {title}"
                        if url:
                            glean_summary += f" ({url})"
                        glean_summary += "\n"
                        # Extract JIRA ticket IDs
                        jira_matches = re.findall(r"[A-Z]+-\d+", title)
                        jira_refs.extend(jira_matches)
                        if url:
                            jira_url_matches = re.findall(r"[A-Z]+-\d+", url)
                            jira_refs.extend(jira_url_matches)

        jira_refs = list(dict.fromkeys(jira_refs))

        summary_parts = []
        summary_parts.append(f"RDM Deployment Failure Analysis")
        summary_parts.append(f"Error: {rdm_message[:300]}")
        if jira_refs:
            summary_parts.append(f"Related Jira tickets: {', '.join(jira_refs[:5])}")
        if glean_summary:
            summary_parts.append(f"Similar issues found:\n{glean_summary}")
        else:
            summary_parts.append("No similar issues found in Glean.")

        ai_summary = "\n".join(summary_parts)

        suggested_comment = "regx_rerun"
        nodes = _extract_node_names(rdm_message)
        if nodes:
            suggested_comment = ", ".join(
                f"regx_rerun_disable-{n} Rerun cause due to node issue" for n in nodes
            )
        elif jira_refs:
            suggested_comment = f"regx_rerun ({jira_refs[0]})"

        rdm_link = (rdm_info or {}).get("rdm_link") or ""

        suggested_pattern = _suggest_rdm_pattern_from_message(
            rdm_message, rdm_link=rdm_link, nodes=nodes
        )

        return jsonify({
            "success": True,
            "ai_summary": ai_summary,
            "jira_refs": jira_refs,
            "suggested_comment": suggested_comment,
            "failed_nodes": nodes,
            "suggested_next_action": "disable_node_and_rerun" if nodes else "rerun",
            "suggested_pattern": suggested_pattern,
            "glean_results_count": len(glean_results) if glean_results else 0,
        })
    except Exception as e:
        logger.error(f"RDM AI analyze error: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/mcp/regression/failed-analysis/rdm-skill-analyze", methods=["POST"])
@jwt_required
def rdm_skill_analyze():
    """
    Skill-based RDM triage for unmatched skipped tests.

    Runs triage-rdm-deployment-failure via the Cursor bridge using the RDM
    scheduled-deployment URL, then maps the result to a JITA comment
    (link existing ENG/DIAL ticket, rerun, or draft a new Jira).
    """
    try:
        data = request.get_json() or {}
        task_id = data.get("task_id") or data.get("agave_task_id") or ""
        testcase_id = data.get("testcase_id") or ""
        deployment_id = data.get("deployment_id") or ""
        rdm_message = data.get("rdm_message") or ""
        rdm_link = data.get("rdm_link") or ""
        testcase_name = data.get("testcase_name") or ""

        if not testcase_name and not rdm_link and not task_id:
            return jsonify({"success": False, "error": "testcase_name or rdm_link is required"}), 400

        username = _current_username()
        user_toks = resolve_user_settings_tokens(username)
        cursor_api_key = user_toks.get("cursor_api_key")
        if not cursor_api_key:
            return jsonify({
                "success": False,
                "error": format_mcp_token_connection_error("cursor", username),
                "require_key_setup": True,
                "mcp_token_status": mcp_token_status_for_user(username),
            }), 403

        atlassian_tokens = build_atlassian_tokens_for_bridge(username)

        rdm_info = None
        if task_id and (not rdm_link or not rdm_message):
            rdm_info = get_rdm_failure_info(
                task_id,
                deployment_id=deployment_id or None,
                testcase_id=testcase_id or None,
            )
            if rdm_info:
                rdm_link = rdm_link or rdm_info.get("rdm_link") or ""
                rdm_message = rdm_message or rdm_info.get("rdm_message") or ""

        if not rdm_link and task_id:
            rdm_link = "https://jita.eng.nutanix.com/results?task_ids=%s" % task_id

        glean_tickets = []
        glean_snippets = []
        glean_rest_ok = False
        try:
            search = search_existing_tickets_for_failure(
                rdm_message, rdm_message, testcase_name
            )
            glean_tickets = _enrich_tickets_with_jira(search.get("tickets") or [])
            glean_snippets = search.get("snippets") or []
            glean_rest_ok = bool(search.get("glean_ok"))
        except Exception as glean_err:
            logger.warning("Glean search failed for RDM skill analysis: %s", glean_err)

        mcp_probe = _probe_rdm_mcp_health()

        payload = {
            "testcase_name": testcase_name or "rdm_skipped_testcase",
            "exception_summary": rdm_message[:500],
            "exception": rdm_message,
            "steps_log": "",
            "nutest_test_log": "",
            "test_log_url": rdm_link,
            "rdm_url": rdm_link,
            "rdm_message": rdm_message,
            "jita_task_id": task_id,
            "jira_tickets": data.get("jira_tickets") or [],
            "failure_stage": data.get("failure_stage") or "DEPLOYMENT_FAILED",
            "triage_genie_ticket": data.get("triage_genie_ticket") or "",
            "glean_tickets": glean_tickets,
            "glean_snippets": glean_snippets,
            "analysis_type": "skipped",
            "cursor_api_key": cursor_api_key,
            "atlassian_tokens": atlassian_tokens,
        }

        resp = requests.post(
            f"{CURSOR_BRIDGE_URL}/analyze-testcase",
            json=payload,
            timeout=600,
        )
        if resp.status_code != 200:
            error_msg = (
                resp.json().get("error", resp.text)
                if resp.headers.get("content-type", "").startswith("application/json")
                else resp.text
            )
            return jsonify({"success": False, "error": "Bridge error: %s" % error_msg}), 502

        bridge = resp.json()
        analysis = bridge.get("analysis") or {}
        mapped = _normalize_rdm_skill_analysis(analysis, rdm_message=rdm_message)
        mcp_health = _merge_rdm_mcp_health(mcp_probe, analysis.get("mcp_status") or {})
        glean_mcp_ok = bool((mcp_health.get("glean") or {}).get("ok"))
        glean_ok = False if not glean_mcp_ok else glean_rest_ok
        search_source = "glean_mcp" if glean_mcp_ok else ("glean_rest" if glean_tickets else "unavailable")
        suggested_pattern = _suggest_rdm_pattern_from_message(
            rdm_message, rdm_link=rdm_link, nodes=mapped.get("failed_nodes") or []
        )
        if mapped.get("suggested_comment"):
            suggested_pattern["comment_template"] = mapped["suggested_comment"]
        if mapped.get("jira_ticket"):
            suggested_pattern["jira"] = mapped["jira_ticket"]
        if mapped.get("issue_category"):
            suggested_pattern["description"] = mapped["issue_category"]

        return jsonify({
            "success": True,
            "session_id": bridge.get("session_id", ""),
            "skill_used": "triage-rdm-deployment-failure",
            "rdm_link": rdm_link,
            "analysis": analysis,
            "root_cause": analysis.get("root_cause"),
            "classification": analysis.get("classification") or mapped["issue_category"],
            "confidence": analysis.get("confidence"),
            "suggested_fix": analysis.get("suggested_fix"),
            "triage_report": analysis.get("triage_report"),
            "tg_ticket_validation": analysis.get("tg_ticket_validation"),
            "enriched_tickets": glean_tickets,
            "glean_snippets": glean_snippets,
            "ai_summary": analysis.get("root_cause") or analysis.get("triage_report") or "",
            "suggested_pattern": suggested_pattern,
            "mcp_health": mcp_health,
            "glean_ok": glean_ok,
            "search_source": search_source,
            **mapped,
        })
    except requests.exceptions.ConnectionError:
        logger.error("Cursor bridge is not reachable at %s", CURSOR_BRIDGE_URL)
        return jsonify({
            "success": False,
            "error": "Cursor AI bridge is not running. Start it with: cd cursor-bridge && npm start",
        }), 503
    except requests.exceptions.Timeout:
        return jsonify({
            "success": False,
            "error": "AI RDM Failure Analysis timed out (>600s).",
        }), 504
    except Exception as e:
        logger.error("RDM skill analyze error: %s", e, exc_info=True)
        return jsonify({"success": False, "error": str(e)}), 500


def _analyze_one_rdm_task(task_id, testcase_id=None, deployment_id=None, deployments=None):
    """Return rdm_info + pattern match for a single test (or legacy per-task)."""
    rdm_info = get_rdm_failure_info(
        task_id,
        deployment_id=deployment_id,
        testcase_id=testcase_id,
        deployments=deployments,
    )
    if not rdm_info:
        return {
            "agave_task_id": task_id or "",
            "testcase_id": testcase_id or "",
            "rdm_found": False,
            "rdm_message": "",
            "generated_comment": "",
            "pattern_matched": False,
            "failed_nodes": [],
            "next_action": "",
        }
    pattern_result = match_rdm_pattern(rdm_info["rdm_message"])
    return {
        "agave_task_id": task_id or "",
        "testcase_id": testcase_id or "",
        "rdm_found": True,
        "rdm_message": rdm_info["rdm_message"][:500],
        "rdm_link": rdm_info["rdm_link"],
        "rdm_category": rdm_info["rdm_category"],
        "rdm_resolution": rdm_info["rdm_resolution"],
        "rdm_source": rdm_info["rdm_source"],
        "jita_deployment_id": rdm_info.get("jita_deployment_id", ""),
        "failed_deployments": rdm_info["failed_deployment_count"],
        "total_deployments": rdm_info["total_deployment_count"],
        "pattern_matched": bool(pattern_result),
        "generated_comment": pattern_result["generated_comment"] if pattern_result else "",
        "pattern_id": pattern_result["pattern_id"] if pattern_result else "",
        "pattern_category": pattern_result["category"] if pattern_result else "",
        "pattern_description": pattern_result["description"] if pattern_result else "",
        "pattern_jira": pattern_result.get("jira", "") if pattern_result else "",
        "failed_nodes": pattern_result.get("failed_nodes", []) if pattern_result else [],
        "next_action": pattern_result.get("next_action", "") if pattern_result else "",
    }


def _process_rdm_approve_and_fix(row, retrigger=False):
    """
    Approve JITA comment, optionally disable Jarvis nodes, optionally rerun.

    row keys: testcase_id, testcase_name, agave_task_id, comment, jira_tickets,
              rdm_link, failed_nodes, pattern_category, next_action,
              pattern_matched (optional).
    """
    test_id = row.get("testcase_id") or row.get("test_id")
    comment = row.get("comment") or row.get("generated_comment") or ""
    jira_tickets = row.get("jira_tickets")
    rdm_link = row.get("rdm_link") or ""
    failed_nodes = row.get("failed_nodes") or []
    category = row.get("pattern_category") or row.get("category") or ""
    next_action = row.get("next_action") or ""
    disabled_by = _current_user_email()

    result = {
        "testcase_id": test_id,
        "testcase_name": row.get("testcase_name", ""),
        "agave_task_id": row.get("agave_task_id", ""),
        "comment": comment,
        "disabled_by": disabled_by,
        "jarvis_results": [],
        "retrigger": None,
        "triage_updated": False,
    }

    if test_id and comment:
        ok, payload = _apply_jita_triage_update(test_id, comment, jira_tickets)
        result["triage_updated"] = ok
        result["triage"] = payload
        if not ok:
            result["success"] = False
            result["error"] = payload.get("error", "JITA triage update failed")
            return result
    elif test_id and not comment:
        result["success"] = False
        result["error"] = "comment is required"
        return result

    if _rdm_should_disable(category, next_action, failed_nodes):
        if not failed_nodes:
            result["jarvis_error"] = "Pattern requires node disable but no node names were extracted"
        else:
            result["jarvis_results"] = _disable_rdm_nodes(failed_nodes, rdm_link, disabled_by)
            if any(not jr.get("success") for jr in result["jarvis_results"]):
                result["success"] = False
                result["error"] = "One or more Jarvis node disable operations failed"
                return result

    if retrigger and _rdm_should_rerun(next_action, category):
        tests = [{
            "testcase_id": test_id,
            "testcase_name": row.get("testcase_name", ""),
            "agave_task_id": row.get("agave_task_id", ""),
        }]
        result["retrigger"] = _rerun_selected_tests(tests, overrides={})

    jarvis_ok = all(jr.get("success") for jr in result["jarvis_results"]) if result["jarvis_results"] else True
    retrigger_ok = True
    if result["retrigger"] is not None:
        retrigger_ok = bool(result["retrigger"].get("success"))
    result["success"] = jarvis_ok and retrigger_ok
    return result


@app.route("/mcp/regression/failed-analysis/rdm-approve", methods=["POST"])
@jwt_required
def rdm_approve_comment_and_fix():
    """
    Approve a pattern-matched RDM comment, disable failed nodes in Jarvis,
    and optionally re-run the test.

    Body: testcase_id, comment, jira_tickets?, rdm_link, failed_nodes[],
          pattern_category, next_action, retrigger (bool)
    """
    try:
        data = request.get_json() or {}
        test_id = data.get("testcase_id") or data.get("test_id")
        if not test_id:
            return jsonify({"error": "testcase_id is required"}), 400
        result = _process_rdm_approve_and_fix(data, retrigger=bool(data.get("retrigger")))
        return jsonify(result)
    except Exception as e:
        logger.error(f"RDM approve error: {e}", exc_info=True)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/mcp/regression/failed-analysis/rdm-auto-workflow", methods=["POST"])
@jwt_required
def rdm_auto_workflow():
    """
    Pattern-matched complete workflow: analyze RDM failure, update JITA comment,
    disable Jarvis node(s) when next_action is disable_node_and_rerun, then
    rerun selected tests once on the parent JITA task (same as the JITA UI
    rerun of the parent with those tests selected).

    Body: tests[], retrigger (bool, default true), parent_task_id? (preferred
    JITA task to POST /rerun against).

    Only runs the fix/rerun steps when a pattern matches. Unmatched rows are
    returned with pattern_matched=false and are not auto-fixed.
    """
    try:
        data = request.get_json() or {}
        tests = data.get("tests") or []
        if not tests:
            return jsonify({"error": "tests array is required"}), 400

        retrigger = data.get("retrigger", True)
        results = []
        rerun_candidates = []
        for row in tests:
            task_id = row.get("agave_task_id")
            rdm = row.get("rdm_info") or {}
            if not rdm.get("pattern_matched"):
                if not task_id:
                    results.append({
                        "testcase_id": row.get("testcase_id"),
                        "success": False,
                        "pattern_matched": False,
                        "error": "agave_task_id is required to analyze RDM failure",
                    })
                    continue
                rdm = _analyze_one_rdm_task(
                    task_id,
                    testcase_id=row.get("testcase_id"),
                    deployment_id=row.get("deployment_id"),
                )

            if not rdm.get("pattern_matched"):
                results.append({
                    "testcase_id": row.get("testcase_id"),
                    "testcase_name": row.get("testcase_name", ""),
                    "agave_task_id": task_id,
                    "success": False,
                    "pattern_matched": False,
                    "rdm_info": rdm,
                    "error": "No pattern match — Analyze, Fix & Re-run only runs for pattern-matched failures",
                })
                continue

            payload = {
                "testcase_id": row.get("testcase_id"),
                "testcase_name": row.get("testcase_name", ""),
                "agave_task_id": task_id,
                "comment": rdm.get("generated_comment") or row.get("comment") or "",
                "jira_tickets": row.get("jira_tickets") or ([rdm.get("pattern_jira")] if rdm.get("pattern_jira") else None),
                "rdm_link": rdm.get("rdm_link") or "",
                "failed_nodes": rdm.get("failed_nodes") or [],
                "pattern_category": rdm.get("pattern_category") or rdm.get("category") or "",
                "next_action": rdm.get("next_action") or "",
            }
            # Approve / disable per test; one parent-task JITA rerun below.
            processed = _process_rdm_approve_and_fix(payload, retrigger=False)
            processed["pattern_matched"] = True
            processed["rdm_info"] = rdm
            results.append(processed)
            if (
                retrigger
                and processed.get("success") is not False
                and _rdm_should_rerun(payload.get("next_action"), payload.get("pattern_category"))
                and task_id
            ):
                rerun_candidates.append({
                    "testcase_id": row.get("testcase_id"),
                    "testcase_name": row.get("testcase_name", ""),
                    "agave_task_id": task_id,
                })

        if retrigger and rerun_candidates:
            parent_task_id = _resolve_rerun_parent_task_id(
                rerun_candidates,
                data.get("parent_task_id") or data.get("agave_task_id"),
            )
            logger.info(
                "[rdm-auto-workflow] One parent rerun on %s for %s test(s)",
                parent_task_id,
                len(rerun_candidates),
            )
            batch = _rerun_selected_tests(
                rerun_candidates,
                overrides={},
                parent_task_id=parent_task_id,
            )
            task_rerun = (batch.get("results") or [None])[0]
            candidate_keys = {
                (c.get("testcase_id") or c.get("testcase_name") or "")
                for c in rerun_candidates
            }
            for processed in results:
                key = processed.get("testcase_id") or processed.get("testcase_name") or ""
                if not task_rerun or key not in candidate_keys:
                    continue
                processed["retrigger"] = {
                    "success": bool(task_rerun.get("success")),
                    "total": 1,
                    "succeeded": 1 if task_rerun.get("success") else 0,
                    "failed": 0 if task_rerun.get("success") else 1,
                    "parent_task_id": parent_task_id,
                    "rerun_task_id": task_rerun.get("rerun_task_id"),
                    "results": [task_rerun],
                }
                if processed.get("success") is not False:
                    processed["success"] = bool(task_rerun.get("success"))
                    if not task_rerun.get("success"):
                        processed["error"] = task_rerun.get("error") or "JITA retrigger failed"

        succeeded = sum(1 for r in results if r.get("success"))
        return jsonify({
            "success": succeeded == len(results) and len(results) > 0,
            "total": len(results),
            "succeeded": succeeded,
            "failed": len(results) - succeeded,
            "results": results,
        })
    except Exception as e:
        logger.error(f"RDM auto-workflow error: {e}", exc_info=True)
        return jsonify({"success": False, "error": str(e)}), 500


