def _oid_bounds_for_local_date(date_str):
    """Return (start_oid, end_oid) hex ObjectIds spanning a local calendar date.

    MongoDB ObjectIds embed the creation time (UTC seconds) in their leading 4
    bytes, so an ``_id`` range filters strictly by creation timestamp. ``date_str``
    is ``YYYY-MM-DD`` in the server's local timezone (same as the user's). Returns
    ``None`` if the date can't be parsed.
    """
    try:
        day_start = datetime.strptime(date_str.strip(), "%Y-%m-%d")
    except (ValueError, AttributeError):
        return None
    start_ts = int(day_start.timestamp())
    end_ts = int((day_start + timedelta(days=1)).timestamp())
    start_oid = f"{start_ts:08x}" + "0" * 16
    end_oid = f"{end_ts:08x}" + "0" * 16
    return start_oid, end_oid


@app.route("/mcp/regression/dynamic-jp/search", methods=["POST"])
def dynamic_jp_search():
    """Search Job Profiles and Test Sets by name and/or creation date.

    Either ``query`` (>= 2 chars name substring) or ``date`` (YYYY-MM-DD) is
    required; both may be combined. When ``date`` is supplied, results are limited
    to entities **created by this tool** (JITA service account) on that calendar
    date, using an ObjectId creation-timestamp range.
    """
    try:
        req_data = request.json or {}
        query = (req_data.get("query") or "").strip()
        date_str = (req_data.get("date") or "").strip()
        # When true, treat `query` as a raw regular expression (Release Migration uses
        # this to target JP families like "CDP_Regression_FullReg_7\.6\.0\.6_.*").
        # Otherwise the query is escaped and matched as a literal substring.
        use_regex = bool(req_data.get("regex", False))
        # Callers that only need one collection can skip the other. An unindexed
        # name-regex scan on JITA is slow, so skipping the unused query (e.g. Release
        # Migration only needs job profiles) avoids a second ~20s round-trip.
        include_job_profiles = bool(req_data.get("include_job_profiles", True))
        include_test_sets = bool(req_data.get("include_test_sets", True))

        # Multi-term search: in literal mode a "|"-separated query like "CDP | 7.5.1"
        # matches names that contain ALL of the terms (AND), mirroring the JITA UI where
        # adding words narrows the result set. In regex mode we keep the whole query
        # intact so "|" behaves as native regex alternation (Release Migration relies on it).
        if use_regex:
            search_terms = [query] if query else []
        else:
            search_terms = [t.strip() for t in query.split("|") if t.strip()]

        if not any(len(t) >= 2 for t in search_terms) and not date_str:
            return jsonify({"error": "Provide a search term (>= 2 chars) or pick a date"}), 400

        if use_regex:
            for t in search_terms:
                try:
                    re.compile(t)
                except re.error as rex:
                    return jsonify({"error": f"Invalid regular expression '{t}': {rex}"}), 400

        date_cond = None
        if date_str:
            bounds = _oid_bounds_for_local_date(date_str)
            if not bounds:
                return jsonify({"error": "date must be YYYY-MM-DD"}), 400
            start_oid, end_oid = bounds
            date_cond = {"_id": {"$gte": {"$oid": start_oid}, "$lt": {"$oid": end_oid}}}

        def _name_regex(term):
            return {"name": {"$regex": term if use_regex else re.escape(term), "$options": "i"}}

        if not search_terms:
            name_cond = None
        elif len(search_terms) == 1:
            name_cond = _name_regex(search_terms[0])
        else:
            # AND semantics: the name must contain every term (order-independent).
            name_cond = {"$and": [_name_regex(t) for t in search_terms]}

        # "Created by this tool" marker: every dynamic JP/TS is tagged with the
        # cdp_reg_jarvis user group (JITA's created_by is an opaque ObjectId and is
        # unreliable). Only applied when a date is selected so plain name search keeps
        # its broad behaviour.
        tool_cond = {"user_groups": {"$in": ["cdp_reg_jarvis"]}}
        jp_tool_cond = tool_cond
        ts_tool_cond = tool_cond

        def _build_raw_query(tool_cond):
            conds = []
            if name_cond:
                conds.append(name_cond)
            if date_cond:
                conds.append(date_cond)
                conds.append(tool_cond)
            if not conds:
                return None
            return json.dumps({"$and": conds} if len(conds) > 1 else conds[0])

        # JITA honors a large single `limit` and returns a top-level `total`, so we
        # fetch everything that matches in one request (like the JITA UI, which shows
        # "N of TOTAL") instead of an arbitrary 20. Capped high for safety.
        SEARCH_MAX_LIMIT = int(os.getenv("JITA_SEARCH_MAX_LIMIT", "2000"))
        limit = min(int(req_data.get("limit", SEARCH_MAX_LIMIT)), SEARCH_MAX_LIMIT)
        result = {"job_profiles": [], "test_sets": []}
        totals = {"job_profiles": 0, "test_sets": 0}
        # Timeouts/failures are surfaced here so the UI can tell "no matches" apart
        # from "the JITA scan was too slow" (a silent empty result is misleading).
        warnings = []

        def _extract_id(item):
            eid = item.get("_id")
            if isinstance(eid, dict) and "$oid" in eid:
                return eid["$oid"]
            return str(eid) if eid else None

        jp_raw_q = _build_raw_query(jp_tool_cond) if include_job_profiles else None
        if jp_raw_q:
            try:
                jp_resp = requests.get(
                    f"{JITA_BASE}/job_profiles",
                    params={"raw_query": jp_raw_q, "limit": limit, "sort": "-_id",
                            "only": "_id,name,description,tags,created_at"},
                    auth=JITA_SVC_AUTH, verify=False, timeout=JITA_SEARCH_TIMEOUT,
                )
                if jp_resp.status_code == 200:
                    jp_body = jp_resp.json() or {}
                    for item in (jp_body.get("data", []) or []):
                        if not isinstance(item, dict):
                            continue
                        result["job_profiles"].append({
                            "_id": _extract_id(item),
                            "name": item.get("name", ""),
                            "description": item.get("description", ""),
                            "created_at": item.get("created_at"),
                        })
                    totals["job_profiles"] = jp_body.get("total", len(result["job_profiles"]))
                else:
                    warnings.append(f"Job profile search returned HTTP {jp_resp.status_code}.")
                    logger.warning(f"[search] JP search HTTP {jp_resp.status_code}: {jp_resp.text[:200]}")
            except requests.exceptions.Timeout:
                warnings.append(
                    "Job profile search timed out. Narrow the query (add more of the name) "
                    "or lower the result limit, then retry."
                )
                logger.warning("[search] JP search timed out")
            except Exception as e:
                warnings.append(f"Job profile search failed: {e}")
                logger.warning(f"[search] JP search failed: {e}")

        if include_test_sets:
            # Test-set name regex is unindexed and slow. Prefer exact match for a
            # single literal term, then a modest substring scan with a longer
            # timeout (Manage JP used to time out at 25s with limit=200 → empty TS).
            ts_limit = min(int(req_data.get("ts_limit", min(limit, 50))), 50)
            ts_timeout = max(int(JITA_SEARCH_TIMEOUT), 45)

            def _run_ts_search(raw_q, lim, timeout_s):
                return requests.get(
                    f"{JITA_BASE}/test_sets",
                    params=_jita_test_sets_search_params(raw_q, lim),
                    auth=JITA_SVC_AUTH, verify=False, timeout=timeout_s,
                )

            def _append_ts_hits(items):
                for item in items or []:
                    if not isinstance(item, dict):
                        continue
                    eid = _extract_id(item)
                    if eid and any(r.get("_id") == eid for r in result["test_sets"]):
                        continue
                    result["test_sets"].append({
                        "_id": eid,
                        "name": item.get("name", ""),
                        "description": item.get("description", ""),
                        "created_at": item.get("created_at"),
                        "test_args": item.get("test_args", "") or item.get("testArgs", "") or "",
                        "framework_args": item.get("framework_args", "") or item.get("frameworkArgs", "") or "",
                        "args_map": item.get("args_map", {}) or {},
                        "agave_options": item.get("agave_options", {}) or {},
                        "test_args_map": _manage_ts_extract_test_args(item),
                        "framework_args_map": _manage_ts_extract_framework_args(item),
                    })

            def _ts_query_with_name(name_clause):
                conds = [name_clause]
                if date_cond:
                    conds.append(date_cond)
                    conds.append(ts_tool_cond)
                return json.dumps({"$and": conds} if len(conds) > 1 else conds[0])

            # Fast path: exact name (indexed) for a single literal term.
            if (
                not use_regex
                and len(search_terms) == 1
                and len(search_terms[0]) >= 2
            ):
                exact_q = _ts_query_with_name({"name": search_terms[0]})
                try:
                    exact_resp = _run_ts_search(exact_q, min(ts_limit, 20), 15)
                    if exact_resp.status_code == 200:
                        exact_body = exact_resp.json() or {}
                        exact_data = exact_body.get("data", []) or []
                        if exact_data:
                            _append_ts_hits(exact_data)
                            totals["test_sets"] = exact_body.get("total", len(result["test_sets"]))
                            logger.info(
                                f"[search] TS exact-name hit for {search_terms[0]!r}: "
                                f"{len(result['test_sets'])} row(s)"
                            )
                except requests.exceptions.RequestException as e:
                    logger.warning(f"[search] TS exact-name lookup failed: {e}")

            ts_raw_q = _build_raw_query(ts_tool_cond)
            if ts_raw_q and not result["test_sets"]:
                ts_resp = None
                try:
                    ts_resp = _run_ts_search(ts_raw_q, ts_limit, ts_timeout)
                except requests.exceptions.Timeout:
                    logger.warning(
                        f"[search] TS search timed out (limit={ts_limit}, timeout={ts_timeout}s); "
                        "retrying with limit=15"
                    )
                    try:
                        ts_resp = _run_ts_search(ts_raw_q, 15, max(ts_timeout, 60))
                    except requests.exceptions.Timeout:
                        ts_resp = None
                        warnings.append(
                            "Test set search timed out. Narrow the query (more of the name) "
                            "or search by date, then retry."
                        )
                        logger.warning("[search] TS search timed out on retry")
                except Exception as e:
                    warnings.append(f"Test set search failed: {e}")
                    logger.warning(f"[search] TS search failed: {e}")

                if ts_resp is not None:
                    if ts_resp.status_code == 200:
                        ts_body = ts_resp.json() or {}
                        _append_ts_hits(ts_body.get("data", []) or [])
                        totals["test_sets"] = ts_body.get("total", len(result["test_sets"]))
                    else:
                        warnings.append(f"Test set search returned HTTP {ts_resp.status_code}.")
                        logger.warning(
                            f"[search] TS search HTTP {ts_resp.status_code}: {ts_resp.text[:200]}"
                        )
            elif result["test_sets"] and not totals["test_sets"]:
                totals["test_sets"] = len(result["test_sets"])

        # Note when JITA reports more matches than we returned (shouldn't happen with
        # the high cap, but keeps the UI honest if a query exceeds SEARCH_MAX_LIMIT).
        for kind, human in (("job_profiles", "job profiles"), ("test_sets", "test sets")):
            if totals[kind] > len(result[kind]):
                warnings.append(
                    f"Showing {len(result[kind])} of {totals[kind]} matching {human}. "
                    f"Refine the search to see the rest."
                )

        return jsonify({
            "success": True,
            "warnings": warnings,
            "totals": totals,
            **result,
        })
    except Exception as e:
        logger.error(f"Error in dynamic-jp search: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/mcp/regression/dynamic-jp/manage-ts/inspect", methods=["POST"])
@jwt_required
def manage_ts_inspect():
    """Inspect selected test sets and return the union of framework/test arguments."""
    try:
        req_data = request.json or {}
        ts_ids = req_data.get("ts_ids") or []
        if not isinstance(ts_ids, list):
            return jsonify({"error": "ts_ids must be an array"}), 400
        ts_ids = [str(i).strip() for i in ts_ids if str(i).strip()]
        if not ts_ids:
            return jsonify({"error": "At least one test set id is required"}), 400

        per_ts = []
        errors = []
        for ts_id in ts_ids:
            try:
                per_ts.append(_manage_ts_fetch_test_set(ts_id))
            except Exception as e:
                errors.append({"ts_id": ts_id, "error": str(e)})

        if errors:
            return jsonify({"error": "Failed to fetch one or more test sets", "details": errors}), 502

        common = _manage_ts_compute_common_args(per_ts)
        return jsonify({
            "success": True,
            "selected_count": len(per_ts),
            "test_sets": [{"_id": row["id"], "name": row["name"]} for row in per_ts],
            "common_framework_args": common["framework_args"],
            "common_test_args": common["test_args"],
        })
    except Exception as e:
        logger.error(f"Error in manage-ts inspect: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/mcp/regression/dynamic-jp/manage-ts/preview", methods=["POST"])
@jwt_required
def manage_ts_preview():
    """Dry-run bulk test-set argument updates and return full diff summary."""
    try:
        req_data = request.json or {}
        ts_ids = req_data.get("ts_ids") or []
        if not isinstance(ts_ids, list):
            return jsonify({"error": "ts_ids must be an array"}), 400
        ts_ids = [str(i).strip() for i in ts_ids if str(i).strip()]
        if not ts_ids:
            return jsonify({"error": "At least one test set id is required"}), 400

        try:
            edits_framework, edits_test, new_args = _manage_ts_normalize_update_maps(req_data)
        except ValueError as vex:
            return jsonify({"error": str(vex)}), 400

        ts_rows = []
        errors = []
        for ts_id in ts_ids:
            try:
                ts_rows.append(_manage_ts_fetch_test_set(ts_id))
            except Exception as e:
                errors.append({"ts_id": ts_id, "error": str(e)})
        if errors:
            return jsonify({"error": "Failed to fetch one or more test sets", "details": errors}), 502

        preview_rows, totals = _manage_ts_build_preview_rows(ts_rows, edits_framework, edits_test, new_args)
        return jsonify({
            "success": True,
            "dry_run": True,
            "summary": totals,
            "preview": preview_rows,
        })
    except Exception as e:
        logger.error(f"Error in manage-ts preview: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/mcp/regression/dynamic-jp/manage-ts/apply", methods=["POST"])
@jwt_required
def manage_ts_apply():
    """Apply bulk test-set argument updates after user-reviewed dry run."""
    try:
        req_data = request.json or {}
        ts_ids = req_data.get("ts_ids") or []
        if not isinstance(ts_ids, list):
            return jsonify({"error": "ts_ids must be an array"}), 400
        ts_ids = [str(i).strip() for i in ts_ids if str(i).strip()]
        if not ts_ids:
            return jsonify({"error": "At least one test set id is required"}), 400

        try:
            edits_framework, edits_test, new_args = _manage_ts_normalize_update_maps(req_data)
        except ValueError as vex:
            return jsonify({"error": str(vex)}), 400

        ts_rows = []
        fetch_errors = []
        for ts_id in ts_ids:
            try:
                ts_rows.append(_manage_ts_fetch_test_set(ts_id))
            except Exception as e:
                fetch_errors.append({"ts_id": ts_id, "error": str(e)})
        if fetch_errors:
            return jsonify({"error": "Failed to fetch one or more test sets", "details": fetch_errors}), 502

        preview_rows, totals = _manage_ts_build_preview_rows(ts_rows, edits_framework, edits_test, new_args)
        update_targets = [row for row in preview_rows if row["changed"] and row.get("put_payload")]
        if not update_targets:
            return jsonify({
                "success": True,
                "updated_count": 0,
                "failed_updates": [],
                "summary": totals,
                "results": [],
            })

        def _put_one(row):
            try:
                put_resp = requests.put(
                    f"{JITA_BASE}/test_sets/{row['ts_id']}",
                    json=_manage_ts_sanitize_for_json(row["put_payload"]),
                    auth=JITA_SVC_AUTH,
                    verify=False,
                    timeout=30,
                )
                ok = put_resp.status_code == 200
                msg = "Updated" if ok else (put_resp.text[:500] if put_resp.text else f"HTTP {put_resp.status_code}")
                return {
                    "ts_id": row["ts_id"],
                    "ts_name": row["ts_name"],
                    "success": ok,
                    "message": msg,
                    "changed_framework_args": row["changed_framework_args"],
                    "changed_test_args": row["changed_test_args"],
                    "collision_skips": row["collision_skips"],
                }
            except Exception as e:
                return {
                    "ts_id": row["ts_id"],
                    "ts_name": row["ts_name"],
                    "success": False,
                    "message": str(e),
                    "changed_framework_args": row["changed_framework_args"],
                    "changed_test_args": row["changed_test_args"],
                    "collision_skips": row["collision_skips"],
                }

        results = []
        max_workers = min(10, len(update_targets)) or 1
        with ThreadPoolExecutor(max_workers=max_workers) as pool:
            future_to_idx = {
                pool.submit(_put_one, row): idx
                for idx, row in enumerate(update_targets)
            }
            ordered = [None] * len(update_targets)
            for fut in as_completed(future_to_idx):
                idx = future_to_idx[fut]
                ordered[idx] = fut.result()
            results = ordered

        updated_count = len([r for r in results if r and r["success"]])
        failed_updates = [r for r in results if r and not r["success"]]
        return jsonify({
            "success": True,
            "updated_count": updated_count,
            "failed_updates": failed_updates,
            "summary": totals,
            "results": results,
        })
    except Exception as e:
        logger.error(f"Error in manage-ts apply: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


def _current_user_identifiers():
    """Identity aliases for the logged-in user, lowercased, for owner matching.

    Includes the JWT email, the username (sAMAccountName), the username with the
    default corp domain, and the local-part of the email. Matching any of these
    against an entity's owner emails counts as ownership.
    """
    cu = getattr(g, "current_user", None)
    username = (cu.get("sub") if isinstance(cu, dict) else "") or ""
    email = (cu.get("email") if isinstance(cu, dict) else "") or ""
    ids = set()
    username = username.strip().lower()
    email = email.strip().lower()
    if username:
        ids.add(username)
        ids.add(f"{username}@nutanix.com")
    if email:
        ids.add(email)
        ids.add(email.split("@")[0])  # local-part
    return {i for i in ids if i}


def _user_in_cdp_reg_jarvis(user_ids=None):
    """True if the logged-in user is a member of the cdp_reg_jarvis group roster."""
    if not CDP_REG_JARVIS_MEMBERS:
        return False
    ids = user_ids if user_ids is not None else _current_user_identifiers()
    return bool(ids & CDP_REG_JARVIS_MEMBERS)


_jita_user_cache = {}
_jita_user_cache_lock = threading.Lock()


def _resolve_jita_user(oid):
    """Resolve a JITA user ObjectId to its user record via /api/v1/users/<oid>.

    Cached process-wide so a bulk delete of many entities owned by the same
    person only hits JITA once for that owner.
    """
    if not oid:
        return {}
    with _jita_user_cache_lock:
        if oid in _jita_user_cache:
            return _jita_user_cache[oid]
    record = {}
    try:
        r = requests.get(f"{JITA_V1_BASE}/users/{oid}", auth=JITA_SVC_AUTH, verify=False, timeout=20)
        if r.status_code == 200:
            record = (r.json() or {}).get("data", {}) or {}
        else:
            logger.warning(f"[delete] user resolve {oid} -> HTTP {r.status_code}")
    except Exception as e:
        logger.warning(f"[delete] user resolve {oid} error: {e}")
    if record:
        with _jita_user_cache_lock:
            _jita_user_cache[oid] = record
    return record


# Markers that identify a JITA *service/bot/tool* account (not a real human).
# When a JP/TS is created by one of these (or created_by can't be resolved), the
# real owner is taken from the entity's ``emails`` list instead — that's where the
# RegX tool records the user who requested the clone/create.
_SERVICE_ACCOUNT_MARKERS = (
    "svc.", "svc_", "svc-", "_bot", "-bot", "bot_", "jarvis", "agave", "jenkins", "automation",
)


def _is_service_account(user_name, email=""):
    blob = f"{user_name or ''} {email or ''}".lower()
    return any(m in blob for m in _SERVICE_ACCOUNT_MARKERS)


def _emails_as_ids(entity_data):
    """Owner identifiers pulled from an entity's ``emails``/``user`` fields."""
    ids = set()
    emails = entity_data.get("emails") or []
    if isinstance(emails, str):
        emails = [emails]
    for e in emails:
        if isinstance(e, str) and e.strip():
            e = e.strip().lower()
            ids.add(e)
            if "@" in e:
                ids.add(e.split("@")[0])
    u = entity_data.get("user")
    if isinstance(u, str) and u.strip():
        u = u.strip().lower()
        ids.add(u)
        if "@" in u:
            ids.add(u.split("@")[0])
    return ids, (emails[0] if emails else None)


def _oid_from_ref(value):
    """Extract ObjectId string from a JITA ref (bare string, {$oid}, or {_id:{$oid}})."""
    if not value:
        return None
    if isinstance(value, str):
        v = value.strip()
        return v or None
    if isinstance(value, dict):
        if value.get("$oid"):
            return str(value["$oid"]).strip() or None
        inner = value.get("_id")
        if isinstance(inner, dict) and inner.get("$oid"):
            return str(inner["$oid"]).strip() or None
        if isinstance(inner, str) and inner.strip():
            return inner.strip()
    return None


def _owner_record_from_entity(entity_data):
    """Resolve the creator/owner user record from created_by_user / created_by / creator.

    Prefer the **creator** identity — never treat the notification ``emails`` list
    as the creator. ``emails`` is only used later for service-account-created JPs.
    """
    # 1) Expanded created_by_user (full user doc)
    cbu = entity_data.get("created_by_user")
    if isinstance(cbu, dict) and (cbu.get("user_name") or cbu.get("email") or cbu.get("display_name")):
        return cbu

    # 2) Explicit creator field (some JITA payloads)
    creator = entity_data.get("creator")
    if isinstance(creator, dict) and (creator.get("user_name") or creator.get("email") or creator.get("display_name")):
        return creator
    creator_oid = _oid_from_ref(creator)
    if creator_oid:
        resolved = _resolve_jita_user(creator_oid)
        if resolved:
            return resolved

    # 3) created_by ObjectId (string or {$oid}) — resolve via users API
    cb_oid = _oid_from_ref(entity_data.get("created_by"))
    if not cb_oid:
        cb_oid = _oid_from_ref(cbu)  # unexpanded created_by_user: {"$oid": "..."}
    if cb_oid:
        resolved = _resolve_jita_user(cb_oid)
        if resolved:
            return resolved

    return {}


def _entity_owner_identity(entity_data):
    """Resolve who is allowed to delete a JITA entity.

    Returns ``(owner_ids, owner_display)`` — a lowercased set of the owner's
    identifiers (user_name, email, email local-part) plus a human-readable name.

    Rules:
    - If **creator** / ``created_by`` / ``created_by_user`` resolves to a **real human**,
      ONLY that person may delete (notification ``emails`` are ignored).
    - If creator is a **service/bot/tool** account, fall back to ``emails``/``user``
      (where RegX records the human requester).
    - If creator cannot be resolved at all, return empty owner_ids (caller blocks delete).
    """
    owner = _owner_record_from_entity(entity_data or {})

    owner_user_name = (owner.get("user_name") or "").strip().lower()
    owner_email = (owner.get("email") or "").strip().lower()
    owner_display_name = (owner.get("display_name") or "").strip().lower()
    # Some expanded users only expose display_name/first_name
    if not owner_user_name and owner_display_name and " " not in owner_display_name:
        owner_user_name = owner_display_name

    creator_is_human = bool(owner_user_name or owner_email) and not _is_service_account(
        owner_user_name, owner_email
    )

    if creator_is_human:
        owner_ids = set()
        for v in (owner_user_name, owner_email):
            if v:
                owner_ids.add(v)
                if "@" in v:
                    owner_ids.add(v.split("@")[0])
        owner_display = (
            owner.get("user_name") or owner.get("email") or owner.get("display_name") or "another user"
        )
        return owner_ids, owner_display

    if owner_user_name or owner_email:
        # Resolved creator is a service/bot — allow requester(s) from emails/user.
        owner_ids, first_email = _emails_as_ids(entity_data)
        owner_display = (
            first_email
            or owner.get("user_name")
            or owner.get("display_name")
            or "the creator"
        )
        return owner_ids, owner_display

    # Creator unresolved — do NOT fall back to emails (would let any CC'd teammate delete).
    return set(), "unverified creator"


@app.route("/mcp/regression/dynamic-jp/delete", methods=["POST"])
@jwt_required
def dynamic_jp_delete():
    """Delete one or more Job Profiles and/or Test Sets by ID.

    JITA does **not** enforce per-entity ownership on delete (any authenticated
    user can delete any entity), so authorization is enforced here (see
    ``_entity_owner_identity``): a human-created entity may only be deleted by that
    human; a tool/service-created entity may be deleted by the user(s) recorded in
    its ``emails``. Non-owners — and entities whose ownership can't be verified —
    are blocked with a clear message instead of being deleted.
    """
    try:
        req_data = request.json or {}
        jp_ids = req_data.get("jp_ids", [])
        ts_ids = req_data.get("ts_ids", [])

        if not jp_ids and not ts_ids:
            return jsonify({"error": "At least one of jp_ids or ts_ids is required"}), 400

        if not isinstance(jp_ids, list):
            jp_ids = [jp_ids]
        if not isinstance(ts_ids, list):
            ts_ids = [ts_ids]

        jp_ids = [str(i).strip() for i in jp_ids if i]
        ts_ids = [str(i).strip() for i in ts_ids if i]

        current_username = g.current_user.get("sub", "") if isinstance(getattr(g, "current_user", None), dict) else ""
        user_ids = _current_user_identifiers()
        if not user_ids:
            return jsonify({
                "error": "Could not determine your identity from the session. Please re-login.",
                "code": "IDENTITY_UNKNOWN",
            }), 401
        is_admin = current_username.strip().lower() in JP_DELETE_ADMIN_USERS
        is_group_member = _user_in_cdp_reg_jarvis(user_ids)

        results = {"job_profiles": [], "test_sets": []}

        def _delete_with_ownership(kind, path, entity_id):
            label = "Job Profile" if kind == "job_profiles" else "Test Set"

            # 1) Fetch the entity (with owner expanded) to verify ownership before deleting.
            try:
                get_resp = requests.get(
                    f"{JITA_BASE}/{path}/{entity_id}",
                    params={"expand": "created_by_user"},
                    auth=JITA_SVC_AUTH, verify=False, timeout=30,
                )
            except Exception as e:
                logger.warning(f"[delete] {label} {entity_id} lookup error: {e}")
                return {"_id": entity_id, "success": False, "message": f"Could not look up {label}: {e}"}

            if get_resp.status_code == 404:
                return {"_id": entity_id, "success": False, "message": f"{label} not found (already deleted?)."}
            if get_resp.status_code != 200:
                return {"_id": entity_id, "success": False,
                        "message": f"Could not verify ownership ({label} lookup HTTP {get_resp.status_code})."}

            entity = (get_resp.json() or {}).get("data", {}) or {}
            entity_name = entity.get("name", entity_id)
            owner_ids, owner_display = _entity_owner_identity(entity)
            entity_groups = entity.get("user_groups") or []
            is_regx_managed = CDP_REG_JARVIS_GROUP in entity_groups

            # 2) Authorization decision — mirror JITA: only the real owner (created_by)
            #    may delete. Exceptions: the admin allowlist, and members of the
            #    cdp_reg_jarvis group for any RegX-managed (tagged) entity.
            if is_admin:
                logger.info(f"[delete] admin '{current_username}' authorized to delete {label} '{entity_name}'")
            elif is_group_member and is_regx_managed:
                logger.info(
                    f"[delete] cdp_reg_jarvis member '{current_username}' authorized to delete "
                    f"RegX-managed {label} '{entity_name}'"
                )
            elif not owner_ids:
                # Owner could not be resolved => cannot prove ownership. Block (safe default).
                logger.warning(
                    f"[delete] {label} '{entity_name}' ({entity_id}) owner unresolved; "
                    f"blocking delete requested by '{current_username}'"
                )
                return {
                    "_id": entity_id, "success": False, "unauthorized": True,
                    "message": f"You are not authorized to delete this {label}: its owner could not be verified.",
                }
            elif user_ids.isdisjoint(owner_ids):
                logger.warning(
                    f"[delete] BLOCKED: '{current_username}' is not the owner of {label} "
                    f"'{entity_name}' ({entity_id}); owner={owner_display}"
                )
                return {
                    "_id": entity_id, "success": False, "unauthorized": True,
                    "owner": owner_display,
                    "message": f"You are not authorized to delete this {label}. Only the owner ({owner_display}) can delete it.",
                }

            # 3) Ownership confirmed — perform the delete (service account always has rights).
            try:
                del_resp = requests.delete(
                    f"{JITA_BASE}/{path}/{entity_id}",
                    auth=JITA_SVC_AUTH, verify=False, timeout=30,
                )
            except Exception as e:
                logger.warning(f"[delete] {label} {entity_id} delete error: {e}")
                return {"_id": entity_id, "success": False, "message": str(e)}

            if del_resp.status_code in (200, 204):
                logger.info(f"[delete] {label} '{entity_name}' ({entity_id}) deleted by owner '{current_username}'")
                return {"_id": entity_id, "success": True, "message": "Deleted"}

            msg = f"JITA returned HTTP {del_resp.status_code}"
            try:
                msg = del_resp.json().get("message", msg)
            except Exception:
                pass
            return {"_id": entity_id, "success": False, "message": msg}

        # Process every selected entity independently and in parallel so bulk
        # deletes (100+ items with mixed ownership) stay fast. Each item is fetched,
        # ownership-checked, and deleted (or blocked) on its own — one blocked item
        # never affects the others. Order is preserved to match the request.
        def _run(kind, path, ids):
            if not ids:
                return []
            ordered = [None] * len(ids)
            max_workers = min(10, len(ids)) or 1
            with ThreadPoolExecutor(max_workers=max_workers) as pool:
                future_to_idx = {
                    pool.submit(_delete_with_ownership, kind, path, eid): i
                    for i, eid in enumerate(ids)
                }
                for fut in as_completed(future_to_idx):
                    i = future_to_idx[fut]
                    try:
                        ordered[i] = fut.result()
                    except Exception as e:
                        ordered[i] = {"_id": ids[i], "success": False, "message": str(e)}
            return ordered

        results["job_profiles"] = _run("job_profiles", "job_profiles", jp_ids)
        results["test_sets"] = _run("test_sets", "test_sets", ts_ids)

        all_items = results["job_profiles"] + results["test_sets"]
        all_ok = bool(all_items) and all(r["success"] for r in all_items)
        any_unauthorized = any(r.get("unauthorized") for r in all_items)
        return jsonify({"success": all_ok, "unauthorized": any_unauthorized, "results": results})
    except Exception as e:
        logger.error(f"Error in dynamic-jp delete: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/mcp/regression/debug/inspect-jp/<jp_id>", methods=["GET"])
def debug_inspect_jp(jp_id):
    """Debug endpoint to inspect JP structure from JITA"""
    try:
        jp_resp = requests.get(
            f"{JITA_BASE}/job_profiles/{jp_id}",
            auth=JITA_SVC_AUTH,
            verify=False,
            timeout=30
        )
        if jp_resp.status_code != 200:
            return jsonify({"error": f"Failed to fetch JP (HTTP {jp_resp.status_code})"}), jp_resp.status_code
        
        jp_data = jp_resp.json().get("data", {})
        
        # Extract email-related fields
        email_fields = {}
        for key in jp_data.keys():
            if 'email' in key.lower() or 'mail' in key.lower() or key in ['emails', 'user_groups', 'scheduling_options']:
                email_fields[key] = jp_data.get(key)

        return jsonify({
            "jp_id": jp_id,
            "jp_name": jp_data.get("name"),
            "all_keys": list(jp_data.keys()),
            "email_related_fields": email_fields
        })
    except Exception as e:
        logger.error(f"Error inspecting JP: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


# ======================================================
# AI Analysis Endpoints
# ======================================================

def _call_ai_chat(system_prompt, user_content, max_tokens=2048):
    """Helper to call the Nutanix AI chat endpoint."""
    payload = {
        "model": "hack-reason",
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_content}
        ],
        "max_tokens": max_tokens,
        "stream": False
    }
    url = f"{AI_BASE}/chat/completions"
    headers = {
        "Authorization": f"Bearer {AI_API_KEY}",
        "Accept": "application/json",
        "Content-Type": "application/json"
    }
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(url, data=data, headers=headers, method="POST")
    with urllib.request.urlopen(req, context=SSL_CTX, timeout=90) as resp:
        if resp.getcode() != 200:
            raise Exception(f"AI API returned HTTP {resp.getcode()}")
        response_data = json.loads(resp.read().decode())
        choices = response_data.get("choices", [])
        if not choices:
            raise Exception("AI returned no choices")
        content = (choices[0].get("message") or {}).get("content", "")
        return content.strip()


def _build_owner_tickets_fallback_analysis(all_tickets, jira_details, owner_for_ticket, ticket_test_count, tag):
    """Generate deterministic markdown when AI endpoint is unavailable for owner tickets analysis."""
    table_header = (
        "| Ticket ID | Owner | Status | Issue Type | Root Cause Category | Impact | AI Recommended Action |\n"
        "| --- | --- | --- | --- | --- | --- | --- |"
    )
    table_rows = []
    for ticket_id in sorted(all_tickets):
        jd = jira_details.get(ticket_id, {})
        owners = ", ".join(owner_for_ticket.get(ticket_id, []))
        tc_count = ticket_test_count.get(ticket_id, 0)
        status = jd.get("status", "N/A")
        issue_type = jd.get("issue_type", "N/A")
        
        # Simple classification based on issue type
        if "bug" in issue_type.lower():
            root_cause = "Product" if "product" in jd.get("summary", "").lower() else "Test"
        elif "test" in issue_type.lower():
            root_cause = "Test"
        else:
            root_cause = "Unknown"
        
        impact = f"{tc_count} testcase(s) affected"
        
        # Recommendation based on status
        if status.lower() in ["open", "to do", "new"]:
            recommended_action = "Prioritize triage and assign to appropriate owner"
        elif status.lower() in ["in progress", "in review"]:
            recommended_action = "Monitor progress and verify fix"
        elif status.lower() in ["resolved", "closed", "done"]:
            recommended_action = "Verify fix is complete and re-run affected tests"
        else:
            recommended_action = "Review status and update as needed"
        
        table_rows.append(
            f"| {ticket_id} | {owners or 'Unassigned'} | {status} | {issue_type} | {root_cause} | {impact} | {recommended_action} |"
        )
    
    analysis = (
        f"# Owner Ticket Breakdown Analysis\n\n"
        f"**Note:** AI analysis endpoint unavailable. Showing basic breakdown.\n\n"
        f"**Regression Tag:** {tag}\n"
        f"**Total Unique Tickets:** {len(all_tickets)}\n\n"
        f"## Ticket Details\n\n"
        f"{table_header}\n" + "\n".join(table_rows) + "\n\n"
        f"## Summary\n\n"
        f"- Total tickets requiring attention: {len(all_tickets)}\n"
        f"- Please review each ticket status and ensure proper ownership assignment\n"
        f"- Priority should be given to tickets with multiple testcases impacted\n\n"
        f"## Recommended Actions\n\n"
        f"1. Review all Open/To Do tickets and assign owners\n"
        f"2. Monitor In Progress tickets for timely completion\n"
        f"3. Verify Resolved/Closed tickets and re-run affected tests\n"
    )
    return analysis


def _build_bulk_issues_fallback_analysis(issue_rows, tag, total_tests):
    """Generate deterministic markdown when external AI endpoint is unavailable."""
    table_header = (
        "| Bug ID | Affected Feature | Testcases Impacted | QI Impact | Risk Level | Impact | Recommended Action |\n"
        "| --- | --- | ---: | ---: | --- | --- | --- |"
    )
    table_rows = []
    for row in issue_rows:
        ticket = row["ticket"]
        feature = row["feature"] or "Unknown"
        testcase_count = row["testcase_count"]
        qi_impact = row["qi_impact"]
        risk_level = row["risk_level"]
        impact = (
            f"Potentially impacts {testcase_count} testcases in {feature}."
            if feature != "Unknown"
            else f"Potentially impacts {testcase_count} testcases across multiple areas."
        )
        recommended_action = (
            "Validate ownership, confirm reproducibility, and prioritize based on QI impact."
        )
        table_rows.append(
            f"| {ticket} | {feature} | {testcase_count} | {qi_impact} | {risk_level} | {impact} | {recommended_action} |"
        )

    critical_count = sum(1 for row in issue_rows if row["risk_level"] == "Critical")
    high_count = sum(1 for row in issue_rows if row["risk_level"] == "High")
    medium_count = sum(1 for row in issue_rows if row["risk_level"] == "Medium")
    risk_score = min(100, critical_count * 30 + high_count * 20 + medium_count * 10 + 15)
    readiness = (
        "Not Ready"
        if critical_count > 0
        else "At Risk"
        if high_count > 0
        else "Proceed with Caution"
        if medium_count > 0
        else "Ready with Monitoring"
    )

    top_three = sorted(
        issue_rows,
        key=lambda r: (
            {"Critical": 4, "High": 3, "Medium": 2, "Low": 1}.get(r["risk_level"], 0),
            abs(float(r["qi_impact"])),
        ),
        reverse=True,
    )[:3]

    priorities = "\n".join(
        f"- {row['ticket']} ({row['risk_level']}, QI impact {row['qi_impact']}%)"
        for row in top_three
    ) or "- No priority tickets identified"

    return (
        "_AI endpoint unreachable. Showing deterministic fallback analysis._\n\n"
        f"**Regression Tag:** `{tag or 'N/A'}`  \n"
        f"**Total Tests in Run:** `{total_tests}`  \n"
        f"**Bulk Issues:** `{len(issue_rows)}`\n\n"
        f"{table_header}\n"
        + "\n".join(table_rows)
        + "\n\n"
        + f"### Overall Summary\n"
        + f"- Overall Risk Score: **{risk_score}/100**\n"
        + f"- Release Readiness: **{readiness}**\n"
        + f"- Top 3 Priorities:\n{priorities}"
    )


@app.route("/mcp/regression/ai-analysis/bulk-issues", methods=["POST"])
@app.route("/api/mcp/regression/ai-analysis/bulk-issues", methods=["POST"])
@jwt_required
def ai_analyze_bulk_issues():
    """AI analysis for bulk issue JIRA tickets - analyzes patterns and provides risk assessment."""
    try:
        body = request.get_json(force=True) or {}
        bulk_issues = body.get("bulk_issues", {})
        bulk_issues_with_qi = body.get("bulk_issues_with_qi", {})
        tag = body.get("tag", "")
        total_tests = body.get("total_tests_processed", 0)

        if not bulk_issues:
            return jsonify({"error": "No bulk issues provided"}), 400

        issue_detail_blocks = []
        issue_rows = []
        for ticket, tests in bulk_issues.items():
            qi_data = bulk_issues_with_qi.get(ticket, {})
            qi_impact = qi_data.get("overall_qi_impact", "N/A")
            count = qi_data.get("testcase_count", len(tests)) if qi_data else len(tests)
            qi_numeric = None
            if qi_impact != "N/A":
                try:
                    qi_numeric = float(qi_impact)
                except Exception:
                    qi_numeric = None

            if qi_numeric is None:
                risk_level = "Low"
            elif qi_numeric <= -5:
                risk_level = "Critical"
            elif qi_numeric <= -2:
                risk_level = "High"
            elif qi_numeric <= -1:
                risk_level = "Medium"
            else:
                risk_level = "Low"

            tc_names = tests if isinstance(tests, list) else []
            # Extract affected feature from test name prefixes
            feature_prefixes = set()
            for name in tc_names[:20]:
                parts = name.split(".")
                if len(parts) >= 3:
                    feature_prefixes.add(".".join(parts[:3]))
                elif len(parts) >= 2:
                    feature_prefixes.add(".".join(parts[:2]))
            affected_features = ", ".join(sorted(feature_prefixes)[:3])
            tc_sample = tc_names[:10]
            tc_display = "\n".join(f"    - {name}" for name in tc_sample)
            if len(tc_names) > 10:
                tc_display += f"\n    ... and {len(tc_names) - 10} more"
            primary_feature = sorted(feature_prefixes)[0] if feature_prefixes else "Unknown"
            issue_rows.append(
                {
                    "ticket": ticket,
                    "feature": primary_feature,
                    "testcase_count": count,
                    "qi_impact": qi_numeric if qi_numeric is not None else 0.0,
                    "risk_level": risk_level,
                }
            )
            issue_detail_blocks.append(
                f"Ticket: {ticket}\n"
                f"  Testcases Impacted: {count}\n"
                f"  QI Impact: {qi_impact}{'%' if qi_impact != 'N/A' else ''}\n"
                f"  Affected Feature(s): {affected_features or 'Unknown'}\n"
                f"  Affected Testcases:\n{tc_display}"
            )

        user_content = (
            f"Regression Tag: {tag}\n"
            f"Total Tests in Run: {total_tests}\n"
            f"Number of Bulk Issues (tickets affecting >5 testcases): {len(bulk_issues)}\n\n"
            f"=== Bulk Issue Details ===\n\n" + "\n\n".join(issue_detail_blocks) + "\n\n"
            "IMPORTANT: Use EXACTLY the ticket IDs and testcase counts from the data above. "
            "Do NOT change or reorder the tickets. Analyse the actual testcase names to determine patterns.\n\n"
            "For EACH ticket listed above (in the same order), provide:\n"
            "1. Bug ID — the JIRA ticket ID exactly as given\n"
            "2. Affected Feature — derived from testcase name prefix (e.g., cdp.stargate.storage_policy)\n"
            "3. Risk Level (Critical/High/Medium/Low) — based on QI impact: <=-5% Critical, <=-2% High, <=-1% Medium, else Low\n"
            "4. Impact — one sentence describing what is broken\n"
            "5. Recommended Action — specific next step (if this looks like a test issue, note it can be fixed; "
            "if product issue, note the affected component)\n\n"
            "Then provide an overall summary:\n"
            "- Overall Risk Score (0-100, where 100 is highest risk)\n"
            "- Release Readiness assessment\n"
            "- Top 3 priorities to address\n\n"
            "Format using markdown. Use a table with columns: "
            "Bug ID | Affected Feature | Testcases Impacted | QI Impact | Risk Level | Impact | Recommended Action\n"
            "The Bug ID, Testcases Impacted, and QI Impact columns MUST match the input data exactly."
        )

        system_prompt = (
            "You are a regression testing expert analyzing bulk failure patterns in a CDP (Continuous Data Protection) "
            "software QA pipeline at Nutanix. "
            "Bulk issues are JIRA tickets that affect more than 5 testcases, indicating systemic problems. "
            "QI Impact is the Quality Index impact - negative values mean the bug is reducing overall quality. "
            "Risk Level thresholds: QI Impact <= -5% is Critical, <= -2% is High, <= -1% is Medium, > -1% is Low. "
            "You MUST use the exact ticket IDs and counts provided — never invent or reorder them. "
            "Infer the Affected Feature from testcase name prefixes (e.g., cdp.stargate.checksum_regions → CDP Stargate Checksum). "
            "For Recommended Action, distinguish between test issues (can be fixed in test code) and product issues "
            "(require product team attention). "
            "Provide actionable, concise analysis. Use markdown tables for structured data."
        )

        try:
            analysis = _call_ai_chat(system_prompt, user_content, max_tokens=3000)
        except urllib.error.URLError as err:
            logger.warning(
                f"AI bulk issues endpoint unreachable ({err.reason}); returning fallback analysis."
            )
            analysis = _build_bulk_issues_fallback_analysis(issue_rows, tag, total_tests)
        return jsonify({"success": True, "analysis": analysis})

    except Exception as e:
        logger.error(f"Error in AI bulk issues analysis: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/mcp/regression/ai-analysis/deep-triage", methods=["POST"])
@app.route("/api/mcp/regression/ai-analysis/deep-triage", methods=["POST"])
@jwt_required
def ai_deep_triage():
    """
    Prepare context for deep triage of a single bug using the triage-cdp-test-failure skill.
    Returns structured context (log URL, test name, ticket, feature area) that the frontend
    uses to invoke the Cursor SDK agent with the skill.
    """
    try:
        body = request.get_json(force=True) or {}
        ticket_id = body.get("ticket_id", "")
        test_name = body.get("test_name", "")
        log_url = body.get("log_url", "")
        task_id = body.get("task_id", "")

        if not ticket_id and not test_name:
            return jsonify({"error": "ticket_id or test_name is required"}), 400

        # Extract feature area from test name
        feature_area = ""
        if test_name:
            parts = test_name.split(".")
            if len(parts) >= 3:
                feature_area = ".".join(parts[:3])
            elif len(parts) >= 2:
                feature_area = ".".join(parts[:2])

        # Build Jita log directory URL if task_id and test_name are provided but log_url is not
        if not log_url and task_id and test_name:
            # Convert test name to path format for log URL construction
            test_path = "/".join(test_name.split("."))
            log_url = f"http://10.40.234.216/logs/{task_id}/{test_path}/"

        # Construct the skill invocation command
        skill_command = f"/triage-cdp-test-failure"
        if ticket_id:
            skill_command += f" {ticket_id}"
        if log_url:
            skill_command += f" {log_url}"

        # Build context for the Cursor agent
        context = {
            "ticket_id": ticket_id,
            "test_name": test_name,
            "feature_area": feature_area,
            "log_url": log_url,
            "task_id": task_id,
            "skill_command": skill_command,
            "skill_prompt": (
                f"Triage the following CDP test failure:\n"
                f"- JIRA Ticket: {ticket_id}\n"
                f"- Test Name: {test_name}\n"
                f"- Feature Area: {feature_area}\n"
                f"- Jita Log Directory: {log_url}\n\n"
                f"Use the triage-cdp-test-failure skill to:\n"
                f"1. Fetch and analyse the test logs\n"
                f"2. Search the test source code in Sourcegraph (nugerrit.ntnxdpro.com/nutest-py3-tests)\n"
                f"3. Determine if this is a test issue or product issue\n"
                f"4. If test issue, propose a fix and offer to create a CR\n"
                f"5. Provide structured triage result"
            ),
        }

        return jsonify({"success": True, "context": context})

    except Exception as e:
        logger.error(f"Error in deep triage: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/mcp/regression/user-keys", methods=["GET", "PUT"])
@app.route("/api/mcp/regression/user-keys", methods=["GET", "PUT"])
@jwt_required
def user_api_keys():
    """Load or save per-user API keys (User Settings → API Keys)."""
    username = _current_username()
    if not username:
        return jsonify({"error": "Unable to resolve current user"}), 401

    if request.method == "GET":
        return jsonify(get_user_keys_masked(username))

    body = request.get_json(force=True) or {}
    if not isinstance(body, dict):
        return jsonify({"error": "Expected a JSON object of keys"}), 400
    try:
        masked = upsert_user_keys(username, body)
        return jsonify(masked)
    except ValueError as exc:
        return jsonify({"error": str(exc)}), 400
    except Exception as exc:
        logger.error("Failed to save user keys for %s: %s", username, exc, exc_info=True)
        return jsonify({"error": "Failed to save keys"}), 500


@app.route("/mcp/regression/user-keys/validate", methods=["POST"])
@app.route("/api/mcp/regression/user-keys/validate", methods=["POST"])
@jwt_required
def validate_user_api_keys():
    """Best-effort key checks. Failures here do not block using a saved Jira token."""
    username = _current_username()
    body = request.get_json(force=True) or {}
    if not isinstance(body, dict):
        return jsonify({"error": "Expected a JSON object of keys"}), 400

    results = {}

    cursor_key = (body.get("cursor_api_key") or "").strip()
    if not cursor_key or "****" in cursor_key:
        cursor_key = get_user_key(username, "cursor_api_key") or ""
    if not cursor_key:
        results["cursor_api_key"] = {"valid": None, "message": "Not provided (optional for Jira lookups)"}
    elif cursor_key.startswith("crsr_") or cursor_key.startswith("key_"):
        results["cursor_api_key"] = {"valid": True, "message": "Format looks valid"}
    else:
        results["cursor_api_key"] = {
            "valid": None,
            "message": "Format unusual — still saved if you clicked Save",
        }

    # Prefer request body plaintext; otherwise use decrypted User Settings store.
    jira_tok = (body.get("atlassian_jira_token") or "").strip()
    if not jira_tok or "****" in jira_tok:
        jira_tok = get_user_key(username, "atlassian_jira_token") or ""
    if not jira_tok:
        results["atlassian_jira_token"] = {
            "valid": None,
            "message": "Not saved yet — paste token and click Save (Test Keys is optional)",
        }
    else:
        try:
            resp = session.get(
                f"{JIRA_BASE}/myself",
                headers=get_jira_headers(jira_tok),
                timeout=15,
                verify=False,
            )
            if resp.status_code == 200:
                display = (resp.json() or {}).get("displayName") or "OK"
                results["atlassian_jira_token"] = {
                    "valid": True,
                    "message": f"Authenticated as {display}",
                }
            elif resp.status_code in (401, 403):
                # Still keep the token for ticket fetches — auth style can differ.
                results["atlassian_jira_token"] = {
                    "valid": None,
                    "message": (
                        f"Live /myself check returned HTTP {resp.status_code}. "
                        "Token is still used for ticket lookups after Save."
                    ),
                }
            else:
                results["atlassian_jira_token"] = {
                    "valid": None,
                    "message": (
                        f"Live check HTTP {resp.status_code}. "
                        "Token is still used for ticket lookups after Save."
                    ),
                }
        except Exception as exc:
            results["atlassian_jira_token"] = {
                "valid": None,
                "message": (
                    f"Could not reach Jira for Test Keys ({exc}). "
                    "Save the token anyway — dashboard ticket fetches will use it."
                ),
            }

    conf_tok = (body.get("atlassian_confluence_token") or "").strip()
    if not conf_tok or "****" in conf_tok:
        conf_tok = get_user_key(username, "atlassian_confluence_token") or ""
    if not conf_tok:
        results["atlassian_confluence_token"] = {"valid": None, "message": "Not provided"}
    else:
        results["atlassian_confluence_token"] = {
            "valid": True,
            "message": "Saved (live Confluence probe skipped)",
        }

    sg_tok = (body.get("sourcegraph_token") or "").strip()
    if not sg_tok or "****" in sg_tok:
        sg_tok = get_user_key(username, "sourcegraph_token") or ""
    if not sg_tok:
        sg_tok = (os.getenv("SOURCEGRAPH_TOKEN") or "").strip()
    if not sg_tok:
        results["sourcegraph_token"] = {
            "valid": None,
            "message": "Not saved yet — paste token and click Save (required for Suggest/Validate LST).",
        }
    else:
        sg_url = (os.getenv("SOURCEGRAPH_URL") or "https://sourcegraph.ntnxdpro.com").strip().rstrip("/")
        api_urls = [sg_url + p for p in ["/.api/graphql", "/api/graphql", "/graphql"]]
        auth_headers = [
            {"Content-Type": "application/json", "Authorization": "token %s" % sg_tok},
            {"Content-Type": "application/json", "Authorization": "Bearer %s" % sg_tok},
        ]
        probe_ok = False
        probe_msg = "Could not reach Sourcegraph"
        for api_url in api_urls:
            for headers in auth_headers:
                try:
                    resp = requests.post(
                        api_url,
                        json={"query": "query { currentUser { username } }"},
                        headers=headers,
                        timeout=12,
                        verify=False,
                    )
                    if resp.status_code in (401, 403):
                        probe_msg = "Authentication failed (HTTP %s) — check the token" % resp.status_code
                        continue
                    if resp.status_code != 200:
                        probe_msg = "HTTP %s from Sourcegraph" % resp.status_code
                        continue
                    data = resp.json() if resp.text else {}
                    if data.get("errors"):
                        # Some instances disallow currentUser; treat GraphQL auth success as OK.
                        probe_ok = True
                        probe_msg = "Reachable (GraphQL responded)"
                        break
                    user = ((data.get("data") or {}).get("currentUser") or {})
                    uname = user.get("username") if isinstance(user, dict) else None
                    probe_ok = True
                    probe_msg = ("Authenticated as %s" % uname) if uname else "Authenticated"
                    break
                except Exception as exc:
                    probe_msg = "Could not reach Sourcegraph (%s)" % exc
                    continue
            if probe_ok:
                break
        results["sourcegraph_token"] = {
            "valid": True if probe_ok else False,
            "message": probe_msg,
        }

    gerrit_pwd = (body.get("gerrit_http_password") or "").strip()
    if not gerrit_pwd or "****" in gerrit_pwd:
        gerrit_pwd = get_user_key(username, "gerrit_http_password") or ""
    # Gerrit HTTP Credentials username is the LDAP id (e.g. swapnil.wankhede), not email.
    gerrit_user = (username or "").strip()
    if not gerrit_pwd:
        results["gerrit_http_password"] = {
            "valid": None,
            "message": "Not saved yet — paste Gerrit HTTP password and Save (required for Take handover CR).",
        }
    elif not gerrit_user:
        results["gerrit_http_password"] = {
            "valid": None,
            "message": "Could not resolve your Gerrit username (LDAP id). Log in again and retry Test Keys.",
        }
    else:
        gerrit_url = (os.getenv("GERRIT_URL") or "https://nugerrit.ntnxdpro.com").strip().rstrip("/")
        ok_auth, auth_msg = _validate_gerrit_credentials(gerrit_url, gerrit_user, gerrit_pwd)
        if ok_auth:
            results["gerrit_http_password"] = {
                "valid": True,
                "message": "Authenticated as %s" % gerrit_user,
            }
        else:
            results["gerrit_http_password"] = {
                "valid": False,
                "message": (
                    "%s. Re-generate the HTTP password in Gerrit → Settings → HTTP Credentials "
                    "and Save again (username is your Gerrit/LDAP id: %s)." % (auth_msg, gerrit_user)
                ),
            }

    return jsonify({"results": results})


@app.route("/mcp/regression/jira-ticket-details", methods=["POST"])
@app.route("/api/mcp/regression/jira-ticket-details", methods=["POST"])
@jwt_required
def get_jira_ticket_details():
    """Fetch JIRA status and issue type for a list of ticket IDs."""
    try:
        body = request.get_json(force=True) or {}
        ticket_ids = body.get("ticket_ids", [])
        if not ticket_ids:
            return jsonify({"error": "No ticket IDs provided"}), 400

        # Capture token on the request thread (Flask g is not safe across workers).
        jira_token = resolve_jira_token()
        if not jira_token:
            return jsonify({
                "success": False,
                "error": (
                    "Jira personal token not configured. "
                    "Open User Settings → API Keys and add your Atlassian Jira Personal Token."
                ),
                "details": {},
            }), 400

        # De-dupe and cap generously; fetch in parallel so large owner maps
        # (100+ unique tickets) return well within the client timeout.
        unique_ids = list(dict.fromkeys(ticket_ids))[:200]

        def _one(ticket_id):
            try:
                jira_data = fetch_jira_ticket(
                    ticket_id, token=jira_token, fields="status,issuetype,created"
                )
                return ticket_id, _extract_jira_ticket_detail(jira_data)
            except Exception as exc:
                logger.warning("Error fetching JIRA details for %s: %s", ticket_id, exc)
                return ticket_id, {"status": "N/A", "issue_type": "N/A", "bug_type": None, "created": None}

        results = {}
        max_workers = min(10, len(unique_ids)) or 1
        with ThreadPoolExecutor(max_workers=max_workers) as pool:
            for ticket_id, detail in pool.map(_one, unique_ids):
                results[ticket_id] = detail

        return jsonify({"success": True, "details": results})
    except Exception as e:
        logger.error(f"Error fetching JIRA ticket details: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/mcp/regression/ai-analysis/owner-tickets", methods=["POST"])
@app.route("/api/mcp/regression/ai-analysis/owner-tickets", methods=["POST"])
@jwt_required
def ai_analyze_owner_tickets():
    """AI analysis for owner-wise JIRA ticket breakdown with JIRA data fetch."""
    try:
        body = request.get_json(force=True) or {}
        owner_ticket_map = body.get("owner_ticket_map", {})
        triage_summary = body.get("triage_summary", {})
        tag = body.get("tag", "")
        total_tests = body.get("total_tests_processed", 0)

        if not owner_ticket_map:
            return jsonify({"error": "No owner ticket data provided"}), 400

        # Collect all unique tickets and fetch JIRA data
        all_tickets = set()
        owner_for_ticket = {}
        ticket_test_count = {}
        for owner, tickets in owner_ticket_map.items():
            for ticket, count in tickets.items():
                all_tickets.add(ticket)
                owner_for_ticket.setdefault(ticket, []).append(owner)
                ticket_test_count[ticket] = ticket_test_count.get(ticket, 0) + count

        # Fetch JIRA data for each ticket
        jira_details = {}
        for ticket_id in all_tickets:
            jira_data = fetch_jira_ticket(ticket_id)
            if jira_data:
                fields = jira_data.get("fields") or {}
                detail = _extract_jira_ticket_detail(jira_data)
                status = detail["status"]
                issue_type = detail["issue_type"]
                summary = fields.get("summary", "")
                description = (fields.get("description") or "")[:500]
                priority = fields.get("priority", {}).get("name", "Unknown") if fields.get("priority") else "Unknown"
                assignee = fields.get("assignee", {}).get("displayName", "Unassigned") if fields.get("assignee") else "Unassigned"
                # Get latest comments
                comments_data = fields.get("comment", {}).get("comments", [])
                latest_comments = ""
                for c in comments_data[-3:]:
                    comment_body = (c.get("body") or "")[:200]
                    latest_comments += f"  [{c.get('author', {}).get('displayName', 'Unknown')}]: {comment_body}\n"
                jira_details[ticket_id] = {
                    "status": status,
                    "issue_type": issue_type,
                    "summary": summary,
                    "description": description,
                    "priority": priority,
                    "assignee": assignee,
                    "comments": latest_comments.strip()
                }
            else:
                jira_details[ticket_id] = {
                    "status": "N/A",
                    "issue_type": "N/A",
                    "summary": "Unable to fetch",
                    "description": "",
                    "priority": "N/A",
                    "assignee": "N/A",
                    "comments": ""
                }

        # Build ticket detail lines for AI
        ticket_detail_lines = []
        for ticket_id in sorted(all_tickets):
            jd = jira_details[ticket_id]
            owners = ", ".join(owner_for_ticket.get(ticket_id, []))
            tc_count = ticket_test_count.get(ticket_id, 0)
            detail = (
                f"Ticket: {ticket_id}\n"
                f"  Owners: {owners}\n"
                f"  Testcases Impacted: {tc_count}\n"
                f"  JIRA Status: {jd['status']}\n"
                f"  JIRA Issue Type: {jd['issue_type']}\n"
                f"  Priority: {jd['priority']}\n"
                f"  Assignee: {jd['assignee']}\n"
                f"  Summary: {jd['summary']}\n"
            )
            if jd['description']:
                detail += f"  Description: {jd['description'][:300]}\n"
            if jd['comments']:
                detail += f"  Latest Comments:\n{jd['comments']}\n"
            ticket_detail_lines.append(detail)

        user_content = (
            f"Regression Tag: {tag}\n"
            f"Total Tests in Run: {total_tests}\n"
            f"Total Owners: {len(owner_ticket_map)}\n"
            f"Total Unique Tickets: {len(all_tickets)}\n\n"
            f"=== Ticket Details with JIRA Data ===\n\n"
            + "\n".join(ticket_detail_lines) + "\n\n"
            "Based on the JIRA data (status, description, comments), create a comprehensive analysis table:\n\n"
            "Create a markdown table with these columns:\n"
            "| Ticket ID | Owner | Status | Issue Type | Root Cause Category | Impact | AI Recommended Action |\n\n"
            "For Root Cause Category, classify as one of: Product | Test | Infra | Framework\n"
            "- Product: Bug in product code causing test failure\n"
            "- Test: Test code issue (flaky, outdated assertions, bad test data)\n"
            "- Infra: Infrastructure problem (environment, network, resources)\n"
            "- Framework: Test framework issue (automation framework, libraries)\n\n"
            "Base your classification on the JIRA description, comments, and issue type.\n"
            "For Impact, one sentence on what this ticket affects.\n"
            "For AI Recommended Action, provide a specific action based on the ticket status:\n"
            "- If Open/To Do: suggest priority and who should work on it\n"
            "- If In Progress: assess if it's on track\n"
            "- If Resolved/Closed: suggest verifying the fix and closing test gaps\n\n"
            "After the table, provide:\n"
            "1. **Summary** — Overall triage health assessment\n"
            "2. **Top 3 Priority Actions** — Most impactful actions to take now\n\n"
            "Use the EXACT ticket IDs, owner names, and status from the data."
        )

        system_prompt = (
            "You are a QA team lead analyzing JIRA tickets linked to regression test failures. "
            "You have access to real JIRA data including status, description, and comments. "
            "Classify each ticket's root cause category (Product/Test/Infra/Framework) based on the JIRA content. "
            "Provide specific, actionable recommendations based on ticket status and context. "
            "Use markdown tables. Use the exact ticket IDs and data provided — never invent data."
        )

        try:
            analysis = _call_ai_chat(system_prompt, user_content)
        except urllib.error.HTTPError as err:
            if err.code == 401:
                logger.warning(f"AI endpoint returned 401 Unauthorized; returning fallback analysis.")
                analysis = _build_owner_tickets_fallback_analysis(
                    all_tickets, jira_details, owner_for_ticket, ticket_test_count, tag
                )
            else:
                raise
        except urllib.error.URLError as err:
            logger.warning(f"AI owner tickets endpoint unreachable ({err.reason}); returning fallback analysis.")
            analysis = _build_owner_tickets_fallback_analysis(
                all_tickets, jira_details, owner_for_ticket, ticket_test_count, tag
            )

        # Return both analysis and jira_details for the frontend table
        return jsonify({
            "success": True,
            "analysis": analysis,
            "jira_details": jira_details
        })

    except Exception as e:
        logger.error(f"Error in AI owner tickets analysis: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/mcp/regression/ai-analysis/testcase-summary", methods=["POST"])
@app.route("/api/mcp/regression/ai-analysis/testcase-summary", methods=["POST"])
@jwt_required
def ai_analyze_testcases():
    """AI analysis for ALL filtered testcase data across all pages - overall health, patterns, and recommendations."""
    try:
        body = request.get_json(force=True) or {}
        stats = body.get("stats", {})
        failed_testcases = body.get("failed_testcases", [])
        branch = body.get("branch", "")
        team = body.get("team", "")

        total = stats.get("total", 0)
        succeeded = stats.get("succeeded", 0)
        failed = stats.get("failed", 0)
        avg_stability = stats.get("avg_stability", "N/A")
        avg_success = stats.get("avg_success", "N/A")
        avg_qi = stats.get("avg_qi", "N/A")

        issue_type_breakdown = stats.get("issue_type_breakdown", {})
        component_breakdown = stats.get("component_breakdown", {})
        unique_tickets = stats.get("unique_tickets", [])

        if not issue_type_breakdown:
            for tc in failed_testcases:
                it = tc.get("issue_type", "Unknown")
                issue_type_breakdown[it] = issue_type_breakdown.get(it, 0) + 1

        if not unique_tickets:
            ticket_set = set()
            for tc in failed_testcases:
                for t in tc.get("last_run_tickets", []):
                    ticket_set.add(t)
            unique_tickets = list(ticket_set)

        failed_details = []
        for tc in failed_testcases[:50]:
            failed_details.append(
                f"  - {tc.get('name', 'Unknown')}: issue_type={tc.get('issue_type', 'N/A')}, "
                f"stability={tc.get('stability', 'N/A')}%, component={tc.get('primary_component', 'N/A')}, "
                f"tickets={tc.get('last_run_tickets', [])}"
            )

        component_lines = "\n".join(
            f"  {k}: {v} failed testcases" for k, v in sorted(component_breakdown.items(), key=lambda x: -x[1])[:15]
        ) if component_breakdown else "  No component data available"

        user_content = (
            f"Branch: {branch}\nTeam: {team}\n\n"
            f"=== Complete Test Suite Statistics (ALL filtered pages) ===\n"
            f"Total Testcases (all pages): {total}\n"
            f"Succeeded: {succeeded}\n"
            f"Failed: {failed}\n"
            f"Pass Rate: {(succeeded/total*100) if total else 0:.1f}%\n"
            f"Avg Stability: {avg_stability}%\n"
            f"Avg Success Rate: {avg_success}%\n"
            f"Avg Quality Index: {avg_qi}%\n\n"
            f"=== Issue Type Breakdown (ALL {failed} failed testcases) ===\n"
            + "\n".join(f"  {k}: {v}" for k, v in issue_type_breakdown.items()) + "\n\n"
            f"=== Component Breakdown (failed testcases by component) ===\n"
            + component_lines + "\n\n"
            f"=== Unique JIRA Tickets ({len(unique_tickets)}) ===\n"
            + ", ".join(unique_tickets[:30]) + "\n\n"
            f"=== Failed Testcase Samples (top 50 of {failed} total) ===\n"
            + "\n".join(failed_details) + "\n\n"
            "Provide a comprehensive analysis of the ENTIRE filtered dataset using markdown formatting with tables:\n"
            "1. **Overall Health Assessment** - Use a table with Metric/Value/Interpretation columns\n"
            "2. **Failure Pattern Analysis** - Common patterns across ALL failed testcases, systemic issues\n"
            "3. **Issue Type Summary** - Use a table with Issue Type/Count/Percentage/Comment columns\n"
            "4. **Component Risk Areas** - Table of components with highest failure concentration\n"
            "5. **Ticket Analysis** - Assessment of JIRA tickets linked to failed tests in a table\n"
            "6. **Recommendations** - Top 5 actionable items to improve test health\n"
            "7. **Risk Score** - Overall risk score 0-100 (100=highest risk)\n"
        )

        system_prompt = (
            "You are a QA analytics expert analyzing testcase data for a regression test suite. "
            "The data represents ALL filtered testcases across all pages (not just the first page). "
            "Provide actionable insights with specific recommendations. "
            "Focus on identifying systemic issues, high-risk areas, and concrete steps to improve. "
            "Use markdown formatting with tables (using | syntax) for structured data. "
            "Be concise but thorough."
        )

        analysis = _call_ai_chat(system_prompt, user_content)
        return jsonify({"success": True, "analysis": analysis})

    except Exception as e:
        logger.error(f"Error in AI testcase analysis: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/mcp/regression/ai-analysis/run-plan-risk", methods=["POST"])
@app.route("/api/mcp/regression/ai-analysis/run-plan-risk", methods=["POST"])
@jwt_required
def ai_run_plan_risk():
    """AI risk analysis for a run plan based on its history and job profiles."""
    try:
        body = request.get_json(force=True) or {}
        run_plan_name = body.get("name", "")
        job_profile_count = body.get("job_profile_count", 0)
        history = body.get("history", [])
        tag_name = body.get("tag_name", "")

        history_summary = []
        success_count = 0
        fail_count = 0
        for entry in history[:10]:
            status = entry.get("status", "unknown")
            if status.lower() in ("success", "completed", "succeeded"):
                success_count += 1
            else:
                fail_count += 1
            history_summary.append(
                f"  - Date: {entry.get('triggered_at', 'N/A')}, Status: {status}, "
                f"Tasks: {len(entry.get('task_ids', []))}"
            )

        total_runs = success_count + fail_count
        success_rate = (success_count / total_runs * 100) if total_runs else 0

        user_content = (
            f"Run Plan: {run_plan_name}\n"
            f"Tag Name: {tag_name}\n"
            f"Job Profiles: {job_profile_count}\n\n"
            f"=== Run History (last {len(history[:10])} runs) ===\n"
            f"Success Rate: {success_rate:.0f}% ({success_count}/{total_runs})\n"
            + "\n".join(history_summary) + "\n\n"
            "Provide using markdown formatting:\n"
            "1. **Risk Score** (0-100, where 100 is highest risk)\n"
            "2. **Risk Level** (Low/Medium/High/Critical)\n"
            "3. **Confidence** (High/Medium/Low based on data available)\n"
            "4. **Key Factors** - What contributes to the risk\n"
            "5. **Recommendation** - One sentence actionable advice\n\n"
            "Keep the response concise (under 200 words). Use a summary table."
        )

        system_prompt = (
            "You are a regression testing risk analyst. Given run plan history, estimate "
            "the risk of the next scheduled run failing. Consider success rate trends, "
            "task counts, and patterns. Provide a numeric risk score and brief assessment. "
            "Use markdown formatting with tables. Be direct and actionable."
        )

        analysis = _call_ai_chat(system_prompt, user_content, max_tokens=512)

        risk_score_match = re.search(r"Risk Score[:\s]*(\d+)", analysis)
        risk_score = int(risk_score_match.group(1)) if risk_score_match else (
            90 if fail_count > success_count else
            60 if success_rate < 70 else
            30 if success_rate < 90 else 15
        )

        risk_level_match = re.search(r"Risk Level[:\s]*(Critical|High|Medium|Low)", analysis, re.IGNORECASE)
        risk_level = risk_level_match.group(1) if risk_level_match else (
            "Critical" if risk_score >= 80 else
            "High" if risk_score >= 60 else
            "Medium" if risk_score >= 40 else "Low"
        )

        return jsonify({
            "success": True,
            "risk_score": risk_score,
            "risk_level": risk_level,
            "analysis": analysis,
            "success_rate": round(success_rate, 1),
            "total_runs": total_runs
        })

    except Exception as e:
        logger.error(f"Error in AI run plan risk analysis: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


# ======================================================
# Cursor AI Bridge — Deep testcase analysis via Cursor SDK
# ======================================================
CURSOR_BRIDGE_URL = os.getenv("CURSOR_BRIDGE_URL", "http://localhost:5002")

# In-memory store for async Cursor AI analysis jobs
_cursor_ai_jobs = {}
_cursor_ai_jobs_lock = threading.Lock()


@app.route("/mcp/regression/cursor-ai/analyze-testcase", methods=["POST"])
@app.route("/api/mcp/regression/cursor-ai/analyze-testcase", methods=["POST"])
@jwt_required
def cursor_ai_analyze_testcase():
    """Trigger deep AI analysis for a single failed testcase via the Cursor bridge."""
    try:
        body = request.get_json(force=True) or {}
        testcase_name = body.get("testcase_name", "")
        if not testcase_name:
            return jsonify({"error": "testcase_name is required"}), 400

        # Get user API keys for Cursor SDK
        username = _current_username()
        user_toks = resolve_user_settings_tokens(username)
        cursor_api_key = user_toks.get("cursor_api_key")

        if not cursor_api_key:
            return jsonify({
                "error": format_mcp_token_connection_error("cursor", username),
                "require_key_setup": True,
                "mcp_token_status": mcp_token_status_for_user(username),
            }), 403

        atlassian_tokens = build_atlassian_tokens_for_bridge(username)

        exception_summary = body.get("exception_summary", "")
        exception = body.get("exception", "")
        test_log_url = body.get("test_log_url", "")
        jira_tickets = body.get("jira_tickets", [])
        failure_stage = body.get("failure_stage", "")
        testcase_id = body.get("testcase_id") or ""
        status = (body.get("status") or "").lower()
        analysis_type = body.get("analysis_type") or ("skipped" if status == "skipped" else "failed")
        triage_genie_ticket = body.get("triage_genie_ticket") or body.get("triage_genie_ticket_id") or ""
        glean_tickets = body.get("glean_tickets") or []
        glean_snippets = body.get("glean_snippets") or []

        if not triage_genie_ticket and testcase_id:
            try:
                triage_genie_ticket = fetch_triage_genie_ticket_id(testcase_id) or ""
            except Exception as tg_err:
                logger.warning("Could not fetch TG ticket for cursor-ai %s: %s", testcase_id, tg_err)

        if not glean_tickets:
            try:
                search = search_existing_tickets_for_failure(
                    exception_summary, exception, testcase_name
                )
                glean_tickets = _enrich_tickets_with_jira(search.get("tickets") or [])
                if not glean_snippets:
                    glean_snippets = search.get("snippets") or []
            except Exception as glean_err:
                logger.warning("Glean auto-search for cursor-ai failed: %s", glean_err)

        # Fetch logs if not provided in the request
        steps_log = body.get("steps_log", "")
        nutest_test_log = body.get("nutest_test_log", "")
        if not steps_log and not nutest_test_log and test_log_url:
            logs = fetch_testcase_logs(testcase_name, test_log_url)
            steps_log = logs.get("steps_log", "")
            nutest_test_log = logs.get("nutest_test_log", "")

        rdm_link = body.get("rdm_link") or body.get("rdm_url") or ""
        rdm_message = body.get("rdm_message") or exception_summary or ""
        skill_url = rdm_link if analysis_type == "skipped" else test_log_url

        payload = {
            "testcase_name": testcase_name,
            "exception_summary": exception_summary or rdm_message,
            "exception": exception or rdm_message,
            "steps_log": steps_log[:5000],
            "nutest_test_log": nutest_test_log[:5000],
            "test_log_url": skill_url or test_log_url,
            "rdm_url": rdm_link,
            "rdm_message": rdm_message,
            "jita_task_id": body.get("agave_task_id") or body.get("jita_task_id") or "",
            "jira_tickets": jira_tickets,
            "failure_stage": failure_stage,
            "triage_genie_ticket": triage_genie_ticket,
            "glean_tickets": glean_tickets,
            "glean_snippets": glean_snippets,
            "analysis_type": analysis_type,
            "cursor_api_key": cursor_api_key,
            "atlassian_tokens": atlassian_tokens,
        }

        resp = requests.post(
            f"{CURSOR_BRIDGE_URL}/analyze-testcase",
            json=payload,
            timeout=600,
        )
        if resp.status_code != 200:
            error_msg = resp.json().get("error", resp.text) if resp.headers.get("content-type", "").startswith("application/json") else resp.text
            return jsonify({"error": f"Bridge error: {error_msg}"}), 502

        data = resp.json()
        return jsonify({
            "success": True,
            "session_id": data.get("session_id", ""),
            "analysis": data.get("analysis", {}),
        })

    except requests.exceptions.ConnectionError:
        logger.error("Cursor bridge is not reachable at %s", CURSOR_BRIDGE_URL)
        return jsonify({"error": "Cursor AI bridge is not running. Start it with: cd cursor-bridge && npm start"}), 503
    except requests.exceptions.Timeout:
        return jsonify({"error": "Analysis timed out (>600s). Try batch mode for complex testcases."}), 504
    except Exception as e:
        logger.error(f"Error in cursor-ai analyze-testcase: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/mcp/regression/cursor-ai/analyze-batch", methods=["POST"])
@app.route("/api/mcp/regression/cursor-ai/analyze-batch", methods=["POST"])
@jwt_required
def cursor_ai_analyze_batch():
    """Start async batch analysis for multiple selected failed testcases."""
    try:
        body = request.get_json(force=True) or {}
        testcases = body.get("testcases", [])
        if not testcases:
            return jsonify({"error": "testcases array is required"}), 400

        # Get user API keys for Cursor SDK (login user's User Settings)
        username = _current_username()
        user_toks = resolve_user_settings_tokens(username)
        cursor_api_key = user_toks.get("cursor_api_key")

        if not cursor_api_key:
            return jsonify({
                "error": format_mcp_token_connection_error("cursor", username),
                "require_key_setup": True,
                "mcp_token_status": mcp_token_status_for_user(username),
            }), 403

        atlassian_tokens = build_atlassian_tokens_for_bridge(username)

        # Enrich each testcase with logs if missing
        enriched = []
        for tc in testcases:
            name = tc.get("testcase_name", "")
            log_url = tc.get("test_log_url", "")
            if name and log_url and not tc.get("steps_log") and not tc.get("nutest_test_log"):
                logs = fetch_testcase_logs(name, log_url)
                tc["steps_log"] = logs.get("steps_log", "")[:5000]
                tc["nutest_test_log"] = logs.get("nutest_test_log", "")[:5000]
            enriched.append(tc)

        resp = requests.post(
            f"{CURSOR_BRIDGE_URL}/analyze-batch",
            json={
                "testcases": enriched,
                "cursor_api_key": cursor_api_key,
                "atlassian_tokens": atlassian_tokens,
            },
            timeout=30,
        )
        if resp.status_code != 200:
            error_msg = resp.json().get("error", resp.text) if resp.headers.get("content-type", "").startswith("application/json") else resp.text
            return jsonify({"error": f"Bridge error: {error_msg}"}), 502

        data = resp.json()
        job_id = data.get("job_id", "")

        # Track the job locally
        with _cursor_ai_jobs_lock:
            _cursor_ai_jobs[job_id] = {
                "status": "running",
                "total": len(enriched),
                "completed": 0,
                "created_at": datetime.now().isoformat(),
            }

        return jsonify({"success": True, "job_id": job_id, "total": len(enriched)})

    except requests.exceptions.ConnectionError:
        return jsonify({"error": "Cursor AI bridge is not running. Start it with: cd cursor-bridge && npm start"}), 503
    except Exception as e:
        logger.error(f"Error in cursor-ai analyze-batch: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/mcp/regression/cursor-ai/status/<job_id>", methods=["GET"])
@app.route("/api/mcp/regression/cursor-ai/status/<job_id>", methods=["GET"])
@jwt_required
def cursor_ai_job_status(job_id):
    """Poll the status of an async batch analysis job from the Cursor bridge."""
    try:
        resp = requests.get(
            f"{CURSOR_BRIDGE_URL}/status/{job_id}",
            timeout=10,
        )
        if resp.status_code == 404:
            return jsonify({"error": "Job not found"}), 404
        if resp.status_code != 200:
            return jsonify({"error": "Bridge error"}), 502

        data = resp.json()

        # Update local tracker
        with _cursor_ai_jobs_lock:
            if job_id in _cursor_ai_jobs:
                _cursor_ai_jobs[job_id]["status"] = data.get("status", "unknown")
                _cursor_ai_jobs[job_id]["completed"] = data.get("completed", 0)

        return jsonify(data)

    except requests.exceptions.ConnectionError:
        return jsonify({"error": "Cursor AI bridge is not reachable"}), 503
    except Exception as e:
        logger.error(f"Error polling cursor-ai status: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/mcp/regression/cursor-ai/result", methods=["POST"])
@app.route("/api/mcp/regression/cursor-ai/result", methods=["POST"])
def cursor_ai_result_callback():
    """Callback endpoint for the bridge to push results (async mode).
    No JWT required since this is a server-to-server call from the bridge."""
    try:
        body = request.get_json(force=True) or {}
        job_id = body.get("job_id", "")
        testcase_id = body.get("testcase_id", "")
        analysis = body.get("analysis", {})

        if not job_id or not testcase_id:
            return jsonify({"error": "job_id and testcase_id are required"}), 400

        with _cursor_ai_jobs_lock:
            job = _cursor_ai_jobs.get(job_id)
            if job:
                if "results" not in job:
                    job["results"] = {}
                job["results"][testcase_id] = analysis
                job["completed"] = len(job["results"])
                if job["completed"] >= job.get("total", 0):
                    job["status"] = "done"

        logger.info(f"[cursor-ai] Received result for job={job_id}, testcase={testcase_id}")
        return jsonify({"success": True})

    except Exception as e:
        logger.error(f"Error in cursor-ai result callback: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/mcp/regression/cursor-ai/create-eng-ticket", methods=["POST"])
@app.route("/api/mcp/regression/cursor-ai/create-eng-ticket", methods=["POST"])
@jwt_required
def cursor_ai_create_eng_ticket():
    """Create an ENG Jira ticket via Jira REST using the login user's User Settings token."""
    try:
        body = request.get_json(force=True) or {}
        ticket_ctx = body.get("ticket_context") or body
        require_confirm = bool(body.get("require_confirm"))
        if body.get("confirm") is True or ticket_ctx.get("confirm"):
            ticket_ctx = dict(ticket_ctx)
            ticket_ctx["confirm"] = True
        # Always use the logged-in user's Atlassian Jira Personal Token from User Settings.
        user_toks = resolve_user_settings_tokens()
        jira_token = user_toks.get("atlassian_jira_token") or ""
        if not jira_token:
            return jsonify({
                "success": False,
                "error": format_mcp_token_connection_error("jira"),
                "mcp_token_status": mcp_token_status_for_user(),
            }), 400
        result = create_eng_jira_ticket(
            ticket_ctx,
            token=jira_token,
            require_confirm=require_confirm,
        )
        if result.get("needs_user_input"):
            return jsonify({
                "success": True,
                "needs_user_input": True,
                "draft": result.get("draft"),
                "analysis": {
                    "follow_up_answer": result.get("follow_up_answer"),
                    "pending_ticket_draft": result.get("draft"),
                },
            })
        if not result.get("ok"):
            err = result.get("error") or "Failed to create ENG ticket"
            if "token" in err.lower() or "credential" in err.lower():
                err = format_mcp_token_connection_error("jira")
            return jsonify({
                "success": False,
                "error": err,
                "mcp_token_status": mcp_token_status_for_user(),
            }), 400
        return jsonify({
            "success": True,
            "key": result.get("key"),
            "url": result.get("url"),
            "summary": result.get("summary"),
            "issue_type": result.get("issue_type"),
            "duplicates_linked": result.get("duplicates_linked") or [],
            "analysis": {
                "follow_up_answer": (
                    f"Created ENG ticket [{result.get('key')}]({result.get('url')})\n\n"
                    f"**Summary:** {result.get('summary')}\n"
                    f"**Type:** {result.get('issue_type')}"
                    + (
                        f"\n**Linked duplicates:** {', '.join(result.get('duplicates_linked') or [])}"
                        if result.get("duplicates_linked")
                        else ""
                    )
                ),
                "created_ticket": result.get("key"),
                "created_ticket_url": result.get("url"),
                "pending_ticket_draft": None,
            },
        })
    except Exception as e:
        logger.error("Error in cursor-ai create-eng-ticket: %s", e, exc_info=True)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/mcp/regression/cursor-ai/follow-up", methods=["POST"])
@app.route("/api/mcp/regression/cursor-ai/follow-up", methods=["POST"])
@jwt_required
def cursor_ai_follow_up():
    """Send a follow-up question to an existing Cursor AI analysis session.
    The agent retains full conversation context from the initial triage.

    Phase 3: intercept create-ENG and Flux Quick Fix intents before bridge call.
    """
    try:
        body = request.get_json(force=True) or {}
        session_id = body.get("session_id", "")
        question = body.get("question", "")
        recovery_context = body.get("recovery_context", {}) or {}
        ticket_context = body.get("ticket_context") or {}
        mode = (body.get("mode", "agent") or "agent").strip().lower()
        if mode not in {"ask", "agent", "plan"}:
            mode = "agent"

        if not question:
            return jsonify({"error": "question is required"}), 400

        latest = recovery_context.get("latest_analysis") or {}
        ticket_ctx = dict(ticket_context or {})
        for key in (
            "testcase_name", "testcase_id", "agave_task_id", "root_cause",
            "classification", "suggested_fix", "triage_report", "jira_duplicates",
            "related_components", "failing_code", "exception_summary", "test_log_url",
            "nutest_branch", "current_branch", "pending_ticket_draft", "created_ticket",
        ):
            if not ticket_ctx.get(key) and (latest.get(key) or recovery_context.get(key)):
                ticket_ctx[key] = latest.get(key) or recovery_context.get(key)

        pending_draft = latest.get("pending_ticket_draft") or ticket_ctx.get("pending_ticket_draft")
        confirm_ticket = bool(pending_draft) and is_confirm_eng_ticket_intent(question)
        create_ticket = is_create_eng_ticket_intent(question) or confirm_ticket

        if create_ticket:
            user_toks = resolve_user_settings_tokens()
            jira_token = user_toks.get("atlassian_jira_token") or ""
            if not jira_token:
                return jsonify({
                    "success": False,
                    "error": format_mcp_token_connection_error("jira"),
                    "mcp_token_status": mcp_token_status_for_user(),
                }), 400
            if confirm_ticket and pending_draft:
                ticket_ctx = {**pending_draft, **ticket_ctx, "confirm": True}
                overrides = parse_eng_ticket_field_overrides(question)
                ticket_ctx.update({k: v for k, v in overrides.items() if v})
            try:
                ticket_ctx = _enrich_eng_ticket_context(ticket_ctx)
            except Exception as enrich_err:
                logger.debug("follow-up eng enrich skipped: %s", enrich_err)
            created = create_eng_jira_ticket(
                ticket_ctx,
                token=jira_token,
                require_confirm=bool(body.get("require_confirm")),
            )
            if created.get("needs_user_input"):
                analysis = {
                    "follow_up_answer": created.get("follow_up_answer")
                    or format_eng_ticket_draft_prompt(created.get("draft") or {}),
                    "pending_ticket_draft": created.get("draft") or {},
                }
                return jsonify({
                    "success": True,
                    "session_id": session_id,
                    "needs_user_input": True,
                    "draft": created.get("draft"),
                    "analysis": analysis,
                })
            if not created.get("ok"):
                err = created.get("error") or "Failed to create ENG ticket"
                if "token" in err.lower() or "credential" in err.lower():
                    err = format_mcp_token_connection_error("jira")
                return jsonify({
                    "success": False,
                    "error": err,
                    "mcp_token_status": mcp_token_status_for_user(),
                }), 400
            return jsonify({
                "success": True,
                "session_id": session_id,
                "analysis": {
                    "follow_up_answer": (
                        f"Created ENG ticket [{created.get('key')}]({created.get('url')})\n\n"
                        f"**Summary:** {created.get('summary')}\n"
                        f"**Type:** {created.get('issue_type')}"
                    ),
                    "created_ticket": created.get("key"),
                    "created_ticket_url": created.get("url"),
                    "jira_duplicates": [created.get("key")],
                    "pending_ticket_draft": None,
                    "suggested_action": "approve_tag_jita",
                },
            })

        if is_flux_quick_fix_intent(question):
            classification = str(
                ticket_ctx.get("classification")
                or latest.get("classification")
                or ""
            )
            is_test_issue = "test" in classification.lower()
            if not is_test_issue:
                return jsonify({
                    "success": True,
                    "session_id": session_id,
                    "analysis": {
                        "follow_up_answer": (
                            "Flux Quick Fix is only offered for **Test Issue** classifications. "
                            f"Current classification is `{classification or 'Unknown'}`. "
                            "Create/link an ENG ticket for product/infra issues instead."
                        ),
                        "suggested_action": None,
                    },
                })
            return jsonify({
                "success": True,
                "session_id": session_id,
                "analysis": {
                    "follow_up_answer": (
                        "Ready to run **Flux Quick Fix** for this test issue. "
                        "Confirm in the UI to start Flux (never auto-started)."
                    ),
                    "suggested_action": "flux_quick_fix",
                    "requires_confirmation": True,
                },
            })

        if not session_id:
            return jsonify({"error": "session_id is required"}), 400

        # Get user API keys for Cursor SDK (login user's User Settings)
        username = _current_username()
        user_toks = resolve_user_settings_tokens(username)
        cursor_api_key = user_toks.get("cursor_api_key")

        if not cursor_api_key:
            return jsonify({
                "error": format_mcp_token_connection_error("cursor", username),
                "require_key_setup": True,
                "mcp_token_status": mcp_token_status_for_user(username),
            }), 403

        atlassian_tokens = build_atlassian_tokens_for_bridge(username)

        resp = requests.post(
            f"{CURSOR_BRIDGE_URL}/follow-up",
            json={
                "session_id": session_id,
                "question": question,
                "mode": mode,
                "recovery_context": recovery_context,
                "cursor_api_key": cursor_api_key,
                "atlassian_tokens": atlassian_tokens,
            },
            timeout=600,
        )
        if resp.status_code == 404:
            return jsonify({"error": "Session expired or not found. Run a new analysis first."}), 404
        if resp.status_code != 200:
            error_msg = resp.json().get("error", resp.text) if resp.headers.get("content-type", "").startswith("application/json") else resp.text
            rewritten = rewrite_agent_jira_credential_errors(str(error_msg), username)
            # Map MCP auth failures to User Settings token guidance
            low = str(error_msg).lower()
            if "atlassian" in low or "jira" in low or "401" in low or "403" in low:
                if not atlassian_tokens.get("jira"):
                    rewritten = format_mcp_token_connection_error("jira", username)
            return jsonify({
                "error": f"Bridge error: {rewritten}",
                "mcp_token_status": mcp_token_status_for_user(username),
            }), 502

        data = resp.json()
        analysis = data.get("analysis", {}) or {}
        if isinstance(analysis, dict):
            for field in ("follow_up_answer", "root_cause", "triage_report", "suggested_fix"):
                if analysis.get(field):
                    analysis[field] = rewrite_agent_jira_credential_errors(
                        analysis.get(field), username
                    )
        return jsonify({
            "success": True,
            "session_id": session_id,
            "analysis": analysis,
            "mcp_token_status": mcp_token_status_for_user(username),
        })

    except requests.exceptions.ConnectionError:
        return jsonify({"error": "Cursor AI bridge is not reachable"}), 503
    except requests.exceptions.Timeout:
        return jsonify({"error": "Follow-up timed out (>600s)."}), 504
    except Exception as e:
        logger.error(f"Error in cursor-ai follow-up: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


