@app.route("/mcp/regression/validate-jira-ticket", methods=["GET", "POST"])
@jwt_required
def validate_jira_ticket():
    """Validate if a Jira ticket exists and return its issuetype."""
    if request.method == "OPTIONS":
        return jsonify({}), 200

    ticket = ""
    if request.method == "POST" and request.is_json:
        ticket = (request.get_json() or {}).get("ticket", "").strip().upper()
    else:
        ticket = (request.args.get("ticket") or "").strip().upper()

    if not ticket:
        return jsonify({"valid": False, "ticket": "", "issuetype": None, "error": "ticket is required"}), 400

    if "-" in ticket and ticket.split("-")[0].isalpha():
        ticket = ticket.split("-")[0].upper() + "-" + (ticket.split("-", 1)[1] or "")

    if not resolve_jira_token():
        return jsonify({
            "valid": None, "ticket": ticket, "issuetype": None, "skipped": True,
            "message": (
                "Jira validation is not configured. "
                "Open User Settings → API Keys and add your Atlassian Jira Personal Token."
            )
        }), 200

    url = "%s/issue/%s" % (JIRA_BASE, ticket)

    try:
        resp = session.get(url, headers=get_jira_headers(), timeout=10)
        if resp.status_code == 401:
            return jsonify({
                "valid": False, "ticket": ticket, "issuetype": None,
                "error": (
                    "Authentication required. Check your Atlassian Jira Personal Token "
                    "in User Settings → API Keys."
                )
            }), 200
        if resp.status_code == 404:
            return jsonify({"valid": False, "ticket": ticket, "issuetype": None, "error": "Ticket not found"}), 200
        if resp.status_code == 403:
            return jsonify({"valid": False, "ticket": ticket, "issuetype": None, "error": "Forbidden"}), 200
        resp.raise_for_status()
        data = resp.json()
        name = _named_jira_field((data.get("fields") or {}).get("issuetype"), default="")
        bug_type = _categorize_bug_type_from_issuetype(name)
        is_valid = bug_type == "Product Bug"
        return jsonify({
            "valid": is_valid, "ticket": ticket, "issuetype": name, "bug_type": bug_type,
            "generated_at": datetime.utcnow().isoformat()
        })
    except requests.RequestException as e:
        err_msg = str(e)
        if "resolve" in err_msg.lower() or "nodename" in err_msg.lower():
            return jsonify({
                "valid": False, "ticket": ticket, "issuetype": None,
                "error": "Cannot reach Jira server. Check network or VPN."
            }), 200
        return jsonify({"valid": False, "ticket": ticket, "issuetype": None, "error": err_msg}), 200
    except Exception as e:
        return jsonify({"valid": False, "ticket": ticket, "issuetype": None, "error": str(e)}), 200


# ======================================================
# Handover - validate-lst, create-lst-cr, check-lst-testcases, search-lst-file, deprecate-lst-cr, deprecation-search
# ======================================================
def validate_with_sourcegraph(repo_name, branch, file_path, explicit_token=None):
    """Validate branch and file exist in repo via Sourcegraph.

    Uses the logged-in user's Sourcegraph token (Settings) with env fallback.
    Tries branch aliases (e.g. 7.5.2 → ganges-7.5-stable) before failing.
    """
    results = {
        "branch_valid": None,
        "file_valid": None,
        "branch_error": None,
        "file_error": None,
        "file_suggestions": [],
        "branch_suggestions": [],
        "resolved_branch": (branch or "master").strip() or "master",
        "auth_required": False,
        "message": "",
    }
    sg_token = resolve_sourcegraph_token(explicit_token)
    sg_url = (os.getenv("SOURCEGRAPH_URL") or "https://sourcegraph.ntnxdpro.com").strip().rstrip("/")
    sg_graphql_path = (os.getenv("SOURCEGRAPH_GRAPHQL_PATH") or "/api/graphql").strip() or "/api/graphql"
    auth_msg = (
        "Sourcegraph token missing. Add Sourcegraph Token in Settings → API Key Configuration "
        "(or set SOURCEGRAPH_TOKEN on the backend)."
    )
    if not sg_token:
        results["auth_required"] = True
        results["branch_error"] = auth_msg
        results["file_error"] = auth_msg
        results["message"] = auth_msg
        return results
    base_url = sg_url
    if not base_url:
        results["branch_error"] = "SOURCEGRAPH_URL not set"
        results["file_error"] = "SOURCEGRAPH_URL not set"
        return results
    api_urls_to_try = []
    sg_graphql_url = (os.getenv("SOURCEGRAPH_GRAPHQL_URL") or "").strip().rstrip("/")
    if sg_graphql_url:
        api_urls_to_try.append(sg_graphql_url)
    base = (base_url or "").strip().rstrip("/")
    graphql_path = sg_graphql_path
    if not graphql_path.startswith("/"):
        graphql_path = "/" + graphql_path
    if base:
        api_url = base + graphql_path
        if api_url not in api_urls_to_try:
            api_urls_to_try.append(api_url)
    if base:
        for p in ["/api/graphql", "/.api/graphql", "/graphql"]:
            full = base + p
            if full not in api_urls_to_try:
                api_urls_to_try.append(full)
    auth_headers = [
        {"Content-Type": "application/json", "Authorization": "token %s" % sg_token},
        {"Content-Type": "application/json", "Authorization": "Bearer %s" % sg_token},
    ]

    def run_search(search_query, url=None):
        urls = [url] if url else api_urls_to_try
        for u in urls:
            if not u:
                continue
            for headers in auth_headers:
                try:
                    resp = requests.post(
                        u,
                        json={
                            "query": (
                                "query Search($q: String!) { search(query: $q) { results "
                                "{ matchCount resultCount results { ... on FileMatch { file { path } } } } } }"
                            ),
                            "variables": {"q": search_query},
                        },
                        headers=headers,
                        timeout=20,
                        verify=False,
                    )
                    if resp.status_code in (401, 403):
                        return None, "Sourcegraph authentication failed. Check your Sourcegraph Token in Settings."
                    if resp.status_code == 200:
                        data = resp.json()
                        if data.get("errors"):
                            continue
                        sr = data.get("data", {}).get("search", {}).get("results")
                        if sr is not None:
                            match_count = (sr or {}).get("matchCount") or (sr or {}).get("resultCount") or len((sr or {}).get("results", []))
                            return (match_count or 0), None
                except Exception:
                    continue
        return None, "Sourcegraph not configured or unreachable"

    try:
        branch_candidates = _branch_alias_candidates(branch)
        resolved_branch = None
        last_err = None
        for b in branch_candidates:
            branch_query = "repo:%s rev:%s count:1" % (repo_name, b)
            match_count, err = run_search(branch_query)
            if err:
                last_err = err
                if "authentication failed" in err.lower():
                    results["auth_required"] = True
                    results["branch_valid"] = None
                    results["file_valid"] = None
                    results["branch_error"] = err
                    results["file_error"] = err
                    results["message"] = err
                    return results
                continue
            if match_count > 0:
                resolved_branch = b
                break
        results["branch_suggestions"] = branch_candidates[:6]
        if resolved_branch:
            results["branch_valid"] = True
            results["resolved_branch"] = resolved_branch
        elif last_err:
            results["branch_valid"] = None
            results["branch_error"] = last_err
        else:
            results["branch_valid"] = False
            results["branch_error"] = "Branch '%s' not found (tried: %s)" % (
                branch, ", ".join(branch_candidates[:6])
            )
    except Exception as e:
        results["branch_valid"] = None
        results["branch_error"] = str(e)

    try:
        branch_for_file = results.get("resolved_branch") or branch
        file_query = "repo:%s rev:%s file:%s type:path count:10" % (repo_name, branch_for_file, file_path)
        match_count, err = run_search(file_query)
        if err:
            results["file_valid"] = None
            results["file_error"] = err
            if "authentication failed" in err.lower():
                results["auth_required"] = True
                results["message"] = err
        else:
            results["file_valid"] = match_count > 0
            if not results["file_valid"]:
                results["file_error"] = "File '%s' not found on branch '%s'" % (file_path, branch_for_file)
    except Exception as e:
        results["file_valid"] = None
        results["file_error"] = str(e)
    return results


def fetch_file_content_via_sourcegraph(repo_name, rev, file_path, explicit_token=None):
    """Fetch file content from Sourcegraph. Returns (content, None) or (None, error_message)."""
    sg_token = resolve_sourcegraph_token(explicit_token)
    if not sg_token:
        return None, (
            "Sourcegraph token missing. Add Sourcegraph Token in Settings → API Key Configuration "
            "or paste LST file content below."
        )
    base_url = (os.getenv("SOURCEGRAPH_URL") or "https://sourcegraph.ntnxdpro.com").strip().rstrip("/")
    if not base_url:
        return None, "SOURCEGRAPH_URL not set"
    api_urls = [base_url + p for p in ["/api/graphql", "/.api/graphql", "/graphql"]]
    auth_headers = [
        {"Content-Type": "application/json", "Authorization": "token %s" % sg_token},
        {"Content-Type": "application/json", "Authorization": "Bearer %s" % sg_token},
    ]
    for query_name, query in [
        ("blob", "query RepoFile($repo: String!, $rev: String!, $path: String!) { repository(name: $repo) { commit(rev: $rev) { blob(path: $path) { content } } } }"),
        ("file", "query RepoFile($repo: String!, $rev: String!, $path: String!) { repository(name: $repo) { commit(rev: $rev) { file(path: $path) { content } } } }"),
    ]:
        payload = {"query": query, "variables": {"repo": repo_name, "rev": rev, "path": file_path}}
        for api_url in api_urls:
            for headers in auth_headers:
                try:
                    resp = requests.post(api_url, json=payload, headers=headers, timeout=20, verify=False)
                    if resp.status_code == 200:
                        data = resp.json()
                        if data.get("errors"):
                            continue
                        repo_data = (data.get("data") or {}).get("repository") or {}
                        commit_data = repo_data.get("commit") or {}
                        blob_or_file = commit_data.get("blob") or commit_data.get("file")
                        if blob_or_file is not None and "content" in blob_or_file:
                            return (blob_or_file.get("content") or ""), None
                except Exception:
                    continue
    return None, "Could not fetch file from Sourcegraph. Check your Sourcegraph Token or paste LST content below."


def _check_testnames_in_lst_content(lst_content, test_names):
    """Check which test names are present in LST file content.

    Exact match first; unique prefix/substring resolves (Sourcegraph-style) so a
    partial query still counts as present when it maps to one LST line.
    A trailing comma on the LST line is ignored (``foo`` matches ``foo,``).
    Returns (present_resolved, not_present, extra) where extra may include
    resolved_from / ambiguous maps.
    """
    if not lst_content or not isinstance(lst_content, str):
        return [], list(test_names or []), {}
    from gerrit_lst_cr import match_tests_in_lst

    present, not_present, resolved_from, ambiguous = match_tests_in_lst(lst_content, test_names)
    extra = {}
    if resolved_from:
        extra["resolved_from"] = resolved_from
    if ambiguous:
        extra["ambiguous"] = ambiguous
    return present, not_present, extra


def _fetch_lst_content_for_check(repo_name, branch, lst_file, explicit_token=None):
    """Fetch LST content, trying branch aliases and basename→full-path resolution."""
    lst_file = (lst_file or "").strip()
    branch = _handover_nutest_branch(branch)
    last_err = None
    resolved_path = lst_file

    # Basename-only path: find full path via Sourcegraph file search
    if lst_file and "/" not in lst_file and lst_file.lower().endswith(".lst"):
        token = resolve_sourcegraph_token(explicit_token)
        for rev in _branch_alias_candidates(branch):
            hits = search_sourcegraph_for_test(
                repo_name, lst_file, rev=rev, lst_files_only=True, sg_token=token, max_count=30
            )
            basename_hits = [
                h for h in (hits or [])
                if (h.get("path") or "").endswith("/" + lst_file) or (h.get("path") or "") == lst_file
            ]
            if not basename_hits and hits:
                # Fallback: any .lst hit whose basename matches
                basename_hits = [
                    h for h in hits
                    if (h.get("path") or "").replace("\\", "/").rsplit("/", 1)[-1] == lst_file
                ]
            if basename_hits:
                resolved_path = basename_hits[0]["path"]
                break

    for rev in _branch_alias_candidates(branch):
        content, err = fetch_file_content_via_sourcegraph(
            repo_name, rev, resolved_path, explicit_token=explicit_token
        )
        if err:
            last_err = err
            continue
        if content is not None:
            return content, rev, resolved_path, None
    return None, branch, resolved_path, last_err or "Could not fetch LST file from Sourcegraph."



def resolve_sourcegraph_token(explicit_token=None):
    """Resolve Sourcegraph token from request/user settings/env."""
    tok = (explicit_token or "").strip()
    if tok and "****" not in tok:
        return tok
    username = _current_username()
    if username:
        saved = (get_user_key(username, "sourcegraph_token") or "").strip()
        if saved:
            return saved
    return (os.getenv("SOURCEGRAPH_TOKEN") or "").strip()


def _handover_nutest_branch(branch):
    """Map product/search branch to nutest-py3-tests mainline (same as JP clone-to).

    7.5.2 / ganges-7.5.2-stable / ganges-7.5.1-stable → ganges-7.5-stable.
    master stays master. Used for LST validate/suggest/CR, not JITA last-5 lookup.
    """
    b = (branch or "").strip() or "master"
    mapped = nutest_mainline_branch(b)
    return (mapped or b).strip() or "master"


def _branch_alias_candidates(branch):
    b = (branch or "").strip()
    if not b:
        return ["master"]
    mainline = _handover_nutest_branch(b)
    out = [mainline]
    if b != mainline:
        out.append(b)
    low = b.lower()
    m = re.search(r"(\d+\.\d+)", low)
    if m:
        v = m.group(1)
        out.extend([
            "ganges-%s-stable" % v,
            "%s-stable" % v,
            v,
        ])
    if low != "master" and mainline.lower() != "master":
        out.append("master")
    seen = set()
    uniq = []
    for x in out:
        if x and x not in seen:
            seen.add(x)
            uniq.append(x)
    return uniq


@app.route("/mcp/regression/validate-lst", methods=["POST"])
@jwt_required
def validate_lst():
    """Validate LST file path and branch via Sourcegraph."""
    if request.method == "OPTIONS":
        return jsonify({}), 200
    data = request.get_json() or {}
    branch = _handover_nutest_branch(data.get("branch") or "master")
    lst_file = (data.get("lst_file") or "").strip()
    repo_name = (data.get("repo_name") or os.getenv("SOURCEGRAPH_FIRST_REPO", "nugerrit.ntnxdpro.com/nutest-py3-tests")).strip()
    if not lst_file:
        return jsonify({"error": "lst_file is required", "branch_valid": None, "file_valid": None}), 400
    validation_results = validate_with_sourcegraph(
        repo_name, branch, lst_file, explicit_token=data.get("sourcegraph_token")
    )
    resolved_branch = validation_results.get("resolved_branch") or branch
    sg_url = (os.getenv("SOURCEGRAPH_URL") or "https://sourcegraph.ntnxdpro.com").strip().rstrip("/")
    sourcegraph_url = (
        f"{sg_url}/{repo_name}@{resolved_branch}/-/blob/{lst_file.replace(' ', '+')}" if sg_url else None
    )
    return jsonify({
        "branch": resolved_branch,
        "input_branch": branch,
        "resolved_branch": resolved_branch,
        "lst_file": lst_file,
        "repo_name": repo_name,
        "branch_valid": validation_results.get("branch_valid"),
        "file_valid": validation_results.get("file_valid"),
        "branch_error": validation_results.get("branch_error"),
        "file_error": validation_results.get("file_error"),
        "file_suggestions": validation_results.get("file_suggestions", []),
        "branch_suggestions": validation_results.get("branch_suggestions", []),
        "auth_required": bool(validation_results.get("auth_required")),
        "sourcegraph_url": sourcegraph_url,
        "message": validation_results.get("message", ""),
        "generated_at": datetime.utcnow().isoformat()
    })


@app.route("/mcp/regression/search-reviewers", methods=["GET"])
@jwt_required
def search_reviewers():
    """Search for reviewers by name (uses Gerrit accounts suggest API). Returns name, email, username."""
    q = (request.args.get("q") or "").strip()
    if not q or len(q) < 2:
        return jsonify({"results": [], "message": "Type at least 2 characters to search"})
    gerrit_url = (os.getenv("GERRIT_URL") or "https://nugerrit.ntnxdpro.com").strip().rstrip("/")
    gerrit_auth = (os.getenv("GERRIT_TOKEN") or "").strip()
    if not gerrit_auth:
        username = (os.getenv("GERRIT_USERNAME") or "").strip()
        password = (os.getenv("GERRIT_HTTP_PASSWORD") or "").strip()
        if username and password:
            gerrit_auth = "%s:%s" % (username, password)
    if not gerrit_auth:
        gerrit_auth = (os.getenv("GERRIT_HTTP_PASSWORD") or "").strip()
    prefix = "/a" if gerrit_auth else ""
    url = "%s%s/accounts/?suggest&q=%s&n=15" % (gerrit_url, prefix, requests.utils.quote(q))
    headers = {"Accept": "application/json"}
    if gerrit_auth:
        import base64
        if ":" in gerrit_auth:
            user, pw = gerrit_auth.split(":", 1)
        else:
            user, pw = "anonymous", gerrit_auth
        headers["Authorization"] = "Basic " + base64.b64encode(("%s:%s" % (user, pw)).encode()).decode()
    try:
        resp = requests.get(url, headers=headers, timeout=10, verify=False)
        if resp.status_code == 401:
            return jsonify({"results": [], "error": "Gerrit reviewer search requires authentication. Set GERRIT_TOKEN (username:http_password) or GERRIT_USERNAME + GERRIT_HTTP_PASSWORD environment variables. You can still add reviewers by typing an email and pressing Enter."})
        if resp.status_code != 200:
            return jsonify({"results": [], "error": "Could not fetch reviewers from Gerrit (status %s). Add reviewers manually by typing email and pressing Enter." % resp.status_code})
        text = resp.text
        if text.startswith(")]}'"):
            text = text[5:]
        data = json.loads(text)
        accounts = data if isinstance(data, list) else (data.get("accounts") if isinstance(data, dict) else [])
        if not isinstance(accounts, list):
            accounts = []
        results = []
        for acc in accounts:
            if not isinstance(acc, dict):
                continue
            name = acc.get("name") or acc.get("display_name") or ""
            email = acc.get("email") or acc.get("preferred_email") or ""
            if not email and isinstance(acc.get("emails"), list):
                for e in acc["emails"]:
                    if isinstance(e, dict) and e.get("preferred"):
                        email = e.get("email") or e.get("value") or ""
                        break
                if not email and acc["emails"]:
                    email = acc["emails"][0].get("email") or acc["emails"][0].get("value") or "" if isinstance(acc["emails"][0], dict) else ""
            username = acc.get("username") or ""
            if email or name or username:
                results.append({"name": name, "email": email, "username": username})
        return jsonify({"results": results, "generated_at": datetime.utcnow().isoformat()})
    except requests.exceptions.Timeout:
        return jsonify({"results": [], "error": "Gerrit request timed out. Add reviewers manually by typing email and pressing Enter."})
    except requests.exceptions.ConnectionError as e:
        err = str(e)
        if "resolve" in err.lower() or "nodename" in err.lower():
            return jsonify({"results": [], "error": "Cannot reach Gerrit (check VPN/network). Add reviewers manually by typing email and pressing Enter."})
        return jsonify({"results": [], "error": "Cannot connect to Gerrit. Add reviewers manually by typing email and pressing Enter."})
    except Exception as e:
        logger.warning("search_reviewers failed: %s", e)
        return jsonify({"results": [], "error": "Could not fetch reviewers: %s. Add reviewers manually by typing email and pressing Enter." % str(e)})



@app.route("/mcp/regression/search-branches", methods=["GET"])
@jwt_required
def search_branches():
    """Suggest branch names for handover branch input."""
    q = (request.args.get("q") or "").strip()
    repo_name = (request.args.get("repo_name") or os.getenv("SOURCEGRAPH_FIRST_REPO", "nugerrit.ntnxdpro.com/nutest-py3-tests")).strip()
    raw_project = repo_name.split("/", 1)[-1] if "/" in repo_name else repo_name
    project_candidates = [repo_name, raw_project]

    suggestions = []
    seen = set()
    for c in _branch_alias_candidates(q)[:8]:
        if c not in seen:
            seen.add(c)
            suggestions.append(c)

    gerrit_url = (os.getenv("GERRIT_URL") or "https://nugerrit.ntnxdpro.com").strip().rstrip("/")
    auth = _get_gerrit_auth()
    headers = {"Accept": "application/json"}
    prefix = ""
    if auth:
        import base64
        user, pw = auth
        headers["Authorization"] = "Basic " + base64.b64encode(("%s:%s" % (user, pw)).encode()).decode()
        prefix = "/a"

    try:
        for project in project_candidates:
            encoded_project = urllib.parse.quote(project, safe="")
            url = "%s%s/projects/%s/branches/?n=25" % (gerrit_url, prefix, encoded_project)
            resp = requests.get(url, headers=headers, timeout=10, verify=False)
            if resp.status_code != 200:
                continue
            resp_text = resp.text
            if resp_text.startswith(")]}'"):
                resp_text = resp_text[5:]
            data = json.loads(resp_text) if resp_text else []
            branches = data if isinstance(data, list) else []
            for b in branches:
                ref = (b.get("ref") or "").strip()
                name = ref.replace("refs/heads/", "").strip()
                if not name:
                    continue
                if q and q.lower() not in name.lower():
                    if name not in suggestions and len(suggestions) < 4:
                        pass
                    else:
                        continue
                if name not in seen:
                    seen.add(name)
                    suggestions.append(name)
            if suggestions:
                break
    except Exception as exc:
        logger.warning("search_branches failed: %s", exc)

    return jsonify({"results": suggestions[:10], "query": q, "repo_name": repo_name})


@app.route("/mcp/regression/gerrit-connectivity", methods=["GET"])
@jwt_required
def gerrit_connectivity():
    """Check if we can reach Gerrit and authenticate (for CR creation)."""
    if request.method == "OPTIONS":
        return jsonify({}), 200
    gerrit_url = (os.getenv("GERRIT_URL") or "https://nugerrit.ntnxdpro.com").strip().rstrip("/")
    auth = _get_gerrit_auth()
    if not auth:
        return jsonify({
            "ok": False,
            "message": "Gerrit credentials not configured",
            "details": "Set GERRIT_USERNAME and GERRIT_HTTP_PASSWORD environment variables (only needed for reviewer search)",
        })
    url = "%s/a/accounts/self" % gerrit_url
    headers = {"Accept": "application/json"}
    import base64
    user, pw = auth
    headers["Authorization"] = "Basic " + base64.b64encode(("%s:%s" % (user, pw)).encode()).decode()
    try:
        resp = requests.get(url, headers=headers, timeout=10, verify=False)
        if resp.status_code == 200:
            text = resp.text
            if text.startswith(")]}'"):
                text = text[5:]
            data = json.loads(text) if text else {}
            username = data.get("username") or data.get("name") or user
            return jsonify({
                "ok": True,
                "message": "Connected to Gerrit",
                "details": "Authenticated as %s. Ready to create CR." % username,
            })
        if resp.status_code == 401:
            return jsonify({
                "ok": False,
                "message": "Gerrit authentication failed",
                "details": "Invalid credentials. Check GERRIT_USERNAME and GERRIT_HTTP_PASSWORD.",
            })
        return jsonify({
            "ok": False,
            "message": "Gerrit returned status %s" % resp.status_code,
            "details": (resp.text or "")[:200],
        })
    except requests.exceptions.Timeout:
        return jsonify({
            "ok": False,
            "message": "Gerrit request timed out",
            "details": "Check VPN/network and try again.",
        })
    except requests.exceptions.ConnectionError as e:
        err = str(e)
        if "resolve" in err.lower() or "nodename" in err.lower():
            return jsonify({
                "ok": False,
                "message": "Cannot reach Gerrit",
                "details": "Check VPN/network. DNS resolution failed.",
            })
        return jsonify({
            "ok": False,
            "message": "Gerrit connection failed",
            "details": str(e)[:200],
        })
    except Exception as e:
        logger.exception("gerrit_connectivity failed")
        return jsonify({
            "ok": False,
            "message": "Unexpected error",
            "details": str(e)[:200],
        })


def _build_gerrit_push_ref(branch, reviewers):
    """Build Gerrit push ref with optional reviewers (e.g. refs/for/master%r=user@x.com)."""
    ref = "refs/for/%s" % (branch or "master")
    if reviewers and isinstance(reviewers, list):
        reviewers = [r.strip() for r in reviewers if r and str(r).strip()]
        if reviewers:
            ref += "%" + ",".join("r=" + r for r in reviewers)
    return ref



def _get_gerrit_auth(prefer_ldap=False):
    """Get Gerrit auth as (username, password).

    When prefer_ldap=True (CR creation), use the logged-in LDAP username/password.
    Otherwise prefer env service credentials (reviewer search / branch listing).
    """
    if prefer_ldap:
        username = (_current_username() or "").strip()
        creds = _get_user_credentials(username) if username else None
        if creds and creds[1]:
            return (creds[0], creds[1])
        return None

    gerrit_token = (os.getenv("GERRIT_TOKEN") or "").strip()
    if gerrit_token and ":" in gerrit_token:
        parts = gerrit_token.split(":", 1)
        return (parts[0], parts[1])
    username = (os.getenv("GERRIT_USERNAME") or "").strip()
    password = (os.getenv("GERRIT_HTTP_PASSWORD") or "").strip()
    if username and password:
        return (username, password)
    # Fall back to LDAP for authenticated Gerrit calls when env not set
    ldap_user = (_current_username() or "").strip()
    creds = _get_user_credentials(ldap_user) if ldap_user else None
    if creds and creds[1]:
        return (creds[0], creds[1])
    return None


def _validate_gerrit_credentials(gerrit_url, username, password):
    """Validate Gerrit basic auth against /a/accounts/self."""
    if not gerrit_url or not username or not password:
        return False, "Missing Gerrit URL/username/password"
    url = "%s/a/accounts/self" % gerrit_url.rstrip("/")
    headers = {"Accept": "application/json"}
    import base64
    headers["Authorization"] = "Basic " + base64.b64encode(("%s:%s" % (username, password)).encode()).decode()
    try:
        resp = requests.get(url, headers=headers, timeout=12, verify=False)
        if resp.status_code == 200:
            return True, "Authenticated"
        if resp.status_code in (401, 403):
            return False, "Authentication failed (401/403)"
        return False, "Gerrit returned HTTP %s" % resp.status_code
    except requests.exceptions.Timeout:
        return False, "Gerrit request timed out"
    except requests.exceptions.ConnectionError:
        return False, "Cannot connect to Gerrit (VPN/network)"
    except Exception as exc:
        return False, str(exc)


def _run_git(args, cwd, check=True, timeout=None):
    """Run git command and return CompletedProcess. timeout is seconds (None = no limit)."""
    cmd = ["git"] + list(args)
    env = os.environ.copy()
    env["GIT_TERMINAL_PROMPT"] = "0"
    env["GIT_ASKPASS"] = "echo"
    try:
        return subprocess.run(
            cmd,
            cwd=cwd,
            text=True,
            capture_output=True,
            check=check,
            timeout=timeout,
            env=env,
        )
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError(
            "git %s timed out after %ss. The nutest-py3-tests clone is too slow; "
            "retry — sparse checkout should avoid a full download."
            % (" ".join(args[:3]), timeout)
        ) from exc


def _sparse_paths_for_lst_files(lst_files):
    """Return unique file paths to materialize via sparse-checkout."""
    out = []
    seen = set()
    for raw in lst_files or []:
        path = (raw or "").strip().lstrip("./")
        if not path or path in seen:
            continue
        seen.add(path)
        out.append(path)
    return out


def _generate_gerrit_change_id():
    """Generate a Gerrit-style Change-Id (I + 40 hex chars)."""
    raw = "%s-%s-%s" % (time.time(), os.getpid(), random.random())
    return "I" + hashlib.sha1(raw.encode("utf-8")).hexdigest()


def _install_gerrit_commit_msg_hook(repo_dir, gerrit_url, gerrit_user=None, gerrit_pwd=None):
    """Install Gerrit's commit-msg hook so commits get a Change-Id (Flux-style).

    Tries to download tools/hooks/commit-msg from Gerrit; falls back to a small
    local hook that appends Change-Id if missing.
    """
    hooks_dir = os.path.join(repo_dir, ".git", "hooks")
    os.makedirs(hooks_dir, exist_ok=True)
    hook_path = os.path.join(hooks_dir, "commit-msg")
    base = (gerrit_url or "").rstrip("/")
    urls = []
    if base:
        urls.append("%s/tools/hooks/commit-msg" % base)
        if gerrit_user and gerrit_pwd:
            auth_base = base.replace(
                "https://",
                "https://%s:%s@" % (urllib.parse.quote(gerrit_user), urllib.parse.quote(gerrit_pwd)),
                1,
            )
            if auth_base != base:
                urls.insert(0, "%s/tools/hooks/commit-msg" % auth_base)
            urls.append("%s/a/tools/hooks/commit-msg" % base)

    downloaded = False
    for url in urls:
        try:
            resp = requests.get(url, timeout=15, verify=False)
            if resp.status_code == 200 and resp.text and "Change-Id" in resp.text:
                with open(hook_path, "w", encoding="utf-8") as fh:
                    fh.write(resp.text)
                os.chmod(hook_path, 0o755)
                downloaded = True
                logger.info("Installed Gerrit commit-msg hook from %s", url.split("@")[-1])
                break
        except Exception as exc:
            logger.warning("Could not download commit-msg hook from Gerrit: %s", exc)

    if not downloaded:
        # Minimal hook: append Change-Id if the message does not already have one.
        script = """#!/bin/sh
# RegX fallback commit-msg hook (Change-Id)
MSG_FILE="$1"
if grep -q '^Change-Id:' "$MSG_FILE" 2>/dev/null; then
  exit 0
fi
CHANGE_ID="I$(openssl rand -hex 20 2>/dev/null || python3 -c 'import hashlib,os,time; print(hashlib.sha1(("%s-%s"%(time.time(),os.urandom(8))).encode()).hexdigest())')"
echo "" >> "$MSG_FILE"
echo "Change-Id: $CHANGE_ID" >> "$MSG_FILE"
exit 0
"""
        with open(hook_path, "w", encoding="utf-8") as fh:
            fh.write(script)
        os.chmod(hook_path, 0o755)
        logger.info("Installed fallback Change-Id commit-msg hook at %s", hook_path)
    return hook_path


def _ensure_change_id_in_message(commit_msg):
    """Ensure commit message body includes a Change-Id line."""
    msg = (commit_msg or "").rstrip()
    if re.search(r"(?m)^Change-Id:\s*I[0-9a-fA-F]{40}\s*$", msg):
        return msg
    return msg + "\n\nChange-Id: %s\n" % _generate_gerrit_change_id()


def _parse_gerrit_push_result(push_output, gerrit_url, repo_path):
    """Parse Gerrit push stdout/stderr for change number and URL (Flux-style)."""
    text = push_output or ""
    gerrit_url = (gerrit_url or "").rstrip("/")
    repo_path = (repo_path or "").strip("/")

    m = re.search(r"(https?://[^\s]+/c/[^\s]+/\+/(\d+))", text)
    if m:
        return {"gerrit_change_id": m.group(2), "gerrit_url": m.group(1).rstrip(")].,;'\"")}

    m = re.search(r"/c/([^\s]+)/\+/(\d+)", text)
    if m:
        cid = m.group(2)
        proj = m.group(1).strip("/")
        return {
            "gerrit_change_id": cid,
            "gerrit_url": "%s/c/%s/+/%s" % (gerrit_url, proj, cid),
        }

    m = re.search(r"\+/(\d+)\b", text)
    if m:
        cid = m.group(1)
        url = "%s/c/%s/+/%s" % (gerrit_url, repo_path, cid) if repo_path else "%s/#/c/%s" % (gerrit_url, cid)
        return {"gerrit_change_id": cid, "gerrit_url": url}

    return {"gerrit_change_id": "", "gerrit_url": ""}


def _commit_and_push_gerrit_cr(repo_dir, commit_msg, push_ref, gerrit_url, repo_path, gerrit_user=None, gerrit_pwd=None):
    """Install Change-Id hook, commit, push to refs/for, return parsed CR info."""
    _install_gerrit_commit_msg_hook(repo_dir, gerrit_url, gerrit_user=gerrit_user, gerrit_pwd=gerrit_pwd)
    final_msg = _ensure_change_id_in_message(commit_msg)
    _run_git(["commit", "-m", final_msg], cwd=repo_dir, check=True, timeout=60)
    push_t0 = time.time()
    logger.info("gerrit_cr: pushing HEAD:%s", push_ref)
    push = _run_git(["push", "origin", "HEAD:%s" % push_ref], cwd=repo_dir, check=True, timeout=180)
    logger.info("gerrit_cr: push done in %.1fs", time.time() - push_t0)
    combined = "%s\n%s" % (push.stdout or "", push.stderr or "")
    parsed = _parse_gerrit_push_result(combined, gerrit_url, repo_path)
    if not parsed.get("gerrit_url"):
        parsed["gerrit_url"] = "%s/q/status:open+project:%s" % (
            gerrit_url.rstrip("/"),
            urllib.parse.quote(repo_path, safe=""),
        )
    parsed["push_output"] = combined[:2000]
    return parsed


def _clone_and_sync_handover_branch(auth_url, repo_dir, branch, tmpdir, sparse_paths=None):
    """Sparse shallow-clone selected branch (LST paths only), then sync to origin tip.

    nutest-py3-tests is too large for a normal shallow clone (hangs on index-pack).
    Use --filter=blob:none --sparse and only materialize the LST file(s).
    """
    t0 = time.time()
    sparse_paths = _sparse_paths_for_lst_files(sparse_paths)
    logger.info(
        "create_lst_cr: sparse shallow clone branch=%s paths=%s -> %s",
        branch,
        sparse_paths or ["(full sparse root)"],
        repo_dir,
    )
    clone_timeout = 180
    clone_args = [
        "clone",
        "--depth", "1",
        "--filter=blob:none",
        "--sparse",
        "--single-branch",
        "--branch", branch,
        auth_url,
        repo_dir,
    ]
    clone = _run_git(clone_args, cwd=tmpdir, check=False, timeout=clone_timeout)
    if clone.returncode != 0:
        err = ((clone.stderr or clone.stdout or "")[:500]).strip()
        logger.warning("create_lst_cr: sparse branch clone failed (%s); falling back", err)
        if os.path.isdir(repo_dir):
            shutil.rmtree(repo_dir, ignore_errors=True)
        clone2 = _run_git(
            [
                "clone",
                "--depth", "1",
                "--filter=blob:none",
                "--sparse",
                "--single-branch",
                auth_url,
                repo_dir,
            ],
            cwd=tmpdir,
            check=True,
            timeout=clone_timeout,
        )
        _ = clone2
        fetch = _run_git(["fetch", "--depth", "1", "origin", branch], cwd=repo_dir, check=False, timeout=120)
        if fetch.returncode != 0:
            _run_git(["fetch", "origin", branch], cwd=repo_dir, check=True, timeout=120)
        checkout = _run_git(["checkout", "-B", branch, "origin/%s" % branch], cwd=repo_dir, check=False, timeout=60)
        if checkout.returncode != 0:
            _run_git(["checkout", "-B", branch, "FETCH_HEAD"], cwd=repo_dir, check=True, timeout=60)

    if sparse_paths:
        # Non-cone: exact LST file paths only (avoids downloading whole test_sets tree).
        sc = _run_git(
            ["sparse-checkout", "set", "--no-cone"] + sparse_paths,
            cwd=repo_dir,
            check=False,
            timeout=120,
        )
        if sc.returncode != 0:
            err = ((sc.stderr or sc.stdout or "")[:400]).strip()
            logger.warning("sparse-checkout --no-cone failed (%s); trying cone parents", err)
            parents = []
            for p in sparse_paths:
                parent = os.path.dirname(p)
                if parent and parent not in parents:
                    parents.append(parent)
            if parents:
                _run_git(["sparse-checkout", "set"] + parents, cwd=repo_dir, check=True, timeout=120)

    head = _run_git(["rev-parse", "--abbrev-ref", "HEAD"], cwd=repo_dir, check=True, timeout=30)
    current = (head.stdout or "").strip()
    if current != branch:
        logger.warning("create_lst_cr: HEAD is %r, expected %r; forcing checkout", current, branch)
        _run_git(["fetch", "--depth", "1", "origin", branch], cwd=repo_dir, check=False, timeout=120)
        _run_git(["checkout", "-B", branch, "origin/%s" % branch], cwd=repo_dir, check=True, timeout=60)

    # Sync tip without re-pulling the whole tree when possible
    fetch = _run_git(["fetch", "--depth", "1", "origin", branch], cwd=repo_dir, check=False, timeout=120)
    if fetch.returncode != 0:
        _run_git(["fetch", "origin", branch], cwd=repo_dir, check=False, timeout=120)
    reset = _run_git(["reset", "--hard", "origin/%s" % branch], cwd=repo_dir, check=False, timeout=60)
    if reset.returncode != 0:
        pull = _run_git(["pull", "--ff-only", "origin", branch], cwd=repo_dir, check=False, timeout=120)
        if pull.returncode != 0:
            logger.warning(
                "create_lst_cr: sync failed; force reset. pull=%s reset=%s",
                ((pull.stderr or "")[:200]),
                ((reset.stderr or "")[:200]),
            )
            _run_git(["fetch", "origin", branch], cwd=repo_dir, check=True, timeout=120)
            _run_git(["reset", "--hard", "origin/%s" % branch], cwd=repo_dir, check=True, timeout=60)
    _run_git(["clean", "-fd"], cwd=repo_dir, check=False, timeout=30)

    if sparse_paths:
        # Re-apply sparse after reset so LST files are present
        _run_git(
            ["sparse-checkout", "set", "--no-cone"] + sparse_paths,
            cwd=repo_dir,
            check=False,
            timeout=120,
        )

    head = _run_git(["rev-parse", "--abbrev-ref", "HEAD"], cwd=repo_dir, check=True, timeout=30)
    current = (head.stdout or "").strip()
    if current != branch:
        raise RuntimeError("After sync, HEAD is %r but expected branch %r" % (current, branch))

    logger.info("create_lst_cr: clone+sync done in %.1fs branch=%s", time.time() - t0, branch)


def _lst_cr_via_gerrit_rest(
    branch,
    lst_files,
    test_names,
    reviewers,
    commit_message,
    gerrit_user,
    gerrit_pwd,
    gerrit_url,
    repo_path,
    mode="append",
    handover_tickets=None,
    owner=None,
):
    """Create an LST CR with Gerrit Change Edit. mode is 'append' or 'remove'."""
    from gerrit_lst_cr import (
        GerritLstClient,
        GerritRestError,
        append_missing_tests,
        remove_tests,
    )

    client = GerritLstClient(gerrit_url, gerrit_user, gerrit_pwd, repo_path)
    file_contents = {}
    per_file = []
    removed_all = []
    not_present_all = []
    total_changed = 0
    tickets = handover_tickets or []
    owner_name = (owner or gerrit_user or "").strip()
    for lf in lst_files:
        try:
            content = client.get_file(branch, lf)
        except GerritRestError as exc:
            if exc.payload.get("gerrit_status") == 404 or "404" in (exc.message or ""):
                raise GerritRestError(
                    "File '%s' was not found on branch '%s'." % (lf, branch),
                    400,
                    {"error": "LST file not found on branch."},
                ) from exc
            raise
        if mode == "remove":
            new_content, removed, not_present = remove_tests(content, test_names)
            removed_all.extend(removed)
            not_present_all.extend(not_present)
            if removed:
                file_contents[lf] = new_content
                total_changed += len(removed)
            per_file.append({"lst_file": lf, "removed": removed, "not_present": not_present})
        else:
            new_content, already, to_add = append_missing_tests(
                content,
                test_names,
                owner=owner_name,
                branch=branch,
                tickets=tickets,
                lst_path=lf,
            )
            logger.info(
                "create_lst_cr append %s: requested=%s to_add=%s already_present=%s",
                lf,
                len(test_names),
                len(to_add),
                len(already),
            )
            if to_add:
                file_contents[lf] = new_content
                total_changed += len(to_add)
            per_file.append({"lst_file": lf, "already_present": already, "to_add": to_add})

    if total_changed == 0:
        if mode == "remove":
            return {
                "success": False,
                "message": "None of the selected tests were found in the LST file.",
                "removed": [],
                "not_present": list(dict.fromkeys(not_present_all)),
                "files": per_file,
            }
        return {
            "success": False,
            "message": "All selected tests are already present in selected LST file(s).",
            "files": per_file,
            "already_present": [x for p in per_file for x in p.get("already_present") or []],
            "to_add": [],
        }

    published = client.publish_lst_edits(branch, commit_message, file_contents, reviewers)
    published["files"] = per_file
    published["message"] = (
        "Deprecation CR created via Gerrit (no clone)."
        if mode == "remove"
        else "CR created via Gerrit (no clone)."
    )
    if mode == "remove":
        published["removed"] = list(dict.fromkeys(removed_all))
        # Use per-file unresolved queries, not raw test_names vs resolved LST names.
        published["not_present"] = list(dict.fromkeys(not_present_all))
    else:
        published["already_present"] = [x for p in per_file for x in p.get("already_present") or []]
        published["to_add"] = [x for p in per_file for x in p.get("to_add") or []]
    published["generated_at"] = datetime.utcnow().isoformat()
    return published


def _gerrit_identity_for_user():
    """Return (gerrit_username, gerrit_http_password, email_for_git) for CR push.

    Gerrit HTTP Credentials use the LDAP sAMAccountName (e.g. swapnil.wankhede)
    plus the Gerrit HTTP password from User Settings — not the email address.
    Email is kept only for git commit identity.
    """
    ldap_username = (_current_username() or "").strip()
    email = (_current_user_email() or "").strip()
    if not email and ldap_username:
        email = "%s@%s" % (ldap_username, CORP_EMAIL_DOMAIN)
    gerrit_user = ldap_username or (email.split("@")[0] if email else "")
    http_pwd = (get_user_key(ldap_username, "gerrit_http_password") or "").strip() if ldap_username else ""
    return gerrit_user, http_pwd, email or ""


def _collect_lst_files_from_payload(data):
    """Merge lst_file + lst_files from a request body, unique, order preserved."""
    data = data or {}
    lst_file = (data.get("lst_file") or "").strip()
    lst_files = data.get("lst_files") or []
    if not isinstance(lst_files, list):
        lst_files = []
    out = []
    seen = set()
    for raw in list(lst_files) + ([lst_file] if lst_file else []):
        path = str(raw or "").strip()
        if not path or path in seen:
            continue
        seen.add(path)
        out.append(path)
    return out


@app.route("/mcp/regression/create-lst-cr", methods=["POST"])
@jwt_required
def create_lst_cr():
    """Create Gerrit CR to add selected handover tests into an LST file using Gerrit HTTP password."""
    if request.method == "OPTIONS":
        return jsonify({}), 200

    data = request.get_json() or {}
    branch = _handover_nutest_branch(data.get("branch") or "master")
    lst_files = _collect_lst_files_from_payload(data)
    test_names = data.get("test_names") or []
    reviewers = [str(r).strip() for r in (data.get("reviewers") or []) if str(r).strip()]
    cr_subject = (data.get("cr_subject") or "Testcase Handover").strip() or "Testcase Handover"
    cr_description = (data.get("cr_description") or "").strip()
    handover_tickets = data.get("handover_tickets") or []
    if isinstance(handover_tickets, str):
        handover_tickets = [x.strip() for x in handover_tickets.split(",") if x.strip()]
    else:
        handover_tickets = [str(x).strip() for x in handover_tickets if str(x).strip()]
    manual_only = bool(data.get("manual_only"))

    if not lst_files:
        return jsonify({"error": "lst_file or lst_files is required"}), 400
    test_names = [str(t).strip() for t in test_names if str(t or "").strip()]
    if not test_names:
        return jsonify({"error": "test_names is required"}), 400

    push_ref = _build_gerrit_push_ref(branch, reviewers)
    if manual_only:
        instructions = {
            "message": "Add the following %s test(s) to the LST file, then push for review." % len(test_names),
            "branch": branch, "lst_file": lst_files[0], "test_names": test_names,
            "manual_steps": [
                "1. Clone the repository and checkout branch '%s'" % branch,
                "2. Open the LST file: %s" % lst_files[0],
                "3. Add the following %s test name(s) to the file:" % len(test_names),
                "   " + "\n   ".join(test_names[:10]) + ("..." if len(test_names) > 10 else ""),
                "4. Commit with message: 'Add %s test(s) to LST'" % len(test_names),
                "5. Push for review: git push origin HEAD:%s" % push_ref,
            ],
        }
        return jsonify({
            "manual": True,
            "instructions": instructions,
            "message": "Follow the manual steps below to push the change for review.",
            "generated_at": datetime.utcnow().isoformat(),
        })

    gerrit_user, gerrit_pwd, git_email = _gerrit_identity_for_user()
    if not gerrit_user:
        return jsonify({
            "error": "Logged-in username is required for Gerrit CR creation.",
            "message": "Could not resolve your Gerrit username from the session. Log in again and retry.",
        }), 400
    if not gerrit_pwd:
        return jsonify({
            "error": "Gerrit HTTP password missing. Save it in Settings → API Keys → Gerrit HTTP Password.",
            "require_key_setup": True,
            "missing_key": "gerrit_http_password",
            "message": "Generate an HTTP password in Gerrit → Settings → HTTP Credentials (username is your LDAP id, e.g. firstname.lastname), then paste it in RegX User Settings and Save.",
        }), 403

    gerrit_url = (os.getenv("GERRIT_URL") or "https://nugerrit.ntnxdpro.com").strip().rstrip("/")
    ok_auth, auth_msg = _validate_gerrit_credentials(gerrit_url, gerrit_user, gerrit_pwd)
    if not ok_auth:
        return jsonify({
            "error": "Gerrit authentication failed.",
            "message": "Unable to validate Gerrit HTTP password for %s: %s. Re-generate the HTTP password in Gerrit and update Settings." % (gerrit_user, auth_msg),
            "require_key_setup": True,
            "missing_key": "gerrit_http_password",
        }), 403

    repo_path = (os.getenv("HANDOVER_REPO_PATH") or "nutest-py3-tests").strip("/")

    from gerrit_lst_cr import GerritRestError, force_git_clone, git_fallback_enabled

    if not cr_description:
        reviewers_line = ", ".join(reviewers) if reviewers else ""
        tickets_line = ", ".join(handover_tickets) if handover_tickets else ""
        tests_line = ", ".join(test_names[:15]) + (" ..." if len(test_names) > 15 else "")
        cr_description = (
            "Reviewers               : %s\n"
            "Tickets resolved        : %s\n"
            "Tests run               : %s\n"
            "Target release          : %s\n"
            "Code review URL         : "
        ) % (reviewers_line, tickets_line, tests_line, branch)
    commit_msg = cr_subject + "\n\n" + cr_description

    if not force_git_clone():
        try:
            logger.info("create_lst_cr: Gerrit REST edit branch=%s files=%s", branch, lst_files)
            result = _lst_cr_via_gerrit_rest(
                branch, lst_files, test_names, reviewers, commit_msg,
                gerrit_user, gerrit_pwd, gerrit_url, repo_path, mode="append",
                handover_tickets=handover_tickets,
                owner=gerrit_user,
            )
            return jsonify(result)
        except GerritRestError as exc:
            if not git_fallback_enabled():
                return jsonify({
                    "error": exc.payload.get("error") or exc.message,
                    "message": exc.message,
                }), exc.status_code if 400 <= exc.status_code < 500 else 502
            logger.warning("create_lst_cr REST failed, git fallback: %s", exc.message)
        except Exception as exc:
            if not git_fallback_enabled():
                logger.exception("create_lst_cr REST failed")
                return jsonify({"error": str(exc), "message": "Unexpected error during CR creation."}), 500
            logger.warning("create_lst_cr REST failed, git fallback: %s", exc)

    clone_url = "%s/a/%s" % (gerrit_url, repo_path)

    tmpdir = tempfile.mkdtemp(prefix="regx_handover_")
    repo_dir = os.path.join(tmpdir, "repo")
    try:
        auth_url = clone_url.replace(
            "https://",
            "https://%s:%s@" % (urllib.parse.quote(gerrit_user), urllib.parse.quote(gerrit_pwd)),
        )
        _clone_and_sync_handover_branch(auth_url, repo_dir, branch, tmpdir, sparse_paths=lst_files)
        if git_email:
            _run_git(["config", "user.email", git_email], cwd=repo_dir, check=False)
        display_name = (_current_username() or gerrit_user.split("@")[0] or gerrit_user).strip()
        _run_git(["config", "user.name", display_name], cwd=repo_dir, check=False)
        logger.info("create_lst_cr: applying LST edits on branch=%s files=%s", branch, lst_files)

        from gerrit_lst_cr import append_missing_tests as _append_missing_tests

        per_file = []
        total_to_add = 0
        for lf in lst_files:
            abs_lst = os.path.join(repo_dir, lf)
            if not os.path.isfile(abs_lst):
                return jsonify({
                    "error": "LST file not found on branch.",
                    "message": "File '%s' was not found on branch '%s'." % (lf, branch),
                }), 400
            with open(abs_lst, "r", encoding="utf-8", errors="ignore") as fh:
                old_content = fh.read()
            new_content, already_present, to_add = _append_missing_tests(
                old_content,
                test_names,
                owner=gerrit_user,
                branch=branch,
                tickets=handover_tickets,
                lst_path=lf,
            )
            if to_add:
                with open(abs_lst, "w", encoding="utf-8") as fh:
                    fh.write(new_content)
                _run_git(["add", lf], cwd=repo_dir, check=True)
            per_file.append({"lst_file": lf, "already_present": already_present, "to_add": to_add})
            total_to_add += len(to_add)

        if total_to_add == 0:
            return jsonify({
                "success": False,
                "message": "All selected tests are already present in selected LST file(s).",
                "files": per_file,
                "already_present": [x for p in per_file for x in p["already_present"]],
                "to_add": [],
            })

        if not cr_description:
            reviewers_line = ", ".join(reviewers) if reviewers else ""
            tickets_line = ", ".join(handover_tickets) if handover_tickets else ""
            all_to_add = [x for p in per_file for x in p["to_add"]]
            tests_line = ", ".join(all_to_add[:15]) + (" ..." if len(all_to_add) > 15 else "")
            cr_description = (
                "Reviewers               : %s\n"
                "Tickets resolved        : %s\n"
                "Tests run               : %s\n"
                "Target release          : %s\n"
                "Code review URL         : "
            ) % (reviewers_line, tickets_line, tests_line, branch)

        commit_msg = cr_subject + "\n\n" + cr_description
        logger.info("create_lst_cr: committing %s test(s) on branch=%s", total_to_add, branch)
        parsed = _commit_and_push_gerrit_cr(
            repo_dir,
            commit_msg,
            push_ref,
            gerrit_url,
            repo_path,
            gerrit_user=gerrit_user,
            gerrit_pwd=gerrit_pwd,
        )
        cr_url = parsed.get("gerrit_url") or "%s/q/status:open+owner:%s+project:%s+branch:%s" % (
            gerrit_url,
            urllib.parse.quote(gerrit_user, safe=""),
            urllib.parse.quote(repo_path, safe=""),
            urllib.parse.quote(branch, safe=""),
        )

        return jsonify({
            "success": True,
            "message": "CR created and pushed for review.",
            "cr_url": cr_url,
            "gerrit_url": cr_url,
            "gerrit_change_id": parsed.get("gerrit_change_id") or "",
            "files": per_file,
            "already_present": [x for p in per_file for x in p["already_present"]],
            "to_add": [x for p in per_file for x in p["to_add"]],
            "push_ref": push_ref,
            "generated_at": datetime.utcnow().isoformat(),
        })
    except subprocess.CalledProcessError as cpe:
        stderr = (cpe.stderr or "").strip()
        stdout = (cpe.stdout or "").strip()
        msg = stderr or stdout or str(cpe)
        return jsonify({
            "error": "Failed to create CR via git/gerrit.",
            "git_error": msg[:1000],
            "message": "Create CR failed. Check Gerrit HTTP password, branch, VPN/network, and repository permissions.",
        }), 502
    except Exception as exc:
        logger.exception("create_lst_cr failed")
        return jsonify({"error": str(exc), "message": "Unexpected error during CR creation."}), 500
    finally:
        try:
            shutil.rmtree(tmpdir, ignore_errors=True)
        except Exception:
            pass


@app.route("/mcp/regression/check-lst-testcases", methods=["POST"])
@jwt_required
def check_lst_testcases():
    """Check which testcases are present in LST file."""
    if request.method == "OPTIONS":
        return jsonify({}), 200
    data = request.get_json() or {}
    branch = _handover_nutest_branch(data.get("branch") or "master")
    lst_file = (data.get("lst_file") or "").strip().replace("(pasted content)", "").strip()
    test_names = data.get("test_names") or []
    lst_file_content = data.get("lst_file_content")
    repo_name = (data.get("repo_name") or os.getenv("SOURCEGRAPH_FIRST_REPO", "nugerrit.ntnxdpro.com/nutest-py3-tests")).strip()
    if not lst_file and not (lst_file_content and isinstance(lst_file_content, str)):
        return jsonify({"error": "Enter LST file path or paste LST file content"}), 400
    test_names = [str(t).strip() for t in test_names if (t or "").strip()]
    if not test_names:
        return jsonify({"error": "test_names is required (at least one)"}), 400
    if lst_file_content:
        already_present, not_present, extra = _check_testnames_in_lst_content(lst_file_content, test_names)
        payload = {
            "branch": branch,
            "lst_file": lst_file or "(pasted content)",
            "test_names": test_names,
            "present": already_present,
            "not_present": not_present,
            "generated_at": datetime.utcnow().isoformat(),
        }
        payload.update(extra or {})
        return jsonify(payload)
    if not lst_file:
        return jsonify({"error": "Enter LST file path or paste LST file content"}), 400
    content, resolved_branch, resolved_path, err = _fetch_lst_content_for_check(
        repo_name, branch, lst_file, explicit_token=data.get("sourcegraph_token")
    )
    if err:
        return jsonify({
            "error": err,
            "test_names": test_names,
            "present": [],
            "not_present": test_names,
            "branch": branch,
            "lst_file": lst_file,
            "generated_at": datetime.utcnow().isoformat(),
        }), 200
    already_present, not_present, extra = _check_testnames_in_lst_content(content, test_names)
    payload = {
        "branch": resolved_branch or branch,
        "input_branch": branch,
        "resolved_branch": resolved_branch or branch,
        "lst_file": resolved_path or lst_file,
        "input_lst_file": lst_file,
        "test_names": test_names,
        "present": already_present,
        "not_present": not_present,
        "generated_at": datetime.utcnow().isoformat(),
    }
    payload.update(extra or {})
    return jsonify(payload)

def search_sourcegraph_for_test(repo_name, test_name, rev="master", lst_files_only=False, sg_token=None, max_count=50):
    """Search Sourcegraph for files containing the test name."""
    test_name = str(test_name).strip() if test_name else ""
    if not test_name:
        return []
    token = (sg_token or os.getenv("SOURCEGRAPH_TOKEN") or "").strip()
    if not token:
        return []
    base_url = (os.getenv("SOURCEGRAPH_URL") or "https://sourcegraph.ntnxdpro.com").strip().rstrip("/")
    # Sourcegraph's GraphQL endpoint is "/.api/graphql" (with the dot). Try the
    # configured path first (if any), then the standard candidates - same as
    # validate_with_sourcegraph / fetch_file_content_via_sourcegraph.
    configured_path = (os.getenv("SOURCEGRAPH_GRAPHQL_PATH") or "").strip()
    if configured_path and not configured_path.startswith("/"):
        configured_path = "/" + configured_path
    api_urls = []
    for p in [configured_path, "/.api/graphql", "/api/graphql", "/graphql"]:
        if not p:
            continue
        u = base_url + p
        if u not in api_urls:
            api_urls.append(u)
    auth_headers = [
        {"Content-Type": "application/json", "Authorization": "token %s" % token},
        {"Content-Type": "application/json", "Authorization": "Bearer %s" % token},
    ]
    escaped = test_name.replace("\\", "\\\\").replace('"', '\\"')
    search_query = f'repo:{repo_name} rev:{rev} "{escaped}" count:{int(max_count) if max_count else 50}'
    payload = {"query": "query Search($q: String!) { search(query: $q) { results { matchCount results { ... on FileMatch { file { path } } } } } }", "variables": {"q": search_query}}
    for api_url in api_urls:
        for headers in auth_headers:
            try:
                resp = requests.post(api_url, json=payload, headers=headers, timeout=20, verify=False)
                if resp.status_code != 200:
                    continue
                data = resp.json()
                if data.get("errors"):
                    continue
                search_node = (data.get("data") or {}).get("search")
                if not search_node:
                    continue
                results_node = search_node.get("results") or search_node.get("matches")
                if isinstance(results_node, dict):
                    hits = results_node.get("results", results_node.get("matches", [])) or []
                elif isinstance(results_node, list):
                    hits = results_node
                else:
                    continue
                out = [{"path": h["file"]["path"], "repo": repo_name, "rev": rev} for h in hits if isinstance(h, dict) and (h.get("file") or {}).get("path")]
                if lst_files_only:
                    out = [x for x in out if (x.get("path") or "").lower().endswith(".lst")]
                return out
            except Exception as e:
                logger.warning("[SOURCEGRAPH] Search failed (%s): %s", api_url, e)
                continue
    return []



@app.route("/mcp/regression/suggest-lst-file", methods=["POST"])
@jwt_required
def suggest_lst_file():
    """Suggest the best-fit LST file for selected handover testcases."""
    data = request.get_json() or {}
    test_names = data.get("test_names") or []
    branch = _handover_nutest_branch(data.get("branch") or "master")
    repo_name = (data.get("repo_name") or os.getenv("SOURCEGRAPH_FIRST_REPO", "nugerrit.ntnxdpro.com/nutest-py3-tests")).strip()

    test_names = [str(t).strip() for t in test_names if (t or "").strip()]
    if not test_names:
        return jsonify({"error": "test_names is required (at least one testcase)"}), 400
    sampled_total = len(test_names)
    test_names = test_names[:20]

    token = resolve_sourcegraph_token(data.get("sourcegraph_token"))
    if not token:
        return jsonify({
            "suggested_lst_file": "",
            "candidates": [],
            "testcase_candidates": {},
            "covered_tests": 0,
            "total_tests": len(test_names),
            "tie": False,
            "error": "Sourcegraph token not configured. Add Sourcegraph Token in Settings → API Key Configuration.",
            "generated_at": datetime.utcnow().isoformat(),
        })

    testcase_candidates = {}
    freq = defaultdict(int)
    seen_by_path = defaultdict(set)

    def _search_one(test_name):
        hits = search_sourcegraph_for_test(
            repo_name,
            test_name,
            rev=branch,
            lst_files_only=True,
            sg_token=token,
            max_count=20,
        )
        paths = []
        seen = set()
        for h in hits:
            path = (h.get("path") or "").strip()
            if not path or path in seen:
                continue
            seen.add(path)
            paths.append(path)
        return test_name, paths

    with ThreadPoolExecutor(max_workers=min(8, max(1, len(test_names)))) as executor:
        future_map = {executor.submit(_search_one, tn): tn for tn in test_names}
        for fut in as_completed(future_map):
            test_name, paths = fut.result()
            testcase_candidates[test_name] = paths
            for path in paths:
                if test_name not in seen_by_path[path]:
                    seen_by_path[path].add(test_name)
                    freq[path] += 1

    low_branch = branch.lower()
    branch_hints = []
    if low_branch == "master":
        branch_hints = ["/master/", "/milestones/master/"]
    else:
        m = re.search(r"(\d+\.\d+)", low_branch)
        if m:
            v = m.group(1)
            branch_hints = ["/%s/" % v, "/%s-stable/" % v, "/ganges-%s/" % v]
        branch_hints.append("/%s/" % low_branch)

    def _score(path, count):
        p = path.lower()
        bonus = 0
        for i, hint in enumerate(branch_hints):
            if hint in p:
                bonus = max(bonus, 50 - i * 5)
        # Prefer stable/regression LST paths over intransit for auto-suggestion.
        if "intransit" in p:
            bonus -= 200
        return count * 100 + bonus

    ranked = sorted(freq.items(), key=lambda kv: (-_score(kv[0], kv[1]), -kv[1], kv[0]))
    candidates = [{"lst_file": path, "count": count} for path, count in ranked]

    # Never auto-suggest an intransit LST; keep those in candidates for manual pick only.
    from handover_helpers import prefer_non_intransit_lst
    suggested = prefer_non_intransit_lst([path for path, _count in ranked])
    top_count = ranked[0][1] if ranked else 0
    tie = len(ranked) > 1 and ranked[1][1] == top_count and top_count > 0
    covered_tests = len({t for t, hits in testcase_candidates.items() if hits})

    if suggested:
        message = (
            "Suggested LST selected by majority of matching selected testcases."
            + (" Checked first 20 selected passed tests for faster suggestions." if sampled_total > 20 else "")
        )
    elif ranked:
        message = (
            "Only intransit LST matches found — pick one manually from candidates, "
            "or enter a non-intransit LST path."
        )
    else:
        message = "No matching LST files found for selected testcases on this branch."

    return jsonify({
        "branch": branch,
        "repo_name": repo_name,
        "suggested_lst_file": suggested,
        "candidates": candidates,
        "testcase_candidates": testcase_candidates,
        "covered_tests": covered_tests,
        "total_tests": sampled_total,
        "tie": tie,
        "message": message,
        "generated_at": datetime.utcnow().isoformat(),
    })


@app.route("/mcp/regression/search-lst-file", methods=["POST"])
@jwt_required
def search_lst_file():
    """Search for LST files containing a test name via Sourcegraph."""
    if request.method == "OPTIONS":
        return jsonify({}), 200
    data = request.get_json() or {}
    test_name = (data.get("test_name") or "").strip()
    if not test_name:
        return jsonify({"error": "test_name is required", "lst_files": []}), 400
    repo_name = os.getenv("SOURCEGRAPH_FIRST_REPO", "nugerrit.ntnxdpro.com/nutest-py3-tests")
    rev = _handover_nutest_branch(data.get("rev") or "master")
    lst_files = search_sourcegraph_for_test(repo_name, test_name, rev=rev, lst_files_only=True)
    token = (os.getenv("SOURCEGRAPH_TOKEN") or "").strip()
    if not lst_files and not token:
        return jsonify({"test_name": test_name, "lst_files": [], "error": "Sourcegraph integration not configured. Set the SOURCEGRAPH_TOKEN environment variable.", "generated_at": datetime.utcnow().isoformat()})
    return jsonify({"test_name": test_name, "lst_files": [f["path"] for f in lst_files], "generated_at": datetime.utcnow().isoformat()})


@app.route("/mcp/regression/deprecate-lst-cr", methods=["POST"])
@jwt_required
def deprecate_lst_cr():
    """Create Gerrit CR to remove selected tests from an LST file (Flux-style Change-Id + push parse)."""
    if request.method == "OPTIONS":
        return jsonify({}), 200
    data = request.get_json() or {}
    branch = _handover_nutest_branch(data.get("branch") or "master")
    lst_files = _collect_lst_files_from_payload(data)
    test_names = data.get("test_names") or []
    reviewers = [str(r).strip() for r in (data.get("reviewers") or []) if str(r).strip()]
    commit_message = (data.get("commit_message") or "").strip()
    jira_tickets = data.get("jira_tickets") or data.get("tickets") or []
    if isinstance(jira_tickets, str):
        jira_tickets = [x.strip() for x in jira_tickets.split(",") if x.strip()]
    else:
        jira_tickets = [str(x).strip() for x in jira_tickets if str(x).strip()]
    manual_only = bool(data.get("manual_only"))

    if not test_names:
        return jsonify({"error": "test_names is required"}), 400
    if not lst_files:
        return jsonify({"error": "lst_file or lst_files is required"}), 400
    test_names = [str(t).strip() for t in test_names if (t or "").strip()]
    if not test_names:
        return jsonify({"error": "test_names is required"}), 400
    lst_file = lst_files[0]

    push_ref = _build_gerrit_push_ref(branch, reviewers)
    instructions = {
        "message": "Remove the following %s test(s) from the LST file(s), then push for review." % len(test_names),
        "branch": branch, "lst_file": lst_file, "lst_files": lst_files, "test_names": test_names,
        "manual_steps": [
            "1. Clone the repository and checkout branch '%s'" % branch,
            "2. Open the LST file(s): %s" % ", ".join(lst_files),
            "3. Remove the following %s test name(s) from each file:" % len(test_names),
            "   " + "\n   ".join(test_names[:10]) + ("..." if len(test_names) > 10 else ""),
            "4. Commit with message: 'Deprecated %s test(s) from LST'" % len(test_names),
            "5. Push for review: git push origin HEAD:%s" % push_ref,
        ],
    }
    if manual_only:
        return jsonify({
            "manual": True,
            "instructions": instructions,
            "message": "Follow the manual steps below to push the change for review.",
            "generated_at": datetime.utcnow().isoformat(),
        })

    gerrit_user, gerrit_pwd, git_email = _gerrit_identity_for_user()
    if not gerrit_user:
        return jsonify({
            "error": "Logged-in username is required for Gerrit CR creation.",
            "message": "Could not resolve your Gerrit username from the session. Log in again and retry.",
        }), 400
    if not gerrit_pwd:
        return jsonify({
            "error": "Gerrit HTTP password missing. Save it in Settings → API Keys → Gerrit HTTP Password.",
            "require_key_setup": True,
            "missing_key": "gerrit_http_password",
            "message": "Generate an HTTP password in Gerrit → Settings → HTTP Credentials, then paste it in RegX User Settings and Save.",
        }), 403

    gerrit_url = (os.getenv("GERRIT_URL") or "https://nugerrit.ntnxdpro.com").strip().rstrip("/")
    ok_auth, auth_msg = _validate_gerrit_credentials(gerrit_url, gerrit_user, gerrit_pwd)
    if not ok_auth:
        return jsonify({
            "error": "Gerrit authentication failed.",
            "message": "Unable to validate Gerrit HTTP password for %s: %s." % (gerrit_user, auth_msg),
            "require_key_setup": True,
            "missing_key": "gerrit_http_password",
        }), 403

    repo_path = (os.getenv("HANDOVER_REPO_PATH") or "nutest-py3-tests").strip("/")

    from gerrit_lst_cr import GerritRestError, force_git_clone, git_fallback_enabled

    if not commit_message:
        commit_message = "Deprecated %s test(s) from %s" % (len(test_names), ", ".join(lst_files))
        if jira_tickets:
            commit_message += "\n\nJira: %s" % ", ".join(jira_tickets)

    if not force_git_clone():
        try:
            logger.info("deprecate_lst_cr: Gerrit REST edit branch=%s files=%s", branch, lst_files)
            result = _lst_cr_via_gerrit_rest(
                branch, lst_files, test_names, reviewers, commit_message,
                gerrit_user, gerrit_pwd, gerrit_url, repo_path, mode="remove",
                handover_tickets=jira_tickets,
                owner=gerrit_user,
            )
            return jsonify(result)
        except GerritRestError as exc:
            if not git_fallback_enabled():
                return jsonify({
                    "error": exc.payload.get("error") or exc.message,
                    "message": exc.message,
                    "instructions": instructions,
                }), exc.status_code if 400 <= exc.status_code < 500 else 502
            logger.warning("deprecate_lst_cr REST failed, git fallback: %s", exc.message)
        except Exception as exc:
            if not git_fallback_enabled():
                logger.exception("deprecate_lst_cr REST failed")
                return jsonify({"error": str(exc), "message": "Unexpected error during deprecation CR creation."}), 500
            logger.warning("deprecate_lst_cr REST failed, git fallback: %s", exc)

    clone_url = "%s/a/%s" % (gerrit_url, repo_path)
    tmpdir = tempfile.mkdtemp(prefix="regx_deprecate_")
    repo_dir = os.path.join(tmpdir, "repo")
    try:
        auth_url = clone_url.replace(
            "https://",
            "https://%s:%s@" % (urllib.parse.quote(gerrit_user), urllib.parse.quote(gerrit_pwd)),
        )
        _clone_and_sync_handover_branch(auth_url, repo_dir, branch, tmpdir, sparse_paths=lst_files)
        if git_email:
            _run_git(["config", "user.email", git_email], cwd=repo_dir, check=False)
        display_name = (_current_username() or gerrit_user.split("@")[0] or gerrit_user).strip()
        _run_git(["config", "user.name", display_name], cwd=repo_dir, check=False)

        from gerrit_lst_cr import remove_tests as _remove_tests

        per_file = []
        removed_all = []
        not_present_all = []
        for lf in lst_files:
            abs_lst = os.path.join(repo_dir, lf)
            if not os.path.isfile(abs_lst):
                return jsonify({
                    "error": "LST file not found on branch.",
                    "message": "File '%s' was not found on branch '%s'." % (lf, branch),
                }), 400
            with open(abs_lst, "r", encoding="utf-8", errors="ignore") as fh:
                old_content = fh.read()
            new_content, removed, not_present = _remove_tests(old_content, test_names)
            per_file.append({"lst_file": lf, "removed": removed, "not_present": not_present})
            removed_all.extend(removed)
            not_present_all.extend(not_present)
            if removed:
                with open(abs_lst, "w", encoding="utf-8") as fh:
                    fh.write(new_content)
                _run_git(["add", lf], cwd=repo_dir, check=True)

        if not removed_all:
            return jsonify({
                "success": False,
                "message": "None of the selected tests were found in the LST file(s).",
                "removed": [],
                "not_present": not_present_all,
                "files": per_file,
            })

        if not commit_message:
            commit_message = "Deprecated %s test(s) from %s" % (len(removed_all), ", ".join(lst_files))
            if jira_tickets:
                commit_message += "\n\nJira: %s" % ", ".join(jira_tickets)

        logger.info("deprecate_lst_cr: committing removal of %s test(s) on branch=%s", len(removed_all), branch)
        parsed = _commit_and_push_gerrit_cr(
            repo_dir,
            commit_message,
            push_ref,
            gerrit_url,
            repo_path,
            gerrit_user=gerrit_user,
            gerrit_pwd=gerrit_pwd,
        )
        cr_url = parsed.get("gerrit_url") or ""
        return jsonify({
            "success": True,
            "message": "Deprecation CR created and pushed for review.",
            "cr_url": cr_url,
            "gerrit_url": cr_url,
            "gerrit_change_id": parsed.get("gerrit_change_id") or "",
            "removed": removed_all,
            "not_present": not_present_all,
            "files": per_file,
            "push_ref": push_ref,
            "generated_at": datetime.utcnow().isoformat(),
        })
    except subprocess.CalledProcessError as cpe:
        stderr = (cpe.stderr or "").strip()
        stdout = (cpe.stdout or "").strip()
        msg = stderr or stdout or str(cpe)
        return jsonify({
            "error": "Failed to create deprecation CR via git/gerrit.",
            "git_error": msg[:1000],
            "message": "Create CR failed. Check Gerrit HTTP password, branch, VPN/network, and repository permissions.",
            "instructions": instructions,
        }), 502
    except Exception as exc:
        logger.exception("deprecate_lst_cr failed")
        return jsonify({"error": str(exc), "message": "Unexpected error during deprecation CR creation."}), 500
    finally:
        try:
            shutil.rmtree(tmpdir, ignore_errors=True)
        except Exception:
            pass


@app.route("/mcp/regression/deprecation-search", methods=["GET", "POST"])
@jwt_required
def deprecation_search():
    """Search handover records for deprecation. Includes Sourcegraph LST file hints for each query."""
    # Support both GET (params) and POST (body) to avoid URL length/encoding issues with long test names
    data = {}
    if request.method == "POST":
        data = request.get_json(silent=True) or {}
    parts = request.args.getlist("q")
    if not parts:
        q0 = (request.args.get("q") or request.args.get("test_name") or "").strip()
        parts = [q0] if q0 else []
    if not parts:
        q_from_body = data.get("q") or data.get("queries") or data.get("test_names")
        if isinstance(q_from_body, list):
            parts = [str(x).strip() for x in q_from_body if str(x).strip()]
        elif q_from_body:
            parts = [str(q_from_body).strip()]
    branch = (data.get("branch") or request.args.get("branch") or "").strip()
    queries = []
    for p in parts:
        if not p:
            continue
        s = str(p).strip()
        if not s:
            continue
        # Split on whitespace, comma, or newline to support "test_a test_b", "test_a,test_b", etc.
        queries.extend([t.strip() for t in re.split(r"[\s,\n\r]+", s) if t.strip()])
    seen_q = set()
    uniq_queries = []
    for q in queries:
        k = q.lower()
        if k not in seen_q:
            seen_q.add(k)
            uniq_queries.append(q)
    queries = uniq_queries
    if not queries:
        return jsonify({
            "results": [], "count": 0, "message": "Provide query parameter q (one or more test names; repeat q= for each, or comma/newline in a single q).",
            "sourcegraph_first_repo": [], "sourcegraph_other_repos": [],
            "sourcegraph_first_repo_name": "nugerrit.ntnxdpro.com/nutest-py3-tests",
            "generated_at": datetime.utcnow().isoformat()
        })
    records = _load_handover_records()
    q_lowers = [qt.lower() for qt in queries]
    matches = [r for r in records if any(qt in (r.get("test_name") or "").lower() for qt in q_lowers)]
    seen_key = set()
    unique_matches = []
    for r in matches:
        key = ((r.get("test_name") or "").strip(), (r.get("handover_date") or "").strip(), (r.get("lst_file") or "").strip())
        if key not in seen_key:
            seen_key.add(key)
            unique_matches.append(r)
    unique_matches.sort(key=lambda r: r.get("handover_date") or "", reverse=True)

    # Sourcegraph: only when a branch is provided so we search that revision, not master.
    sourcegraph_first_repo = []
    sourcegraph_other_repos = []
    repo_name = os.getenv("SOURCEGRAPH_FIRST_REPO", "nugerrit.ntnxdpro.com/nutest-py3-tests")
    token = resolve_sourcegraph_token(data.get("sourcegraph_token") if isinstance(data, dict) else None)
    if token and queries and branch:
        seen_paths = set()
        rev = _handover_nutest_branch(branch)
        for test_name in queries[:10]:
            lst_hits = search_sourcegraph_for_test(
                repo_name, test_name, rev=rev, lst_files_only=True, sg_token=token
            )
            for f in lst_hits:
                path = f.get("path", "")
                if path and path not in seen_paths:
                    seen_paths.add(path)
                    sourcegraph_first_repo.append({"path": path, "test_name": test_name, "rev": rev})
        sourcegraph_other_repos = []

    return jsonify({
        "q": " ".join(queries), "queries": queries, "results": unique_matches, "count": len(unique_matches),
        "branch": branch,
        "sourcegraph_first_repo": sourcegraph_first_repo,
        "sourcegraph_other_repos": sourcegraph_other_repos,
        "sourcegraph_first_repo_name": repo_name,
        "generated_at": datetime.utcnow().isoformat()
    })


@app.route("/mcp/regression/failed-analysis/first-level-ai", methods=["POST"])
@app.route("/api/agents/triage/first-level-ai", methods=["POST"])
@jwt_required
def first_level_ai_analysis():
    """First Level AI: failure analysis plus Triage Genie ticket validation.

    Phase 2: returns formal intelligent_triage schema + decision engine outcome.
    Never auto-starts Deep AI. Hybrid auto-triage write only when TG Correct/VALID
    and ticket is open.

    When tag+testcase_id already have a saved intelligent_triage analysis, return
    that cached payload unless force/force_refresh is set.
    """
    try:
        request_data = request.get_json(force=True) or {}
        test_result = request_data.get("test_result") or request_data
        if not test_result or not (
            test_result.get("testcase_name") or test_result.get("testcase_id")
        ):
            return jsonify({"success": False, "error": "test_result is required"}), 400

        tag_name = (request_data.get("tag") or test_result.get("tag") or "").strip()
        testcase_id = str(test_result.get("testcase_id") or "")
        force = bool(
            request_data.get("force")
            or request_data.get("force_refresh")
            or request_data.get("rerun")
        )

        if tag_name and testcase_id and not force:
            cached_analysis = _it_get_cached_analysis(tag_name, testcase_id)
            if cached_analysis and (
                cached_analysis.get("triage_analysis")
                or cached_analysis.get("decision")
            ):
                ta = cached_analysis.get("triage_analysis") or {}
                decision = cached_analysis.get("decision") or {}
                glean = (cached_analysis.get("glean_candidates") or {}).get("search") or {}
                tg = cached_analysis.get("triage_genie") or {}
                return jsonify({
                    "success": True,
                    "cached": True,
                    "analysis_type": "first_level_ai",
                    "issue_type": ta.get("issue_type"),
                    "analysis": ta.get("summary"),
                    "recommended_action": ta.get("recommended_action"),
                    "best_matching_ticket": ta.get("best_matching_ticket"),
                    "triage_confidence": ta.get("triage_confidence")
                        or (cached_analysis.get("intermittent_analysis") or {}).get("intermittent_confidence"),
                    "intermittent_confidence": (
                        (cached_analysis.get("intermittent_analysis") or {}).get("intermittent_confidence")
                    ),
                    "tg_ticket_validation": (
                        {**(tg.get("ai_validation") or {}), "ticket": (tg.get("original") or {}).get("ticket")}
                        if tg.get("ai_validation") or (tg.get("original") or {}).get("ticket")
                        else None
                    ),
                    "enriched_tickets": glean.get("candidates") or [],
                    "glean_snippets": glean.get("snippets") or [],
                    "search_source": glean.get("search_source"),
                    "glean_ok": (glean.get("mcp_health") or {}).get("ok"),
                    "mcp_health": cached_analysis.get("mcp_health"),
                    "decision": decision,
                    "intelligent_triage": cached_analysis,
                    "analysis_result": {
                        "analysis_type": "first_level_ai",
                        "confidence": ta.get("triage_confidence"),
                        "triage_confidence": ta.get("triage_confidence"),
                        "intermittent_confidence": (
                            (cached_analysis.get("intermittent_analysis") or {}).get("intermittent_confidence")
                        ),
                    },
                })

        result = _run_first_level_ai_analysis(test_result, run_ai=True)
        payload = build_intelligent_triage_payload(test_result, result)
        analysis = payload["intelligent_triage"]
        decision = payload["decision"]

        # Independent confidences — never average into overall_confidence.
        triage_confidence = payload.get("triage_confidence")
        intermittent_confidence = payload.get("intermittent_confidence")

        result["user_requested"] = True
        result["analysis_result"] = {
            "analysis_type": "first_level_ai",
            # Back-compat field: same as triage_confidence only (not blended).
            "confidence": triage_confidence,
            "triage_confidence": triage_confidence,
            "intermittent_confidence": intermittent_confidence,
        }
        result["intelligent_triage"] = analysis
        result["decision"] = decision
        result["triage_confidence"] = triage_confidence
        result["intermittent_confidence"] = intermittent_confidence
        result["mcp_health"] = analysis.get("mcp_health")
        result["thresholds"] = payload.get("thresholds")
        result["cached"] = False

        # Persist into saved-tag cache when tag provided.
        if tag_name and testcase_id:
            try:
                cached = load_failed_analysis_results(tag_name) or {
                    "tag": tag_name,
                    "results": [],
                    "cursor_ai": {},
                    "intelligent_triage": {},
                }
                cached = persist_analysis_into_tag_payload(cached, testcase_id, analysis)
                save_failed_analysis_results(tag_name, cached)
            except Exception as persist_err:
                logger.warning("Could not persist intelligent_triage for %s: %s", tag_name, persist_err)

        # Hybrid auto-triage write (eligible only).
        auto_write = {
            "attempted": False,
            "applied": False,
            "mode": decision.get("auto_triage_write"),
            "detail": decision.get("auto_triage_write_detail"),
            "error": None,
        }
        apply_auto = request_data.get("apply_auto_triage", True)
        if (
            apply_auto
            and should_auto_write_triage(decision, analysis)
            and testcase_id
        ):
            auto_write["attempted"] = True
            try:
                ticket = (
                    ((analysis.get("triage_genie") or {}).get("original") or {}).get("ticket")
                    or result.get("best_matching_ticket")
                    or ""
                )
                comment = (
                    "RegX Intelligent Triage AUTO_TRIAGE: TG validation Correct/VALID, "
                    "ticket open. Linked %s. %s"
                    % (ticket, (result.get("recommended_action") or "")[:400])
                )
                current_username = g.current_user.get("sub", "") if hasattr(g, "current_user") else ""
                user_auth = _get_user_credentials(current_username) if current_username else None
                if not user_auth:
                    auto_write["error"] = "Session credentials unavailable for auto-triage write"
                    decision["auto_triage_write"] = "recommend_only"
                else:
                    update_fields = {
                        "comments": comment,
                        "triaged_by": current_username,
                    }
                    if ticket:
                        update_fields["jira_tickets"] = [ticket]
                    put_payload = {
                        "query": {"_id": {"$in": [{"$oid": testcase_id}]}},
                        "data": {"$set": update_fields},
                        "multi": True,
                    }
                    resp = requests.put(
                        f"{JITA_BASE}/agave_test_results",
                        headers={"Content-Type": "application/json"},
                        json=put_payload,
                        auth=user_auth,
                        verify=False,
                        timeout=30,
                    )
                    if resp.status_code == 200:
                        auto_write["applied"] = True
                        decision["auto_triage_write"] = "applied"
                        analysis["auto_triage"] = {
                            "applied": True,
                            "jira_tickets": [ticket] if ticket else [],
                            "comment": comment,
                            "applied_at": datetime.utcnow().isoformat() + "Z",
                            "applied_by": current_username,
                            "mode": "hybrid_auto",
                        }
                        analysis["decision"] = decision
                        result["intelligent_triage"] = analysis
                        result["decision"] = decision
                    else:
                        auto_write["error"] = resp.text or ("HTTP %s" % resp.status_code)
                        decision["auto_triage_write"] = "recommend_only"
            except Exception as write_err:
                auto_write["error"] = str(write_err)[:300]
                decision["auto_triage_write"] = "recommend_only"
                logger.warning("Hybrid auto-triage write failed: %s", write_err)

        result["auto_triage_write"] = auto_write
        # Explicit: Deep AI never auto-started from First Level.
        result["deep_ai_recommended"] = bool(decision.get("deep_ai_recommended"))
        result["deep_ai_started"] = False
        return jsonify(result)
    except Exception as e:
        logger.error("Error in first level AI analysis: %s", e, exc_info=True)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/mcp/regression/failed-analysis/glean-ai-validate", methods=["POST"])
@jwt_required
def glean_ai_validate_candidate():
    """Human-triggered AI validation of a single Glean candidate (not auto for all)."""
    try:
        body = request.get_json(force=True) or {}
        ticket = (body.get("ticket") or "").strip()
        test_result = body.get("test_result") or {}
        tag_name = (body.get("tag") or "").strip()
        testcase_id = str(
            body.get("testcase_id")
            or test_result.get("testcase_id")
            or ""
        )
        if not ticket:
            return jsonify({"success": False, "error": "ticket is required"}), 400

        exception_summary = test_result.get("exception_summary") or body.get("exception_summary") or ""
        exception = test_result.get("exception") or body.get("exception") or ""
        testcase_name = test_result.get("testcase_name") or body.get("testcase_name") or ""

        # Reuse TG detailed validation heuristics against this candidate.
        validation = validate_triage_genie_ticket_detailed(
            ticket, exception_summary, exception, [{"ticket": ticket}]
        )
        validation["trigger"] = "human"
        validation["match_verdict"] = validation.get("verdict")

        # Optional short AI confirmation (best-effort; never fabricate tickets).
        ai_note = ""
        try:
            system_prompt = (
                "You validate whether a Jira ticket matches a test failure. "
                "Respond with JSON only: "
                '{"verdict":"Correct|Partial|Incorrect","reason":"...","confidence":0.0}. '
                "Do not invent ticket IDs."
            )
            user_content = "\n".join([
                "Testcase: %s" % testcase_name,
                "Exception: %s" % (exception_summary or "")[:1500],
                "Candidate ticket: %s" % ticket,
                "Jira summary: %s" % (validation.get("jira_summary") or ""),
                "Heuristic verdict: %s — %s" % (validation.get("verdict"), validation.get("reason")),
            ])
            ai_raw = _call_ai_chat(system_prompt, user_content, max_tokens=400)
            parsed = _parse_first_level_ai_json(ai_raw)
            if parsed.get("verdict") in ("Correct", "Partial", "Incorrect"):
                validation["verdict"] = parsed["verdict"]
                validation["match_verdict"] = parsed["verdict"]
                if parsed.get("reason"):
                    validation["reason"] = parsed["reason"]
                if parsed.get("confidence") is not None:
                    validation["ai_confidence"] = parsed["confidence"]
            ai_note = (ai_raw or "")[:500]
        except Exception as ai_err:
            validation["ai_error"] = str(ai_err)[:200]
            # Do not fabricate a stronger verdict on AI failure.
            logger.warning("Glean AI validate chat failed: %s", ai_err)

        validation["ai_note"] = ai_note

        # Persist into intelligent_triage map when tag+testcase known.
        analysis = None
        if tag_name and testcase_id:
            cached = load_failed_analysis_results(tag_name) or {
                "tag": tag_name,
                "results": [],
                "cursor_ai": {},
                "intelligent_triage": {},
            }
            existing = (cached.get("intelligent_triage") or {}).get(testcase_id) or {}
            if not existing:
                # Seed from a lightweight first-level search so candidates exist.
                fl = _run_first_level_ai_analysis(test_result or body, run_ai=False)
                seeded = build_intelligent_triage_payload(test_result or body, fl)
                existing = seeded["intelligent_triage"]
            analysis = merge_glean_ai_validation(existing, validation, ticket=ticket)
            cached = persist_analysis_into_tag_payload(cached, testcase_id, analysis)
            save_failed_analysis_results(tag_name, cached)

        return jsonify({
            "success": True,
            "ticket": ticket,
            "ai_validation": validation,
            "intelligent_triage": analysis,
            "persisted": bool(analysis),
        })
    except Exception as e:
        logger.error("Error in glean-ai-validate: %s", e, exc_info=True)
        return jsonify({"success": False, "error": str(e)}), 500


